def is_fubon_new_whole_life_cancer_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-050"
        and product_id in FUBON_NEW_WHOLE_LIFE_CANCER_RIDER_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "") == f"{product_id}-A.pdf"
    )


