    if any(signal not in text for signal in required_signals):
        return None

    source_ref = "保單條款第 1-6 頁、附表一保險金給付表"
    unit_note = "每一投保單位按附表一金額計算；實際給付為每單位金額乘以保單所載投保單位數。"
