                calculation_basis="reimbursement_with_cap",
                amount_role="limit",
                limit_scope="per_day",
                conditions=[non_nhi_condition, outpatient_deductible_condition, "同一保單年度給付門診醫療費用保險金合計以 20 日門診為限"],
