                        f"保單條款{article_refs[THREE_PLAN_REQUIRED_HEADINGS['benefit_limit']]}及{table_ref}",
                        calculation_basis="reimbursement_with_cap",
                        amount_role="limit",
                        limit_scope="annual",
                        aggregation_rule="cumulative_cap",
