def is_fubon_nhsd_fixed_inpatient_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        document.get("batch_id") == "tii-life-050"
        and product_id in FUBON_NHSD_FIXED_INPATIENT_PRODUCT_VERSIONS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "") == f"{product_id}-A.pdf"
    )


def parse_fubon_nhsd_fixed_inpatient_surgery_unit(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_fubon_nhsd_fixed_inpatient_strict_source(document):
        return None

    product_id = str(document.get("product_id") or "")
    version = FUBON_NHSD_FIXED_INPATIENT_PRODUCT_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    compact_text = compact_table_text(text)
    required_signals = [
        "富邦人壽新健康醫療費用定額給付健康保險附約",
        "給付項目住院醫療日額保險金、加護病房或燒燙傷中心保險金、住院手術醫療保險金、出院居家療養保險金、長期住院補助保險金",
        "住院醫療保險金日額」乘以實際住院醫療日數",
        "一點二五1.25倍乘以實際居住加護病房或燒燙傷中心日數",
        "每次手術醫療保險金」乘以被保險人所投保之單位數",
        "給付總額最高以所投保之「住院醫療保險金日額」的七十五倍為限",
        "實際住院日數超過六日者",
        "實際住院日數乘以所投保之「住院醫療保險金日額」的四分之一",
        "實際住院日數超過三十日",
        "超過之日數乘以所投保之「住院醫療保險金日額」的四分之一",
        "出院後十四日內再次住院",
        "各等級每次手術醫療保險金給付表新臺幣元/每單位手術等級12345678每次手術醫療保險金350750150020003000450060007500",
    ]
    if any(signal not in compact_text for signal in required_signals):
        return None

    post_expiry_signal = (
        "倘被保險人係於本附約有效期間屆滿後出院者"
        "本公司就再次住院部分不予給付保險金"
    )
    if (post_expiry_signal in compact_text) != version[
        "post_expiry_readmission_excluded"
    ]:
        return None

    source_ref = "保單條款第八、九條及外科手術分類表"
    daily_amount_note = (
        "條款未將住院醫療保險金日額固定為每單位金額，請依保單首頁或批註輸入實際日額。"
    )
    common_conditions = [
        "因條款所定義之疾病或傷害住院診療。",
        "同一疾病、傷害或其併發症於出院後 14 日內再次住院，視為同一次住院。",
    ]
    if version["post_expiry_readmission_excluded"]:
        common_conditions.append(
            "於附約有效期間屆滿後出院者，再次住院部分不予給付。"
        )

    entries = [
        coverage_entry(
            "hospital-daily-benefit",
            "住院醫療日額保險金",
            None,
            "hospital_daily_amount",
            f"{daily_amount_note}每日給付等於保單記載日額；同一保單年度最多給付 365 日。",
            source_ref,
            calculation_basis="unknown",
            amount_role="payout",
            limit_scope="per_day",
            multiplier=1,
            conditions=common_conditions,
        ),
        coverage_entry(
            "icu-or-burn-center-daily-benefit",
            "加護病房或燒燙傷中心保險金",
            None,
            "hospital_daily_amount",
            f"{daily_amount_note}每日另按日額 1.25 倍給付；加護病房與燒燙傷中心各以同一保單年度 365 日為限，同一日只能擇一。",
            source_ref,
            calculation_basis="unknown",
            amount_role="payout",
            limit_scope="per_day",
            aggregation_rule="choose_one",
            multiplier=1.25,
            conditions=common_conditions,
        ),
    ]
    entries.extend(
        coverage_entry(
            f"inpatient-surgery-grade-{grade}",
            f"住院手術醫療保險金（第 {grade} 級）",
            amount,
            "per_unit",
            f"第 {grade} 級手術每一投保單位 {amount:,} 元；實際手術項目須依條款外科手術分類表確認。",
            source_ref,
            calculation_basis="per_unit",
            amount_role="payout",
            limit_scope="per_surgery",
            conditions=[
                *common_conditions,
                "同一次住院接受多項手術時分別計算，但仍受同次住院手術給付總上限限制。",
                "同一次手術、同一位置接受一項器官以上手術時，只按附表最高等級的一項計算。",
                "不在附表內的手術須由保險公司與被保險人協議比照，不可由系統自行推定等級。",
            ],
        )
        for grade, amount in enumerate(
            FUBON_NHSD_SURGERY_GRADE_AMOUNTS,
            start=1,
        )
    )
    entries.extend(
        [
            coverage_entry(
                "inpatient-surgery-aggregate-cap",
                "同次住院手術給付總上限",
                None,
                "hospital_daily_amount",
                "同一次住院多項手術分別計算，合計最高為保單記載住院醫療保險金日額的 75 倍。",
                source_ref,
                calculation_basis="unknown",
                amount_role="limit",
                limit_scope="per_hospitalization",
                aggregation_rule="cumulative_cap",
                multiplier=75,
                conditions=common_conditions,
            ),
            coverage_entry(
                "home-recovery-daily-benefit",
                "出院居家療養保險金",
                None,
                "hospital_daily_amount",
                f"{daily_amount_note}實際住院超過 6 日時，按全部實際住院日數、每日為日額的四分之一給付；每次最多 90 日。",
                source_ref,
                calculation_basis="unknown",
                amount_role="payout",
                limit_scope="per_day",
                multiplier=0.25,
                conditions=common_conditions,
            ),
            coverage_entry(
                "long-hospital-daily-subsidy",
                "長期住院補助保險金",
                None,
                "hospital_daily_amount",
                f"{daily_amount_note}實際住院超過 30 日時，僅就超過 30 日的日數、每日為日額的四分之一給付；每次最多 150 日。",
                source_ref,
                calculation_basis="unknown",
                amount_role="payout",
                limit_scope="per_day",
                multiplier=0.25,
                conditions=common_conditions,
            ),
        ]
    )

    return {
        "selection_type": "unit",
        "input_mode": "unit",
        "selection_source": "terms",
        "selection_label": "住院手術投保單位數",
        "selection_guidance": (
            "請輸入保單記載的正整數投保單位數；單位數只換算手術給付。"
            "住院日額相關保障另依保單首頁或批註所載日額計算。"
        ),
        "version_characteristics": {
            "terms_revision": version["terms_revision"],
            "disease_initial_waiting_days": 30,
            "hospital_daily_annual_days_limit": 365,
            "icu_or_burn_daily_multiplier": 1.25,
            "icu_or_burn_annual_days_limit": 365,
            "icu_and_burn_same_day_choose_one": True,
            "surgery_grade_count": 8,
            "surgery_total_cap_daily_multiplier": 75,
            "home_recovery_min_hospital_days": 7,
            "home_recovery_days_limit": 90,
            "long_hospital_min_days": 31,
            "long_hospital_days_limit": 150,
            "same_hospital_readmission_days": 14,
            "post_expiry_readmission_excluded": version[
                "post_expiry_readmission_excluded"
            ],
            "unlisted_surgery_requires_agreement": True,
        },
        "coverage_entries": entries,
    }


