def is_fubon_whole_life_medical_health_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FUBON_WHOLE_LIFE_MEDICAL_HEALTH_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-050"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def fubon_whole_life_medical_health_semantic_phase(
    revision: int,
) -> str:
    if revision <= 2:
        return "legacy-one-to-three-disability-waiver"
    if revision <= 4:
        return "expanded-one-to-six-disability-waiver"
    if revision <= 8:
        return "full-and-two-to-six-disability-waiver"
    if revision == 9:
        return "updated-funeral-limit"
    if revision <= 11:
        return "minor-paid-premium-interest-transition"
    if revision <= 13:
        return "explicit-minor-death-rule"
    return "explicit-minor-death-rule-with-warning"


