def is_farglory_new_cancer_whole_life_health_99_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FARGLORY_NEW_CANCER_WHOLE_LIFE_HEALTH_99_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-080"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def farglory_new_cancer_whole_life_health_99_semantic_phase(
    revision: int,
) -> str:
    if revision <= 6:
        return (
            "legacy-cancer-classification-with-"
            "reinstatement-waiting"
        )
    if revision <= 8:
        return (
            "legacy-cancer-classification-"
            "inception-waiting-only"
        )
    return (
        "standardized-three-tier-"
        "inception-waiting-only"
    )


