def is_china_new_kangjian_whole_life_cancer_health_97_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = (
        CHINA_NEW_KANGJIAN_WHOLE_LIFE_CANCER_HEALTH_97_VERSIONS.get(
            product_id
        )
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-026"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def china_new_kangjian_whole_life_cancer_health_97_semantic_phase(
    revision: int,
) -> str:
    if revision <= 1:
        return "legacy-high-unit-schedule-basic-termination"
    if revision <= 3:
        return (
            "legacy-high-unit-schedule-"
            "waiver-protected-termination"
        )
    if revision == 4:
        return "expanded-low-unit-schedule"
    if revision <= 7:
        return (
            "expanded-low-unit-schedule-"
            "day-hospital-excluded"
        )
    if revision == 8:
        return (
            "expanded-low-unit-schedule-"
            "inception-waiting-only"
        )
    if revision == 9:
        return (
            "modern-pathology-definition-"
            "inception-waiting-only"
        )
    return (
        "modern-pathology-definition-"
        "medical-review"
    )


