def is_china_new_lohas_whole_life_medical_health_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = CHINA_NEW_LOHAS_WHOLE_LIFE_MEDICAL_HEALTH_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-026"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def china_new_lohas_whole_life_medical_health_document_code(
    revision: int,
) -> str:
    if revision <= 1:
        return "ANHRL"
    if revision <= 4:
        return "BNHRL"
    if revision <= 6:
        return "CNHRL"
    if revision <= 9:
        return "DNHRL"
    if revision == 10:
        return "ENHRL"
    if revision == 11:
        return "FNHRL"
    return "GNHRL"


def china_new_lohas_whole_life_medical_health_semantic_phase(
    revision: int,
) -> str:
    if revision <= 1:
        return "anhrl-six-hour-treatment-and-emergency-transport"
    if revision <= 4:
        return "bnhrl-separated-six-hour-treatment-and-emergency-transport"
    if revision <= 7:
        return "cnhrl-dnhrl-inpatient-only-legacy-capacity-wording"
    if revision <= 9:
        return "dnhrl-inpatient-only-guardianship-wording"
    return "modern-inpatient-only-medical-review"


