def parse_china_new_lohas_whole_life_medical_health_plan(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_china_new_lohas_whole_life_medical_health_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = CHINA_NEW_LOHAS_WHOLE_LIFE_MEDICAL_HEALTH_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "樂活終身醫療健康保險",
        "累積總給付金額限制與契約的終止",
        "加護病房費用保險金之給付",
        "住院手術費用保險金之給付",
        "住院手術看護保險金之給付",
        "門診手術費用保險金之給付",
        "住院保險金日額",
        "三千倍",
        "一點零六倍",
        "計劃5計劃10計劃15計劃20計劃25計劃30",
        "每日住院日額保險金",
        "手術名稱及費用表",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None
    if (
        version["source_text_extractor"] != "windows_ocr"
        and (
            "住院日額保險金之給付" not in dense_text
            or "5001,0001,5002,0002,5003,000"
            not in dense_text
        )
    ):
        return None
    if (
        version["source_text_extractor"] == "windows_ocr"
        and (
            "給付項目每日住院日額保險金" not in dense_text
            or "緊急醫療轉送保險金1,0002,0003,0004,0005,0006,000"
            not in dense_text
        )
    ):
        return None
    if any(
        f"{rate}%" not in dense_text
        for rate in CHINA_NEW_LOHAS_SURGERY_RATES
    ):
        return None

    revision = int(version["revision"])
    document_code = (
        china_new_lohas_whole_life_medical_health_document_code(
            revision
        )
    )
    phase_checks = (
        (f"【{document_code}】" in dense_text, True),
        (
            "持續治療達六小時" in dense_text,
            revision <= 4,
        ),
        (
            "緊急醫療轉送保險金之給付" in dense_text,
            revision <= 4,
        ),
        (
            "精神障礙或其他心智缺陷" in dense_text,
            revision <= 7,
        ),
        (
            "受監護宣告尚未撤銷者" in dense_text,
            revision >= 8,
        ),
        (
            "徵詢其他醫師之醫學專業意見" in dense_text,
            revision >= 10,
        ),
    )
    if any(actual is not expected for actual, expected in phase_checks):
        return None

    claim_event_inputs = [
        "china_new_lohas_eligible_hospital_daily_days",
        "intensive_care_days",
        "surgery_total_benefit_rate_percent",
        "outpatient_surgery_count",
        "cumulative_medical_benefit_paid_amount",
        "paid_premium_total",
        "death_benefit_status",
        "death_age_band_status",
        "unexpired_premium_refund_amount",
    ]
    return {
        "selection_type": "plan",
        "input_mode": "plan",
        "selection_source": "terms",
        "selection_label": "保險計畫",
        "selection_guidance": (
            "請依保單首頁選擇計劃 5、10、15、20、25 或 30；本商品不輸入單位數。"
            "住院與手術試算再依診斷書、這個 product ID 的手術附表及既往理賠填寫事件狀態。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "china-new-lohas-whole-life-medical-health"
            ),
            "family_fingerprint": "89299f1a6790f8ec920e878e",
            "company_group": "china_life",
            "source_batch_id": "tii-life-026",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                china_new_lohas_whole_life_medical_health_semantic_phase(
                    revision
                )
            ),
            "document_code": document_code,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "plan_names": [
                f"計劃 {plan_number}"
                for plan_number in CHINA_NEW_LOHAS_PLAN_DAILY_AMOUNTS
            ],
            "plan_daily_amounts": {
                f"plan-{plan_number}": daily_amount
                for plan_number, daily_amount
                in CHINA_NEW_LOHAS_PLAN_DAILY_AMOUNTS.items()
            },
            "disease_waiting_days": 30,
            "reinstatement_waiting_days": 30,
            "same_hospital_readmission_days": 14,
            "six_hour_treatment_qualifies": revision <= 4,
            "emergency_transport_benefit_available": revision <= 4,
            "hospital_daily_max_days_per_stay": 365,
            "intensive_care_multiplier": 2,
            "intensive_care_max_days_per_stay": 365,
            "inpatient_surgery_base_multiplier": 10,
            "surgery_schedule_rates_percent": list(
                CHINA_NEW_LOHAS_SURGERY_RATES
            ),
            "same_stay_surgery_cap_multiplier": 50,
            "inpatient_surgery_nursing_multiplier": 5,
            "outpatient_surgery_multiplier": 3,
            "outpatient_repeat_window_days": 14,
            "lifetime_medical_cap_multiplier": 3000,
            "terminal_return_age": 99,
            "terminal_return_paid_premium_rate_percent": 106,
            "death_paid_premium_rate_percent": 106,
            "minor_death_rule_present": True,
            "medical_review_opinion_revision": revision >= 10,
            "burn_unit_benefit_present": False,
            "pre_post_outpatient_benefit_present": False,
            "major_surgery_benefit_present": False,
            "discharge_recuperation_benefit_present": False,
            "long_term_hospital_benefit_present": False,
            "premium_waiver_available": False,
            "no_cash_surrender_value": True,
            "required_policy_inputs": ["plan_name"],
            "claim_event_inputs": claim_event_inputs,
            "amount_presentation": (
                "selected_plan_with_claim_event_and_terminal_state"
            ),
        },
        "plan_options": [
            {
                "value": f"plan-{plan_number}",
                "label": f"計劃 {plan_number}",
                "coverage_entries": (
                    china_new_lohas_whole_life_medical_health_entries(
                        revision=revision,
                        daily_amount=daily_amount,
                    )
                ),
            }
            for plan_number, daily_amount
            in CHINA_NEW_LOHAS_PLAN_DAILY_AMOUNTS.items()
        ],
    }


