def parse_farglory_health_jiujiu_surgical_medical_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_farglory_health_jiujiu_surgical_medical_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = FARGLORY_HEALTH_JIUJIU_SURGICAL_MEDICAL_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["dense_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)

    revision = int(version["revision"])
    common_signals = (
        "遠雄人壽健康久久手術醫療終身保險附約",
        "手術醫療保險金額」係指",
        "門診手術醫療保險金的給付",
        "一千二百倍",
        "一點一倍",
        "手術項目倍數表",
        "50局部皮瓣(2公分以上)8",
        "1235顱底瘤手術100",
        "1464臍腸系膜瘻管切除40",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None
    if revision <= 1:
        if (
            "心神喪失或精神耗弱" not in dense_text
            or "實際年齡未滿十五足歲" in dense_text
        ):
            return None
    elif revision <= 10:
        if (
            "實際年齡未滿十五足歲" not in dense_text
            or "精神障礙或其他心智缺陷" not in dense_text
            or "受監護宣告尚未撤銷" in dense_text
        ):
            return None
    elif (
        "實際年齡未滿十五足歲" not in dense_text
        or "受監護宣告尚未撤銷" not in dense_text
        or "完全失能" not in dense_text
    ):
        return None

    disability_term = "完全失能" if revision >= 11 else "全殘廢"
    minor_death_rule = (
        "paid_premium_refund_under_15_or_paid_premium_death_benefit_before_age_16_anniversary"
        if revision >= 2
        else "legacy_general_death_formula"
    )
    funeral_status_rule = (
        "guardianship_declaration"
        if revision >= 11
        else "mental_incapacity"
        if revision >= 2
        else "minor_under_14_or_mental_incapacity"
    )
    source_ref = (
        "保單條款第四、第五及第十至十五條；附表手術項目倍數表"
    )
    required_policy_inputs = [
        "face_amount",
        "surgery_benefit_multiplier",
        "premium_total_amount",
        "cumulative_surgery_benefit_paid_amount",
        "death_benefit_status",
        *(["death_age_band_status"] if revision >= 2 else []),
    ]
    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": "手術醫療保險金額",
        "selection_guidance": "請輸入保單首頁或最新批註記載的手術醫療保險金額；試算手術給付時再輸入本次手術附表倍數，身故或祝壽則依保單填入應繳保險費總和與累計手術給付。",
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "farglory-health-jiujiu-surgical-medical"
            ),
            "company_group": "farglory_life",
            "source_batch_id": "tii-life-080",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["dense_text_sha256"],
            "source_text_extractor": version["source_text_extractor"],
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "disease_waiting_days": 30,
            "face_amount_required": True,
            "surgery_multiplier_required": True,
            "surgery_table_item_count": 1464,
            "surgery_table_multiplier_min": 1,
            "surgery_table_multiplier_max": 100,
            "surgery_table_unlisted_requires_agreement": True,
            "cumulative_medical_cap_multiplier": 1200,
            "maturity_age": 99,
            "premium_total_rate_percent": 110,
            "cumulative_surgery_paid_required": True,
            "death_benefit_formula": (
                "scheduled_premium_total_to_earlier_of_death_or_payment_end_times_1_10_minus_cumulative_surgery_benefits"
            ),
            "maturity_benefit_formula": (
                "scheduled_premium_total_to_payment_end_times_1_10_minus_cumulative_surgery_benefits"
            ),
            "minor_death_rule": minor_death_rule,
            "funeral_status_rule": funeral_status_rule,
            "disability_term": disability_term,
            "non_participating_policy": True,
            "no_cash_surrender_value": True,
            "required_policy_inputs": required_policy_inputs,
        },
        "coverage_entries": (
            farglory_health_jiujiu_surgical_medical_entries(
                revision=revision,
                source_ref=source_ref,
            )
        ),
    }


