def is_farglory_yongan_surgical_medical_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-080"
        and product_id in FARGLORY_YONGAN_SURGICAL_MEDICAL_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == f"{product_id.lower()}-a.pdf"
    )


def farglory_yongan_semantic_phase(revision: int) -> str:
    if revision == 0:
        return "legacy_under14_funeral_rule"
    if revision <= 2:
        return "minor_refund_mental_capacity_rule"
    if revision <= 7:
        return "premium_rate_table_definition"
    if revision == 8:
        return "alternate_communication_method"
    if revision == 9:
        return "surgery_schedule_revision"
    if revision == 10:
        return "guardianship_declaration_rule"
    return "newborn_screening_waiting_exception"


