def parse_farglory_yongan_surgical_medical_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_farglory_yongan_surgical_medical_strict_source(document):
        return None
    product_id = str(document.get("product_id") or "")
    version = FARGLORY_YONGAN_SURGICAL_MEDICAL_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version["dense_text_sha256"]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "遠雄人壽永安手術醫療終身保險",
        "住院手術療養保險金",
        "重大手術慰問保險金",
        "意外創傷縫合處置保險金",
        "無理賠紀錄增值保險金",
        "一千二百倍",
        "六十倍(含)以上",
        "傷口最大者",
        "本險無解約金",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None

    revision = int(version["revision"])
    semantic_phase = farglory_yongan_semantic_phase(revision)
    if revision == 0:
        if (
            "未滿十四足歲之未成年人" not in dense_text
            or "所繳保險費的退還" in dense_text
        ):
            return None
    else:
        if (
            "所繳保險費的退還" not in dense_text
            or "實際年齡未滿十五足歲前身故" not in dense_text
        ):
            return None
        if revision <= 2:
            if "已繳之表訂保險費" not in dense_text:
                return None
        elif "保險費率表所載金額為基礎" not in dense_text:
            return None
        if revision >= 8 and "書面或其他約定方式" not in dense_text:
            return None
        if revision >= 9 and (
            "252肌腱移植術-單腱5" not in dense_text
            or "編號252及253每增加一條加2" not in dense_text
        ):
            return None
        if revision >= 10:
            if "受監護宣告尚未撤銷者" not in dense_text:
                return None
        elif "精神障礙或其他心智缺陷" not in dense_text:
            return None
        if revision >= 11:
            if (
                "投保時之保險年齡為零歲" not in dense_text
                or "新生兒先天性代謝異常疾病篩檢項目"
                not in dense_text
            ):
                return None
        elif (
            "新生兒先天性代謝異常疾病篩檢項目"
            in dense_text
        ):
            return None

    required_policy_inputs = [
        "face_amount",
        "surgery_benefit_multiplier",
        "surgery_care_setting",
        "wound_suture_benefit_rate_percent",
        "current_articles_11_to_14_benefit_total_amount",
        "no_claim_bonus_rate_percent",
        "cumulative_medical_benefit_paid_amount",
        "premium_total_amount",
        "death_benefit_status",
        *(["death_age_band_status"] if revision >= 1 else []),
    ]
    source_ref = "條款第十一條至第十八條及手術、意外創傷縫合附表"
    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": "手術醫療保險金額",
        "selection_guidance": "請輸入保單首頁或最新批註記載的手術醫療保險金額；查看各項給付時，再依手術附表、住院狀態、傷口大小、無理賠期間及累計理賠紀錄填入對應狀態。",
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "farglory-yongan-surgical-medical-whole-life"
            ),
            "company_group": "farglory_life",
            "source_batch_id": "tii-life-080",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["dense_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "machine_readable_exact_hash_pymupdf_recovery"
                if version["source_text_extractor"] == "pymupdf"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "disease_waiting_days": 30,
            "surgery_care_scope": "hospital_or_clinic",
            "outpatient_surgery_separate_benefit": False,
            "surgery_table_item_count": 1461,
            "surgery_schedule_revision": (
                "original"
                if revision <= 8
                else "item_252_253_revision"
            ),
            "surgery_table_unlisted_requires_agreement": True,
            "inpatient_recuperation_multiplier": 3,
            "major_surgery_minimum_multiplier": 60,
            "major_surgery_additional_rate_percent": 50,
            "wound_suture_rate_options_percent": [50, 100],
            "no_claim_bonus_rate_schedule_percent": {
                "under_3_years": 0,
                "3_to_under_4_years": 20,
                "4_to_under_5_years": 30,
                "5_to_under_6_years": 40,
                "6_years_or_more": 50,
            },
            "cumulative_medical_cap_multiplier": 1200,
            "maturity_age": 99,
            "premium_total_rate_percent": 110,
            "death_benefit_formula": (
                "scheduled_premium_total_to_earlier_of_death_or_payment_end_times_1_10_minus_cumulative_articles_11_to_15_benefits"
            ),
            "maturity_benefit_formula": (
                "scheduled_premium_total_to_payment_end_times_1_10_minus_cumulative_articles_11_to_15_benefits"
            ),
            "minor_death_rule": (
                "legacy_under_14_funeral_conversion"
                if revision == 0
                else "paid_premium_refund_under_15_or_paid_premium_death_benefit_before_age_16_anniversary"
            ),
            "paid_premium_definition": (
                "legacy_not_separately_defined"
                if revision == 0
                else "paid_scheduled_premium"
                if revision <= 2
                else "premium_rate_table_amount"
            ),
            "funeral_status_rule": (
                "minor_under_14_or_mental_incapacity"
                if revision == 0
                else "mental_incapacity"
                if revision <= 9
                else "guardianship_declaration"
            ),
            "contract_review_period_days": (
                3 if revision >= 3 else None
            ),
            "alternate_communication_method_available": (
                revision >= 8
            ),
            "newborn_screening_waiting_exception": revision >= 11,
            "newborn_screening_exception_requires_issue_age_zero": (
                revision >= 11
            ),
            "premium_waiver_benefit_present": False,
            "non_participating_policy": True,
            "no_cash_surrender_value": True,
            "required_policy_inputs": required_policy_inputs,
        },
        "coverage_entries": (
            farglory_yongan_surgical_medical_entries(
                revision=revision,
                source_ref=source_ref,
            )
        ),
    }


