def is_taiwan_overseas_sudden_illness_medical_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-008"
        and product_id
        in TAIWAN_OVERSEAS_SUDDEN_ILLNESS_MEDICAL_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == f"{product_id}-a.pdf".lower()
    )


