def parse_taiwan_overseas_sudden_illness_medical_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_taiwan_overseas_sudden_illness_medical_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = TAIWAN_OVERSEAS_SUDDEN_ILLNESS_MEDICAL_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version["source_text_sha256"]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    required_signals = (
        "海外突發疾病醫療健康保險附約",
        "海外突發疾病住院醫療保險金",
        "海外突發疾病急診醫療保險金",
        "海外突發疾病門診醫療保險金",
        "一百八十日",
        "百分之二十",
        "千分之五",
        "出院後十四日內",
        "同一醫院再次住院",
        "調整係數",
    )
    if any(signal not in dense_text for signal in required_signals):
        return None

    revision = version["revision"]
    post_expiry_signal = "附約有效期間屆滿後出院"
    if (post_expiry_signal in dense_text) is not (revision >= 9):
        return None
    ocr_evidence_path = (
        "work/tii-benefit-candidates/"
        f"tii-life-008-taiwan-overseas-sudden-illness-medical-{product_id}-ocr-evidence.json"
        if version["source_text_extractor"] == "windows_ocr"
        else None
    )
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "海外醫療保單限額與就醫地區",
        "selection_guidance": (
            "請輸入保單首頁或最新批註記載的海外突發疾病實支實付住院醫療保險金限額，"
            "再選擇本次海外就醫地區；系統會顯示住院、每次急診及每日門診的條款上限。"
            "實際理賠仍以符合條款的醫療費用與上限取低。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "taiwan-overseas-sudden-illness-medical"
            ),
            "company_group": "taiwan_life",
            "source_batch_id": "tii-life-008",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                "post_expiry_readmission_exclusion"
                if revision >= 9
                else "original_readmission_aggregation"
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version["source_text_extractor"],
            "source_text_quality": (
                "font_encoded_visual_verified"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "ocr_evidence_path": ocr_evidence_path,
            "currency_basis": "twd",
            "overseas_scope": "treatment_outside_taiwan",
            "return_to_taiwan_medical_coverage": False,
            "sudden_illness_lookback_days": 180,
            "inpatient_coverage_days": 180,
            "emergency_limit_percent": 20,
            "outpatient_daily_limit_percent": 0.5,
            "region_adjustment_percent": {
                "north_america": 300,
                "europe_australia_new_zealand_japan": 150,
                "other_overseas_regions": 100,
            },
            "same_illness_readmission_days": 14,
            "same_hospital_required": True,
            "same_illness_hospitalization_aggregation": (
                "same_illness_or_complication_same_hospital_within_14_days"
            ),
            "post_expiry_readmission_excluded": revision >= 9,
            "claim_currency_conversion_basis": (
                "taiwan_bank_closing_spot_selling_rate_on_expense_payment_date"
            ),
            "required_policy_inputs": [
                "reimbursement_limit",
                "overseas_medical_region_factor_percent",
            ],
        },
        "coverage_entries": (
            taiwan_overseas_sudden_illness_medical_entries()
        ),
    }


