def farglory_premium_waiver_rider_file_name(product_id: str) -> str:
    return (
        "216341R12B026-A.pdf"
        if product_id == "216341R12B02600"
        else f"{product_id}-A.pdf"
    )


def is_farglory_premium_waiver_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-080"
        and product_id in FARGLORY_PREMIUM_WAIVER_RIDER_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == farglory_premium_waiver_rider_file_name(product_id).lower()
    )


def farglory_premium_waiver_rider_entries(
    *,
    revision: int,
    disability_term: str,
    disability_levels: str,
    source_ref: str,
) -> list[dict[str, Any]]:
    latest_formula_version = revision == 18
    waiver_until = (
        "本附約保險期間屆滿"
        if latest_formula_version
        else "主契約繳費期滿"
    )
    waiver_scope = (
        "主契約、本附約及其他附約"
        if latest_formula_version
        else "主契約及附加於主契約的所有附約（含本附約）"
    )
    trigger_description = (
        f"被保險人於附約有效期間內身故、符合完全{disability_term}、"
        f"罹患條款特定傷病，或因疾病／意外致成第二至第六級{disability_term}之一"
    )
    entries = [
        coverage_entry(
            "future-premium-waiver",
            f"身故、特定傷病或{disability_term}豁免保險費",
            None,
            "policy_premium",
            (
                f"{trigger_description}時，豁免{waiver_scope}未到期各期保險費"
                f"至{waiver_until}；輸入未到期保費合計可估算非現金保障效果。"
            ),
            source_ref,
            calculation_basis="waiver",
            amount_role="premium_waiver",
            limit_scope="per_policy",
            aggregation_rule="choose_one",
            unit_key="remaining_premium_amount",
            policy_state_keys=["remaining_premium_amount"],
            result_kind="non_cash_effect",
            amount_stage="non_cash_estimate",
            conditions=[
                trigger_description + "。",
                "疾病所致事故須經附約生效日起三十日等待期間；意外傷害事故不受等待期間限制。",
                f"本版本失能／殘廢豁免範圍為第 {disability_levels} 級。",
                "若本附約被保險人與主契約被保險人為同一人，須依附約終止條款及主契約事故狀態確認實際豁免範圍。",
                "豁免後不得任意變更條款所列險種、保額、單位、計畫、繳別或繳費年期。",
                "此項為未來保費豁免效果，不是現金保險金。",
            ],
        )
    ]
    if latest_formula_version:
        entries.extend(
            [
                coverage_entry(
                    "current-unexpired-premium-refund",
                    "當期已繳未到期保險費退還",
                    None,
                    "policy_recorded_limit",
                    "符合本版本豁免事故時，按事故日至當期末的剩餘日數比例退還主契約及其他附約當期已繳未到期保險費。",
                    source_ref,
                    calculation_basis="policy_state_amount",
                    amount_role="payout",
                    limit_scope="per_event",
                    aggregation_rule="separate",
                    unit_key="unexpired_premium_refund_amount",
                    policy_state_keys=[
                        "unexpired_premium_refund_amount"
                    ],
                    conditions=[
                        "僅第十八次部分變更版本具有此項明文退還。",
                        "金額須依事故日、繳費週期及各契約當期保費由保單或保險公司按日數比例確認。",
                    ],
                ),
                coverage_entry(
                    "overlapping-waiver-cash-settlement",
                    "重疊豁免保障貼現一次給付",
                    None,
                    "policy_recorded_limit",
                    "本附約已發生豁免事故後，若主契約或其他附約再發生其豁免事故，條款將當年度剩餘日數比例金額及後續年度貼現值一次給付。",
                    source_ref,
                    calculation_basis="policy_state_amount",
                    amount_role="payout",
                    limit_scope="per_policy",
                    aggregation_rule="separate",
                    unit_key="overlapping_waiver_settlement_amount",
                    policy_state_keys=[
                        "overlapping_waiver_settlement_amount"
                    ],
                    conditions=[
                        "須先符合本附約豁免事故，之後主契約或其他附約另發生其約定的豁免事故。",
                        "一次給付包含當年度剩餘未經過日數比例金額，以及後續各年度按本附約預定利率貼現之金額。",
                        "因需保險金額對應關係、剩餘日數、保費時程與預定利率，請輸入保險公司確認的一次給付總額。",
                        "給付後本公司不再負該主契約或其他附約對應部分的豁免責任，並依條款減少本附約保險金額。",
                    ],
                ),
            ]
        )
    return entries


def parse_farglory_premium_waiver_rider_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_farglory_premium_waiver_rider_strict_source(document):
        return None
    product_id = str(document.get("product_id") or "")
    version = FARGLORY_PREMIUM_WAIVER_RIDER_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    if (
        not any(
            title in dense_text
            for title in (
                "遠雄人壽豁免保險費附約",
                "遠雄豁免保險費附約",
            )
        )
        or "特定傷病" not in dense_text
    ):
        return None

    revision = int(version["revision"])
    if revision <= 1:
        if (
            "二、三級殘廢" not in dense_text
            or "主契約繳費期滿" not in dense_text
        ):
            return None
        disability_term = "殘廢"
        disability_levels = "1-3"
        semantic_phase = "legacy_disability_grade_1_to_3"
    elif revision <= 13:
        if (
            "二至六級殘廢" not in dense_text
            or "主契約繳費期滿" not in dense_text
        ):
            return None
        disability_term = "殘廢"
        disability_levels = "1-6"
        semantic_phase = "disability_grade_1_to_6"
    else:
        if "二至六級失能" not in dense_text:
            return None
        disability_term = "失能"
        disability_levels = "1-6"
        semantic_phase = (
            "impairment_grade_1_to_6_with_refund_and_overlap_settlement"
            if revision == 18
            else "impairment_grade_1_to_6"
        )
    if revision == 18:
        latest_signals = (
            "按日數比例退還主契約及其他附約之當期已繳未到期保險費",
            "主契約或其他附約另有豁免保險費之約定",
            "預定利率貼現計算一次給付",
            "至本附約保險期間屆滿",
        )
        if any(signal not in dense_text for signal in latest_signals):
            return None
    elif (
        "按日數比例退還主契約及其他附約之當期已繳未到期保險費"
        in dense_text
    ):
        return None

    latest_formula_version = revision == 18
