def parse_farglory_jinanxin_premium_waiver_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_farglory_jinanxin_premium_waiver_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = FARGLORY_JINANXIN_PREMIUM_WAIVER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    if (
        "遠雄人壽金安心豁免保險費附約" not in dense_text
        and "遠雄金安心豁免保險費附約" not in dense_text
    ) or "特定傷病" not in dense_text:
        return None

    revision = int(version["revision"])
    if revision <= 1:
        if "二、三級殘廢" not in dense_text:
            return None
        disability_term = "殘廢"
        disability_levels = "2-3"
        semantic_phase = "legacy_disability_grade_2_to_3"
    elif revision <= 6:
        if "二至六級殘廢" not in dense_text:
            return None
        disability_term = "殘廢"
        disability_levels = "2-6"
        semantic_phase = "disability_grade_2_to_6"
    elif revision <= 10:
        if (
            "二至六級殘廢" not in dense_text
            or "非經被保險人同意" not in dense_text
        ):
            return None
        disability_term = "殘廢"
        disability_levels = "2-6"
        semantic_phase = (
            "disability_grade_2_to_6_with_insured_consent"
        )
    elif revision <= 14:
        if (
            "二至六級失能" not in dense_text
            or "非經被保險人同意" not in dense_text
        ):
            return None
        disability_term = "失能"
        disability_levels = "2-6"
        semantic_phase = (
            "impairment_grade_2_to_6_with_insured_consent"
        )
    else:
        latest_signals = (
            "二至六級失能",
            "按日數比例退還主契約及其他附約之當期已繳未到期保險費",
            "至本附約保險期間屆滿",
            "主契約或其他附約另有豁免保險費之約定",
            "預定利率貼現計算一次給付",
            "減少本附約保險金額",
            "非經該主契約或其他附約之被保險人同意",
        )
        if any(signal not in dense_text for signal in latest_signals):
            return None
        disability_term = "失能"
        disability_levels = "2-6"
        semantic_phase = (
            "impairment_grade_2_to_6_refund_overlap_and_term_bound"
        )

    latest_formula_version = revision == 15
    if latest_formula_version is not (
        "按日數比例退還主契約及其他附約之當期已繳未到期保險費"
        in dense_text
    ):
        return None
    required_policy_inputs = [
        "remaining_premium_amount",
        *(
            [
                "unexpired_premium_refund_amount",
                "overlapping_waiver_settlement_amount",
            ]
            if latest_formula_version
            else []
        ),
    ]
    source_ref = (
        "保單條款第九條保險費的豁免、第四條特定傷病定義及失能／殘廢附表"
    )
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "剩餘應繳保費與豁免狀態",
        "selection_guidance": (
            "本商品主要提供非現金的未來保費豁免，無須輸入虛構保額；"
            "請依保單填入事故後尚未到期的保費合計。"
            + (
                "第十五次變更版本另請填入按日數比例確認的當期退費，"
                "以及發生重疊豁免時由保險公司確認的貼現一次給付總額。"
                if latest_formula_version
                else ""
            )
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "farglory-jinanxin-premium-waiver-rider"
            ),
            "family_fingerprint": "8b1ce911a76877355b950bc1",
            "company_group": "farglory_life",
            "source_batch_id": "tii-life-080",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "ocr_evidence_path": None,
            "currency_basis": "twd",
            "disease_waiting_days": 30,
            "specified_disease_definition_source": (
                "exact_terms_revision_article_4"
            ),
            "accidental_waiting_exception": True,
            "waiver_event_triggers": [
                "specified_disease",
                (
                    "disease_impairment_grade_2_to_6"
                    if disability_term == "失能"
                    else f"disease_disability_grade_{disability_levels.replace('-', '_to_')}"
                ),
                (
                    "accident_specified_disease_or_impairment_grade_2_to_6"
                    if disability_term == "失能"
                    else "accident_specified_disease_or_disability_grade_"
                    + disability_levels.replace("-", "_to_")
                ),
            ],
            "premium_waiver_disability_levels": disability_levels,
            "disability_term": disability_term,
            "insured_consent_required_for_termination": revision >= 7,
            "premium_waiver_until": (
                "rider_term_end"
                if latest_formula_version
                else "covered_contract_payment_end"
            ),
            "premium_waiver_scope": (
                "main_contract_this_rider_and_other_riders"
                if latest_formula_version
                else "main_contract_and_all_attached_riders_including_this_rider"
            ),
            "premium_waiver_requires_remaining_premium_amount": True,
            "waiver_is_non_cash_effect": True,
            "post_rider_expiry_premiums_resume": (
                latest_formula_version
            ),
            "current_unexpired_premium_refund_available": (
                latest_formula_version
            ),
            "current_unexpired_premium_refund_formula": (
                "current_paid_premiums_times_unexpired_day_ratio"
                if latest_formula_version
                else None
            ),
            "current_unexpired_premium_refund_scope": (
                "main_contract_and_other_riders_excluding_this_rider"
                if latest_formula_version
                else None
            ),
            "overlapping_waiver_settlement_available": (
                latest_formula_version
            ),
            "overlapping_waiver_settlement_formula": (
                "current_year_unexpired_day_ratio_plus_future_annual_amounts_discounted_at_policy_pricing_rate"
                if latest_formula_version
                else None
            ),
            "overlapping_waiver_settlement_requires_insurer_amount": (
                latest_formula_version
            ),
            "non_participating_policy": True,
            "amount_presentation": (
                "remaining_premium_policy_state_with_conditional_cash_components"
            ),
            "required_policy_inputs": required_policy_inputs,
        },
        "coverage_entries": (
            farglory_jinanxin_premium_waiver_entries(
                revision=revision,
                disability_term=disability_term,
                disability_levels=disability_levels,
                source_ref=source_ref,
            )
        ),
    }


