def is_nanshan_group_critical_illness_term_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    file_name = str(document.get("file_name") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-033"
        and product_id in NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and file_name.lower() == f"{product_id.lower()}-a.pdf"
    )


def nanshan_group_critical_illness_term_entries(
    *,
    critical_disease_term: str,
    disability_term: str,
    accidental_waiting_exception_scope: str,
    unexpired_premium_refund: bool,
    critical_page: int,
    death_page: int,
    disability_page: int,
) -> list[dict[str, Any]]:
    refund_condition = (
        ["給付後另按日數比例返還該被保險人已繳的未滿期保險費。"]
        if unexpired_premium_refund
        else []
    )
    accident_exception = (
        "因意外傷害事故所致者，不受六十日等待期間限制。"
        if accidental_waiting_exception_scope == "all_defined_critical_disease"
        else "意外傷害所致癱瘓或須接受重大器官移植手術時，不受六十日等待期間限制；其他重大疾病仍依條款等待期間。"
    )
    entries = [
        coverage_entry(
            "critical-disease-benefit",
            f"{critical_disease_term}保險金",
            None,
            "face_amount",
            f"初次符合條款所列七項{critical_disease_term}之一時，按被保險人保險金額給付。",
            f"保單條款{critical_disease_term}保險金的給付，第 {critical_page} 頁",
            calculation_basis="percentage_of_base",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="choose_one",
            benefit_group_id=NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_BENEFIT_GROUP_ID,
            event_key="critical_disease",
            event_label=f"{critical_disease_term}事故",
            rate_percent=100,
            unit_key="face_amount",
            conditions=[
                "疾病等待期間為六十日，自契約生效日或加保日起持續有效第六十一日開始適用。",
                accident_exception,
                f"同時罹患兩項以上{critical_disease_term}僅給付其中一項。",
                "本項與身故、殘廢或完全失能給付擇一，給付後該被保險人的保險效力終止。",
                *refund_condition,
            ],
        ),
        coverage_entry(
            "death-or-funeral-benefit",
            "身故保險金或喪葬費用保險金",
            None,
            "face_amount",
            "一般身故按被保險人保險金額給付；符合該版本條款所列法律狀態時，改按喪葬費用保險金並受法定剩餘額度限制。",
            f"保單條款身故保險金或喪葬費用保險金的給付，第 {death_page} 頁",
            calculation_basis="death_or_funeral_face_amount",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="choose_one",
            benefit_group_id=NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_BENEFIT_GROUP_ID,
            event_key="death_or_funeral",
            event_label="身故或喪葬費用事故",
            unit_key="face_amount",
            conditions=[
                "是否適用喪葬費用限制，須依本版本條款與被保險人投保時法律狀態確認。",
                "喪葬費用保險金須與其他保單合併計算法定上限，本保單僅能使用剩餘額度。",
                "本項與重大疾病、殘廢或完全失能給付擇一，給付後該被保險人的保險效力終止。",
                *refund_condition,
            ],
        ),
        coverage_entry(
            "disability-benefit",
            f"{disability_term}保險金",
            None,
            "face_amount",
            f"致成附表一所列七項{disability_term}程度之一，經醫院診斷確定後按被保險人保險金額給付。",
            f"保單條款{disability_term}保險金的給付，第 {disability_page} 頁",
            calculation_basis="percentage_of_base",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="choose_one",
            benefit_group_id=NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_BENEFIT_GROUP_ID,
            event_key="disability",
            event_label=f"{disability_term}事故",
            rate_percent=100,
            unit_key="face_amount",
            conditions=[
                f"同時符合附表一兩款以上{disability_term}程度時僅給付一款。",
                "本項與重大疾病、身故或喪葬費用給付擇一，給付後該被保險人的保險效力終止。",
                *refund_condition,
            ],
        ),
    ]
    if unexpired_premium_refund:
        entries.append(
            coverage_entry(
                "unexpired-premium-refund",
                "未滿期保險費返還",
                None,
                "policy_recorded_limit",
                "在重大疾病、身故或喪葬費用、殘廢或完全失能給付後，另按日數比例返還該被保險人已繳的未滿期保險費。",
                f"保單條款各保險金給付條文，第 {min(critical_page, death_page, disability_page)}-{max(critical_page, death_page, disability_page)} 頁",
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="per_event",
                aggregation_rule="conditional_additive",
                benefit_group_id=NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_BENEFIT_GROUP_ID,
                applies_to_entry_ids=NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_PRIMARY_ENTRY_IDS,
                unit_key="unexpired_premium_refund_amount",
                policy_state_keys=["unexpired_premium_refund_amount"],
                conditions=[
                    "僅隨本契約三類擇一保險事故中的實際給付項目加計一次，不是獨立或可重複申領的保障。",
                    "金額須以團體保單、保險證或保險公司按事故日實際計算結果為準。",
                ],
            )
        )
    return entries


def parse_nanshan_group_critical_illness_term_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_nanshan_group_critical_illness_term_strict_source(document):
        return None

    product_id = str(document.get("product_id") or "")
    revision = NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_REVISIONS[product_id]
    expected_page_count = NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_PAGE_COUNTS[
        product_id
    ]
    if (
        document.get("page_count") not in {None, expected_page_count}
        or document.get("pages_parsed") not in {None, expected_page_count}
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    dense_text = compact_table_text(text)
    if len(dense_text) < 7000:
        return None

    critical_disease_term = "重度重大疾病" if revision >= 13 else "重大疾病"
    disability_term = "完全失能" if revision >= 14 else "殘廢"
    definition_revision = (
        "severe_seven_major_diseases"
        if revision >= 13
        else "legacy_seven_major_diseases"
    )
    unexpired_premium_refund = revision >= 7
    accidental_waiting_exception_scope = (
        "all_defined_critical_disease"
        if revision >= 7
        else "paralysis_or_major_organ_transplant_only"
    )
    funeral_status_rule_revision = (
        "legacy_under_14_or_mental_capacity"
        if revision <= 7
        else (
            "mental_capacity_definition"
            if revision <= 13
            else "guardianship_declaration"
        )
    )
    funeral_cap_reference_revision = (
        "legacy_legal_status_cap"
        if revision <= 7
        else (
            "mental_capacity_cap"
            if revision <= 13
            else (
                "inheritance_deduction_half_at_insurance_application"
                if revision <= 16
                else "statutory_inheritance_deduction_half"
            )
        )
    )

    required_signals = [
        "南山人壽團體重大疾病定期保險",
        "本契約保險期間為一年",
        "本公司按該被保險人之保險金額給付保險金",
        "被保險人同時有前項兩款情形之一時",
        "本公司僅給付其中一款之保險金",
        f"{critical_disease_term}保險金的給付",
        "身故保險金或喪葬費用保險金的給付",
        f"{disability_term}保險金的給付",
        "本公司按保險金額給付",
        "附表一",
        "七、中樞神經系統機能遺存極度障害",
    ]
    if any(compact_table_text(signal) not in dense_text for signal in required_signals):
        return None

    waiting_signals = (
        [
            "第六十一日開始",
            "因遭受意外傷害事故所致者",
        ]
        if revision >= 7
        else ["持續有效六十天以後", "不受前述六十天期間之限制"]
    )
    if any(compact_table_text(signal) not in dense_text for signal in waiting_signals):
        return None

    legacy_definition_signal = "七、重大器官移植手術"
    severe_definition_signal = "七、重大器官移植或造血幹細胞移植"
    if (
        definition_revision == "legacy_seven_major_diseases"
        and compact_table_text(legacy_definition_signal) not in dense_text
    ) or (
        definition_revision == "severe_seven_major_diseases"
        and compact_table_text(severe_definition_signal) not in dense_text
    ):
        return None

    funeral_signals = {
        "legacy_under_14_or_mental_capacity": [
            "未滿十四足歲",
            "心神喪失或精神耗弱",
        ],
        "mental_capacity_definition": [
            "精神障礙或其他心智缺陷",
            "不能辨識其行為或欠缺依其辨識而行為之能力",
        ],
        "guardianship_declaration": ["受監護宣告尚未撤銷"],
    }[funeral_status_rule_revision]
    if any(compact_table_text(signal) not in dense_text for signal in funeral_signals):
        return None
    funeral_cap_reference_signal = (
        "不得超過被保險人投保時遺產及贈與稅法第十七條有關遺產稅喪葬費扣除額之半數"
        if 14 <= revision <= 16
        else (
            "不得超過遺產及贈與稅法第十七條有關遺產稅喪葬費扣除額之半數"
            if revision >= 17
            else None
        )
    )
    if (
        funeral_cap_reference_signal
        and compact_table_text(funeral_cap_reference_signal) not in dense_text
    ):
        return None

    event_refund_signal = compact_table_text(
        "返還該被保險人已繳之未滿期保險費"
    )
    has_event_refund = dense_text.count(event_refund_signal) >= 3
    if has_event_refund is not unexpired_premium_refund:
        return None

    critical_heading = f"{critical_disease_term}保險金的給付"
    disability_heading = f"{disability_term}保險金的給付"
    critical_start = text.find(critical_heading)
    death_start = text.find("身故保險金或喪葬費用保險金的給付")
    disability_start = text.find(disability_heading)
    if min(critical_start, death_start, disability_start) < 0:
        return None
    critical_page = source_page(text, critical_start) or (
        5 if expected_page_count == 9 else 6
    )
    death_page = source_page(text, death_start) or (
        6 if expected_page_count == 9 else 7
    )
    disability_page = source_page(text, disability_start) or (
        6 if expected_page_count == 9 else 7
    )
    page_override = NANSHAN_GROUP_CRITICAL_ILLNESS_TERM_PAGE_OVERRIDES.get(
        product_id
    )
    if page_override:
        critical_page, death_page, disability_page = page_override

    required_policy_inputs = [
        "face_amount",
        "death_benefit_status",
        "remaining_funeral_benefit_limit",
    ]
    if unexpired_premium_refund:
        required_policy_inputs.append(
            "unexpired_premium_refund_amount"
        )

    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": "被保險人保險金額",
        "face_amount_label": "被保險人保險金額",
        "selection_guidance": "請輸入保險證、被保險人名冊或最近契約變更通知所載的被保險人保險金額；身故給付另須確認是否適用喪葬費用限制。",
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": "nanshan-group-critical-illness-term",
            "company_group": "nanshan_life",
            "terms_revision": f"partial_change_{revision}",
            "group_policy": True,
            "policy_period_years": 1,
            "insurance_amount_basis": "insured_face_amount",
            "death_benefit_formula": "face_amount_or_funeral_limit",
            "critical_disease_benefit_formula": "face_amount",
            "disability_benefit_formula": "face_amount",
            "face_amount_required": True,
            "required_policy_inputs": required_policy_inputs,
            "exclusive_benefit_choice": True,
            "contract_terminates_after_benefit": True,
            "critical_disease_term": critical_disease_term,
            "critical_disease_definition_revision": definition_revision,
            "critical_disease_item_count": 7,
            "critical_disease_waiting_days": 60,
            "accidental_waiting_exception_scope": accidental_waiting_exception_scope,
            "disability_term": disability_term,
            "complete_disability_table_item_count": 7,
            "benefit_event_unexpired_premium_refund": unexpired_premium_refund,
            "unexpired_premium_refund_requires_policy_state": unexpired_premium_refund,
            "funeral_benefit_limit_rule": True,
            "funeral_status_rule_revision": funeral_status_rule_revision,
            "funeral_cap_reference_revision": funeral_cap_reference_revision,
            "amount_presentation": "contract_gross_benefit_before_premium_adjustments",
        },
        "coverage_entries": nanshan_group_critical_illness_term_entries(
            critical_disease_term=critical_disease_term,
            disability_term=disability_term,
            accidental_waiting_exception_scope=accidental_waiting_exception_scope,
            unexpired_premium_refund=unexpired_premium_refund,
            critical_page=critical_page,
            death_page=death_page,
            disability_page=disability_page,
        ),
    }


