def is_nanshan_group_one_year_cancer_medical_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = NANSHAN_GROUP_ONE_YEAR_CANCER_MEDICAL_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-032"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def nanshan_group_one_year_cancer_medical_semantic_phase(
    revision: int,
) -> str:
    if revision <= 5:
        return "legacy_application_schedule_member_spouse_child"
    if revision <= 12:
        return "legacy_cancer_disease_application_amounts"
    return "standardized_cancer_taxonomy_application_amounts"


def nanshan_group_one_year_cancer_medical_entries(
    *,
    revision: int,
    article_refs: dict[str, str],
) -> list[dict[str, Any]]:
    eligibility_conditions = [
        "首次參加或加保後自第 31 日起，第一次符合本版本癌症定義才進入保障範圍。",
        "前 30 日內確診不屬本條款癌症給付範圍，實際效力與退費依該版本條款及保險公司審核。",
        "各項日額或保險金額須以要保書、保險證、被保險人名冊、批註或最近契約變更通知為準。",
    ]
    surgery_conditions = [
        *eligibility_conditions,
        (
            "同一國際疾病傷害及死因分類標準詳細分類編號之癌症接受手術治療，以給付一次為限。"
            if revision <= 5
            else "條款按每次因第一次罹患癌症而接受的手術，依保單記載癌症手術治療保險金額給付。"
        ),
    ]
    recovery_conditions = [
        *eligibility_conditions,
        "出院後療養日數按該次實際住院日數計算。",
    ]
    if revision <= 5:
        recovery_conditions.append(
            "每次出院後給付日數最高以 21 日為限。"
        )

    source_ref = lambda key: f"保單條款{article_refs[key]}"
    return [
        coverage_entry(
            "cancer-inpatient-daily-benefit",
            "癌症住院醫療保險金",
            None,
            "policy_recorded_limit",
            "按保單記載癌症住院醫療日額乘以實際住院日數。",
            source_ref("hospital"),
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_day",
            unit_key="cancer_hospital_daily_amount",
            quantity_state_key="cancer_hospitalization_days",
            policy_state_keys=["cancer_hospital_daily_amount"],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=eligibility_conditions,
        ),
        coverage_entry(
            "cancer-surgery-treatment-benefit",
            "癌症手術治療保險金",
            None,
            "policy_recorded_limit",
            "按保單記載癌症手術治療保險金額乘以符合條款的手術次數。",
            source_ref("surgery"),
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_surgery",
            unit_key="cancer_surgery_benefit_amount",
            quantity_state_key="cancer_surgery_count",
            policy_state_keys=["cancer_surgery_benefit_amount"],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=surgery_conditions,
        ),
        coverage_entry(
            "cancer-death-benefit",
            "癌症死亡保險金",
            None,
            "policy_recorded_limit",
            "因第一次符合本版本癌症定義而身故時，按保單記載癌症死亡保險金額給付。",
            source_ref("death"),
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_policy",
            unit_key="cancer_death_benefit_amount",
            policy_state_keys=["cancer_death_benefit_amount"],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=eligibility_conditions,
        ),
        coverage_entry(
            "cancer-post-discharge-recovery-benefit",
            "癌症出院後療養保險金",
            None,
            "policy_recorded_limit",
            (
                "按保單記載癌症出院後療養日額乘以實際住院日數，"
                + (
                    "每次出院最多計 21 日。"
                    if revision <= 5
                    else "本版本未另列 21 日上限。"
                )
            ),
            source_ref("recovery"),
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_day",
            unit_key="cancer_recovery_daily_amount",
            quantity_state_key="cancer_hospitalization_days",
            quantity_cap=21 if revision <= 5 else None,
            policy_state_keys=["cancer_recovery_daily_amount"],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=recovery_conditions,
        ),
    ]


def parse_nanshan_group_one_year_cancer_medical_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_nanshan_group_one_year_cancer_medical_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = NANSHAN_GROUP_ONE_YEAR_CANCER_MEDICAL_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version["source_text_sha256"]:
        return None
    dense_text = compact_table_text(text)
    common_signals = (
        "本契約保險期間為一年",
        "第三十一日",
        "癌症住院醫療保險金",
        "癌症手術治療保險金",
        "癌症死亡保險金",
        "癌症出院後療養保險金",
    )
    if any(
        compact_table_text(signal) not in dense_text
        for signal in common_signals
    ):
        return None
    if not any(
        compact_table_text(title) in dense_text
        for title in (
            "南山團體一年定期癌症醫療保險",
            "南山人壽團體一年定期癌症醫療保險",
        )
    ):
        return None

    revision = int(version["revision"])
    early_schedule = revision <= 5
    standardized_taxonomy = revision >= 13
    exact_phase_signals = (
        (
            "最高以二十一日為限",
            "同一國際詳細分類編號",
            "保險金額詳要保書",
        )
        if early_schedule
        else (
            "每次手術本公司按其投保之",
            "被保險成員戶籍登記之父母",
        )
    )
    if any(
        compact_table_text(signal) not in dense_text
        for signal in exact_phase_signals
    ):
        return None
    if (
        (compact_table_text("最高以二十一日為限") in dense_text)
        is not early_schedule
        or (
            compact_table_text("同一國際詳細分類編號")
            in dense_text
        )
        is not early_schedule
        or (
            compact_table_text("每次手術本公司按其投保之")
            in dense_text
        )
        is early_schedule
        or (compact_table_text("父母") in dense_text)
        is early_schedule
    ):
        return None
    standardized_signals = (
        "癌症初期",
        "癌症輕度",
        "癌症重度",
    )
    has_standardized_taxonomy = all(
        compact_table_text(signal) in dense_text
        for signal in standardized_signals
    )
    if has_standardized_taxonomy is not standardized_taxonomy:
        return None

    headings = {
        "hospital": "「癌症住院醫療保險金」的給付",
        "surgery": "「癌症手術治療保險金」的給付",
        "death": "「癌症死亡保險金」的給付",
        "recovery": "「癌症出院後療養保險金」的給付",
    }
    article_refs = {
        key: heading_reference(text, heading)
        for key, heading in headings.items()
    }
    if any(reference is None for reference in article_refs.values()):
        return None

    semantic_phase = (
        nanshan_group_one_year_cancer_medical_semantic_phase(
            revision
        )
    )
    required_policy_inputs = [
        "cancer_hospital_daily_amount",
        "cancer_hospitalization_days",
        "cancer_surgery_benefit_amount",
        "cancer_surgery_count",
        "cancer_death_benefit_amount",
        "cancer_recovery_daily_amount",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "保單記載癌症保障金額",
        "selection_guidance": (
            "請依要保書、保險證、被保險人名冊、批註或最近契約變更通知，"
            "輸入四項癌症保障金額；再輸入住院日數與符合條款的手術次數。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "nanshan-group-one-year-cancer-medical"
            ),
            "company_group": "nanshan_life",
            "source_batch_id": "tii-life-032",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "group_policy": True,
            "policy_period_years": 1,
            "currency_basis": "twd",
            "amounts_source": (
                "application_policy_or_latest_endorsement"
            ),
            "cancer_waiting_days": 30,
            "cancer_coverage_starts_day": 31,
            "cancer_definition_revision": (
                "legacy_malignant_tumor_appendix_codes"
                if early_schedule
                else (
                    "legacy_cancer_disease_appendix_exclusions"
                    if revision <= 12
                    else "standardized_initial_mild_severe_cancer"
                )
            ),
            "covered_relationships": (
                ["member", "spouse", "children"]
                if early_schedule
                else ["member", "spouse", "children", "parents"]
            ),
            "surgery_benefit_rule": (
                "same_icd_detailed_code_once"
                if early_schedule
                else "per_surgery"
            ),
            "recovery_days_cap_per_discharge": (
                21 if early_schedule else None
            ),
            "radiation_benefit_present": False,
            "chemotherapy_benefit_present": False,
            "bone_marrow_transplant_benefit_present": False,
            "outpatient_benefit_present": False,
            "required_policy_inputs": required_policy_inputs,
            "amount_presentation": (
                "contract_gross_benefit_before_claim_eligibility_review"
            ),
        },
        "coverage_entries": (
            nanshan_group_one_year_cancer_medical_entries(
                revision=revision,
                article_refs=article_refs,
            )
        ),
    }


