def parse_prudential_concern_premium_waiver_96_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_prudential_concern_premium_waiver_96_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = PRUDENTIAL_CONCERN_PREMIUM_WAIVER_96_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "保誠人壽關心豁免保險費附約(96)",
        "第一次罹患",
        "退還按日數比例計算當期已繳付未到期保險費總和",
        "豁免爾後各期的保險費",
        "至主契約繳費期滿日止",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None
    if any(
        signal in dense_text
        for signal in (
            "第一保單年度",
            "年繳保險費總額",
            "乘以三倍給付",
        )
    ):
        return None

    revision = int(version["revision"])
    disability_term = "殘廢" if revision <= 10 else "失能"
    if (
        f"本附約所稱「完全{disability_term}」" not in dense_text
        or (
            "本附約所稱「完全失能」" in dense_text
        )
        is not (revision >= 11)
    ):
        return None

    cancer_term = "癌症" if revision <= 8 else "癌症(重度)"
    if f"五、{cancer_term}:" not in dense_text:
        return None

    waiting_period_explicit = revision >= 9
    if waiting_period_explicit:
        first_seven_signal = (
            "生效日或復效日起持續有效九十日內"
            if revision == 9
            else "生效日起持續有效九十日內"
        )
        waiting_signals = (
            first_seven_signal,
            "生效日起持續有效三十日內",
            "不受前述「等待期間」之限制",
        )
        if any(signal not in dense_text for signal in waiting_signals):
            return None
        if (
            "生效日或復效日起持續有效九十日內"
            in dense_text
        ) is not (revision == 9):
            return None
    elif (
        "持續有效九十日內" in dense_text
        or "持續有效三十日內" in dense_text
    ):
        return None

    revised_last_eleven_definitions = revision >= 12
    if (
        "嚴重再生不良性貧血" in dense_text
    ) is not revised_last_eleven_definitions:
        return None

    required_policy_inputs = [
        "remaining_premium_amount",
        "unexpired_premium_refund_amount",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "特定傷病與保費資料",
        "selection_guidance": (
            "先依這個 product_id 的條款版本確認是否首次罹患十八項"
            "特定傷病之一；未來保費豁免請填尚未到期保費合計，"
            "當期退費請填按日數比例確認的金額。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "prudential-concern-premium-waiver-96"
            ),
            "company_group": "prudential_life",
            "source_batch_id": "tii-life-014",
            "terms_revision": f"partial_change_{revision}",
            "semantic_phase": (
                prudential_concern_premium_waiver_96_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version[
                "source_text_sha256"
            ],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "specific_disease_item_count": 18,
            "specific_disease_definition_source": (
                "exact_terms_revision"
            ),
            "specific_disease_waiting_period_explicit": (
                waiting_period_explicit
            ),
            "specific_disease_waiting_days_first_7": (
                90 if waiting_period_explicit else None
            ),
            "specific_disease_waiting_days_last_11": (
                30 if waiting_period_explicit else None
            ),
            "specific_disease_waiting_start_first_7": (
                "effective_or_reinstatement_date"
                if revision == 9
                else "effective_date"
                if waiting_period_explicit
                else None
            ),
            "specific_disease_waiting_start_last_11": (
                "effective_date"
                if waiting_period_explicit
                else None
            ),
            "accidental_waiting_exception": (
                waiting_period_explicit
            ),
            "cancer_term": cancer_term,
            "termination_definition_term": disability_term,
            "death_is_waiver_trigger": False,
            "disability_or_impairment_is_waiver_trigger": False,
            "first_policy_year_cash_benefit_available": False,
            "premium_waiver_event_triggers": [
                "specified_disease_18_items",
            ],
            "premium_waiver_until": (
                "main_contract_payment_end"
            ),
            "premium_waiver_scope": (
                "main_contract_this_rider_and_other_attached_riders"
            ),
            "premium_waiver_requires_remaining_premium_amount": (
                True
            ),
            "waiver_is_non_cash_effect": True,
            "current_unexpired_premium_refund_available": True,
            "current_unexpired_premium_refund_formula": (
                "current_paid_premiums_times_unexpired_day_ratio"
            ),
            "discounted_cash_settlement_available": False,
            "ordinary_termination_values_excluded_from_coverage": (
                True
            ),
            "required_policy_inputs": required_policy_inputs,
            "claim_event_inputs": [
                "policy_effect_status_at_event",
                "event_or_diagnosis_date",
                "specific_disease_exact_version_confirmation",
                "waiting_period_or_accident_exception_confirmation",
                "covered_contract_remaining_premium_total",
                "unexpired_premium_refund_amount",
            ],
            "amount_presentation": (
                "single_event_with_policy_state_amounts"
            ),
        },
        "coverage_entries": (
            prudential_concern_premium_waiver_96_entries(
                revision=revision,
            )
        ),
    }


