def parse_prudential_group_hospital_medical_b_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_prudential_group_hospital_medical_b_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = PRUDENTIAL_GROUP_HOSPITAL_MEDICAL_B_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "團體住院醫療保險",
        "病房費用日額保險金",
        "手術費用保險金",
        "住院醫療費用保險金",
        "出院門診醫療費用保險金",
        "手術名稱及費用表",
        "百分之五十",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None

    revision = int(version["revision"])
    phase_checks = (
        ("社會保險" in dense_text, revision <= 1),
        ("全民健康保險" in dense_text, revision >= 2),
        ("每次住院總限額" in dense_text, revision <= 1),
        (
            "計算之金額的百分之六十" in dense_text,
            revision <= 1,
        ),
        ("百分之六十五" in dense_text, revision >= 2),
        (
            "未能出具醫院開立之醫療收據正本"
            in dense_text,
            revision >= 2,
        ),
        (
            "指定醫師" in dense_text,
            2 <= revision <= 6,
        ),
        (
            "有效期間屆滿後出院" in dense_text,
            revision >= 9,
        ),
        ("日間住院" in dense_text, revision >= 10),
    )
    if any(actual is not expected for actual, expected in phase_checks):
        return None

    required_policy_inputs = [
        "hospital_daily_amount",
        "surgery_fee_benefit_limit",
        "inpatient_medical_benefit_limit",
    ]
    if revision <= 1:
        required_policy_inputs.append(
            "hospitalization_total_benefit_limit"
        )
    outpatient_quantity_key = (
        "post_discharge_outpatient_visit_count"
        if revision <= 1
        else "post_discharge_outpatient_day_count"
    )
    claim_event_inputs = [
        "hospitalization_days",
        outpatient_quantity_key,
        "inpatient_surgery_expense",
        "inpatient_medical_expense",
        "national_health_insurance_payment_status",
        "surgery_benefit_rate_percent",
    ]
    if revision >= 2:
        claim_event_inputs.append("medical_claim_receipt_status")
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "保單記載限額與本次住院資料",
        "selection_guidance": (
            "先依本 product_id 對應的保單首頁、被保險人名冊、附表或最新批註，"
            "輸入病房日額、手術限額與住院醫療限額；再依本次事故輸入住院日數、"
            "門診日或次數、實際費用、健保狀態與手術附表比例。"
            + (
                "舊版另須輸入每次住院總限額。"
                if revision <= 1
                else "若無法提供收據正本，請選擇條款約定的日額替代方式。"
            )
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "prudential-group-hospital-medical-insurance-type-b"
            ),
            "family_fingerprint": (
                PRUDENTIAL_GROUP_HOSPITAL_MEDICAL_B_FINGERPRINT
            ),
            "company_group": "prudential_life_taiwan",
            "source_batch_id": "tii-life-014",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                prudential_group_hospital_medical_b_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "group_policy": True,
            "policy_period_years": 1,
            "coverage_type": "B",
            "currency_basis": "twd",
            "policy_schedule_amounts_required": True,
            "fixed_plan_amounts_in_terms": False,
            "disease_waiting_days": 30,
            "same_hospital_readmission_days": 90,
            "social_insurance_wording": revision <= 1,
            "non_insurance_payment_rate_percent": (
                60 if revision <= 1 else 65
            ),
            "hospital_daily_day_limit": (
                None if revision <= 1 else 60
            ),
            "post_discharge_outpatient_window_days": 14,
            "post_discharge_outpatient_measure": (
                "visits" if revision <= 1 else "days"
            ),
            "receipt_daily_cash_alternative": revision >= 2,
            "receipt_daily_cash_excludes_reimbursement": (
                revision >= 2
            ),
            "hospitalization_total_cap": revision <= 1,
            "designated_physician_expense_covered": (
                2 <= revision <= 6
            ),
            "post_expiry_readmission_excluded": revision >= 9,
            "day_hospital_excluded": revision >= 10,
            "surgery_table_rate_required": True,
            "required_policy_inputs": required_policy_inputs,
            "claim_event_inputs": claim_event_inputs,
            "amount_presentation": (
                "policy_schedule_limits_with_claim_event_inputs"
            ),
        },
        "coverage_entries": (
            prudential_group_hospital_medical_b_entries(
                revision=revision,
            )
        ),
    }


