def is_fubon_group_one_year_critical_illness_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FUBON_GROUP_ONE_YEAR_CRITICAL_ILLNESS_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-050"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def fubon_group_one_year_critical_illness_semantic_phase(
    revision: int,
) -> str:
    if revision <= 5:
        return "legacy_minor_age_and_statutory_funeral_cap"
    if revision <= 8:
        return "legacy_three_month_waiting"
    if revision == 9:
        return "legacy_ninety_day_waiting"
    if revision == 10:
        return "standardized_severe_disability_term"
    if revision <= 13:
        return "standardized_severe_impairment_term"
    if revision <= 15:
        return "standardized_severe_current_funeral_cap"
    return "standardized_severe_declared_death_revision"


