def is_fubon_group_fixed_hospital_comprehensive_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FUBON_GROUP_FIXED_HOSPITAL_COMPREHENSIVE_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-050"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def fubon_group_fixed_hospital_comprehensive_semantic_phase(
    revision: int,
) -> str:
    if revision <= 4:
        return "legacy_90_day_readmission"
    if revision == 5:
        return "neonatal_exception_90_day_readmission"
    if revision == 6:
        return "post_expiry_exclusion_90_day_readmission"
    if revision == 7:
        return "day_hospital_legal_references_90_day_readmission"
    if revision <= 9:
        return "modernized_exclusions_90_day_readmission"
    if revision <= 13:
        return "fourteen_day_readmission"
    return "updated_day_hospital_references_fourteen_day_readmission"


