                amount_role="payout",
                limit_scope="per_hospitalization",
                unit_key="inpatient_nursing_daily_amount",
                quantity_state_key="hospitalization_days",
                quantity_cap_state_key=(
                    "hospitalization_day_limit_per_stay"
                ),
                policy_state_keys=["inpatient_nursing_daily_amount"],
