def is_fubon_group_one_year_cancer_health_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FUBON_GROUP_ONE_YEAR_CANCER_HEALTH_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-050"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def fubon_group_one_year_cancer_health_rider_semantic_phase(
    revision: int,
) -> str:
    if revision == 0:
        return "legacy_child_23_designated_hospital_reinstatement_wait"
    if revision <= 5:
        return "child_25_designated_hospital_reinstatement_wait"
    if revision <= 7:
        return "medical_act_hospital_reinstatement_wait"
    if revision == 8:
        return "medical_act_hospital_issue_only_wait"
    if revision <= 10:
        return "in_situ_definition_issue_only_wait"
    if revision == 11:
        return "in_situ_definition_insured_notice"
    return "in_situ_definition_forced_execution_continuation"


