def is_hongtai_xianghaokang_whole_life_medical_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = HONGTAI_XIANGHAOKANG_WHOLE_LIFE_MEDICAL_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-086"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def hongtai_xianghaokang_semantic_phase(revision: int) -> str:
    if revision <= 1:
        return "emergency_observation_embedded"
    if revision <= 5:
        return "separate_emergency_observation"
    if revision == 6:
        return "newborn_screening_waiting_exception"
    if revision == 7:
        return "post_expiry_continuing_hospitalization"
    if revision <= 13:
        return "emergency_observation_removed"
    return "expiry_age_111"


