def hongtai_wholeheart_cancer_semantic_phase(revision: int) -> str:
    if revision <= 2:
        return "legacy_225_survival_waiting_reinstatement"
    if revision <= 5:
        return "legacy_225_waiting_reinstatement"
    if revision == 6:
        return "legacy_200_waiting_reinstatement"
    if revision == 7:
        return "legacy_200_reinstatement_immediate"
    if revision == 8:
        return "impairment_200_reinstatement_immediate"
    if revision <= 10:
        return "standardized_cancer_200"
    if revision == 11:
        return "medical_review_200"
    return "medical_review_175"


def is_hongtai_wholeheart_cancer_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = HONGTAI_WHOLEHEART_CANCER_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-086"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


