def aia_tongtong_youbao_semantic_phase(revision: int) -> str:
    if revision <= 6:
        return "legacy_long_term_care_and_disability"
    if revision <= 11:
        return "long_term_care_and_disability"
    return "long_term_care_and_impairment"


def is_aia_tongtong_youbao_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = AIA_TONGTONG_YOUBAO_VERSIONS.get(product_id)
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-140"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


