def parse_bnp_paribas_group_hospital_medical_d_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_bnp_paribas_group_hospital_medical_d_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = BNP_PARIBAS_GROUP_HOSPITAL_MEDICAL_D_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version["source_text_sha256"]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "法商法國巴黎人壽團體住院醫療保險附約",
        "住院醫療保險金日額",
        "一般住院醫療日額保險金",
        "癌症住院醫療日額保險金",
        "加護病房日額保險金",
        "燒燙傷病房日額保險金",
        "特定手術醫療保險金",
        "出院療養保險金",
        "住院前後門診醫療保險金",
        "九十日",
        "十倍",
        "百分之五十",
        "百分之二十五",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None

    revision = int(version["revision"])
    phase_signals = (
        ("新生兒先天性代謝異常疾病篩檢項目", revision >= 5),
        ("有效期間屆滿後出院", revision >= 6),
        ("日間住院", revision >= 7),
        ("原位癌", revision >= 10),
        ("中央衛生主管機關", revision >= 11),
        ("日間留院/日間照護", revision == 15),
    )
    if any(
        (signal in dense_text) is not expected
        for signal, expected in phase_signals
    ):
        return None
    if revision == 15:
        if "第五十一條" in dense_text or "第三十五條" in dense_text:
            return None
    elif revision >= 7:
        mental_health_reference_present = (
            "第三十五條" in dense_text
            or (
                revision == 9
                and "精神衛生法第三十第2頁,共5頁五條"
                in dense_text
            )
        )
        if (
            "第五十一條" not in dense_text
            or not mental_health_reference_present
        ):
            return None

    required_policy_inputs = [
        "hospital_daily_amount",
        "hospitalization_days",
        "cancer_hospitalization_days",
        "intensive_care_days",
        "burn_unit_days",
        "outpatient_visit_count",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "住院醫療保險金日額與事故日數",
        "selection_guidance": (
            "請輸入保單、保險證、被保險人名冊或最新批註所載的"
            "住院醫療保險金日額，再依事故填入本 product_id 條款"
            "可計入的住院、癌症住院、加護病房、燒燙傷病房與門診日數。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "bnp-paribas-group-hospital-medical-rider-type-d"
            ),
            "company_group": "bnp_paribas_cardif_life",
            "source_batch_id": "tii-life-170",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                bnp_paribas_group_hospital_medical_d_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "group_policy": True,
            "rider": True,
            "policy_period_years": 1,
            "coverage_type": "D",
            "currency_basis": "twd",
            "daily_amount_source": "policy_or_latest_endorsement",
            "benefit_article": 7,
            "disease_waiting_days": 30,
            "sars_waiting_days": 10,
            "renewal_waiting_period_carryover": True,
            "newborn_screening_waiting_exception": revision >= 5,
            "same_hospital_readmission_days": 14,
            "post_expiry_readmission_excluded": revision >= 6,
            "day_hospital_excluded": revision >= 7,
            "day_hospital_legal_reference_revision": (
                "current_statutes_with_day_care"
                if revision == 15
                else "nhi_article_51_and_mental_health_article_35"
                if revision >= 7
                else "not_explicit"
            ),
            "cancer_waiting_days": 30,
            "cancer_definition_revision": (
                "malignant_tumor_or_in_situ"
                if revision >= 10
                else "legacy_malignant_tumor"
            ),
            "health_authority_wording": (
                "central_health_authority"
                if revision >= 11
                else "executive_yuan_department_of_health"
            ),
            "hospitalization_day_limit_per_benefit": 90,
            "general_hospital_daily_multiplier": 1,
            "cancer_hospital_daily_additional_multiplier": 1,
            "intensive_care_daily_additional_multiplier": 1,
            "burn_unit_daily_additional_multiplier": 2,
            "specified_surgery_multiplier": 10,
            "specified_surgery_health_points_minimum": 1000,
            "post_discharge_convalescence_rate_percent": 50,
            "outpatient_rate_percent": 25,
            "outpatient_pre_days": 7,
            "outpatient_post_days": 7,
            "outpatient_post_surgery_days": 14,
            "reimbursement_benefit": False,
            "required_policy_inputs": required_policy_inputs,
            "claim_event_inputs": required_policy_inputs[1:],
            "amount_presentation": (
                "policy_daily_amount_with_claim_event_days"
            ),
        },
        "coverage_entries": (
            bnp_paribas_group_hospital_medical_d_entries()
        ),
    }


