def parse_hongtai_hospital_medical_rider_plan_unit(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_hongtai_hospital_medical_rider_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = HONGTAI_HOSPITAL_MEDICAL_RIDER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "住院醫療保險附約",
        "每日加護病房費用保險金",
        "每次住院醫療費用保險金",
        "每次手術費用保險金",
        "甲型轉換成日額給付",
        "每日住院醫療保險金",
        "投保單位",
        "附表一",
        "附表二",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None

    revision = int(version["revision"])
    phase_checks = (
        ("社會保險" in dense_text, revision == 0),
        ("全民健康保險" in dense_text, revision >= 1),
        (
            "每日居家療養費用保險金" in dense_text,
            revision <= 4,
        ),
        (
            "每日療養補助費用保險金" in dense_text,
            revision >= 5,
        ),
        (
            "新生兒先天性代謝異常疾病篩檢" in dense_text,
            revision >= 9,
        ),
        (
            "附約有效期間屆滿後住院之處理" in dense_text,
            revision >= 10,
        ),
    )
    if any(actual is not expected for actual, expected in phase_checks):
        return None

    semantic_phase = (
        "social_insurance_home_convalescence"
        if revision == 0
        else "nhi_home_convalescence"
        if revision <= 4
        else "nhi_therapy_subsidy"
        if revision <= 8
        else "newborn_screening_waiting_exception"
        if revision == 9
        else "post_expiry_readmission_exclusion"
    )
    therapy_name = (
        "每日居家療養費用保險金"
        if revision <= 4
        else "每日療養補助費用保險金"
    )
    return {
        "selection_type": "plan_unit",
        "input_mode": "plan_unit",
        "selection_source": "terms",
        "selection_label": "甲型／乙型與投保單位數",
        "selection_guidance": (
            "請依保單面頁選擇甲型或乙型，並輸入正整數投保單位數。"
            "甲型實支實付還需依本次住院日數、實際費用、條款所稱社會保險／健保身分"
            "與手術附表比例計算；無收據時可依條款改選甲型日額。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": "hongtai-hospital-medical-rider",
            "company_group": "hongtai_life",
            "source_batch_id": "tii-life-086",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "plan_options": ["A", "B"],
            "plan_and_unit_required": True,
            "unit_count_positive_integer": True,
            "disease_waiting_days": 30,
            "renewal_waiting_period_carryover": True,
            "newborn_screening_waiting_exception": revision >= 9,
            "same_hospital_readmission_days": 14,
            "social_insurance_wording": revision == 0,
            "non_health_insurance_payment_rate_percent": 70,
            "per_unit_room_daily_limit": 100,
            "per_unit_icu_daily_limit": 200,
            "per_unit_therapy_daily_amount": 100,
            "therapy_benefit_term": therapy_name,
            "per_unit_inpatient_medical_limit": 3_000,
            "per_unit_surgery_base_limit": 3_000,
            "surgery_rate_min_percent": 2.5,
            "surgery_rate_max_percent": 100,
            "per_unit_plan_a_daily_alternative": 122,
            "per_unit_plan_b_daily_amount": 100,
            "outpatient_pre_days": 7,
            "outpatient_post_days": 7,
            "outpatient_per_visit_per_unit_limit": 50,
            "plan_a_daily_alternative_mutually_exclusive": True,
            "post_expiry_readmission_excluded": revision >= 10,
            "no_claim_consecutive_years": 3,
            "no_claim_premium_discount_percent": 40,
            "required_policy_inputs": ["plan_name", "unit_count"],
            "claim_event_inputs": [
                "hospitalization_days",
                "intensive_care_days",
                "hospital_room_expense",
                "intensive_care_room_expense",
                "inpatient_medical_expense",
                "inpatient_surgery_expense",
                "national_health_insurance_payment_status",
                "surgery_benefit_rate_percent",
                "reimbursement_or_daily_cash_choice",
            ],
            "amount_presentation": (
                "selected_plan_and_unit_with_claim_event_inputs"
            ),
        },
        "plan_options": [
            {
                "value": "A",
                "label": "甲型（實支實付，可依條件轉日額）",
                "coverage_entries": (
                    hongtai_hospital_medical_rider_plan_a_entries(
                        revision=revision
                    )
                ),
            },
            {
                "value": "B",
                "label": "乙型（固定日額）",
                "coverage_entries": [
                    coverage_entry(
                        "plan-b-hospital-daily",
                        "每日住院醫療保險金",
                        100,
                        "daily_per_unit",
                        "按實際住院日數，每單位每日給付一百元。",
                        "保單條款乙型給付約定及附表一",
                        calculation_basis="per_unit_per_day",
                        amount_role="payout",
                        limit_scope="per_day",
                        aggregation_rule="separate",
                        quantity_state_key="hospitalization_days",
                        result_kind="cash_payout",
                        amount_stage="gross_contract_benefit",
                    )
                ],
            },
        ],
    }


