def parse_hongtai_group_hospital_medical_reimbursement_unit(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_hongtai_group_hospital_medical_reimbursement_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = HONGTAI_GROUP_HOSPITAL_MEDICAL_REIMBURSEMENT_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "宏泰人壽團體住院醫療保險",
            "住院醫療費用保險金",
            "手術費用保險金",
            "病房費用保險金",
        )
    ):
        return None

    revision = int(version["revision"])
    semantic_phase = (
        "social_insurance_standard_receipt"
        if revision <= 1
        else "nhi_standard_receipt"
        if revision <= 4
        else "original_receipt_room_name_update"
        if revision == 5
        else "designated_physician_removed"
        if revision <= 8
        else "day_hospital_and_disclosure_daily_fallback"
    )
    claim_event_inputs = [
        "hospitalization_days",
        "hospital_room_expense",
        "inpatient_medical_expense",
        "inpatient_surgery_expense",
        "national_health_insurance_payment_status",
        "surgery_benefit_rate_percent",
    ]
    if revision >= 9:
        claim_event_inputs.extend(
            [
                "hospital_medical_claim_mode",
                "day_hospital_medical_expense",
                "day_hospital_days",
                "day_hospital_daily_cash_amount",
            ]
        )
    return {
        "selection_type": "unit",
        "input_mode": "unit",
        "selection_source": "terms",
        "selection_label": "投保單位數",
        "selection_guidance": (
            "請依保單面頁輸入正整數投保單位數。理賠試算還需填本次實際費用、健保給付狀態及手術附表比例；"
            "新版日間住院若改採替代日額，請再依實際保單或保險公司列示金額輸入每日金額。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "hongtai-group-hospital-medical-reimbursement"
            ),
            "company_group": "hongtai_life",
            "source_batch_id": "tii-life-086",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "group_policy": True,
            "unit_count_required": True,
            "unit_count_positive_integer": True,
            "same_hospital_readmission_days": 14,
            "room_benefit_name": (
                "每日一般病房費用保險金"
                if revision <= 4
                else "每日病房費用保險金"
            ),
            "original_receipt_required": revision >= 5,
            "designated_physician_expense_covered": revision <= 5,
            "day_hospital_explicit": revision >= 9,
            "unnotified_other_reimbursement_daily_fallback": (
                revision >= 9
            ),
            "outpatient_benefit_present": False,
            "non_nhi_payment_rate_percent": 65,
            "per_unit_room_daily_limit": 100,
            "room_days_limit_per_hospitalization": 365,
            "per_unit_inpatient_medical_limit": 3_000,
            "per_unit_surgery_base_limit": 3_000,
            "surgery_rate_min_percent": 2.5,
            "surgery_rate_max_percent": 100,
            "required_policy_inputs": ["unit_count"],
            "claim_event_inputs": claim_event_inputs,
            "amount_presentation": (
                "contract_limits_from_unit_count_with_claim_event_inputs"
            ),
        },
        "coverage_entries": (
            hongtai_group_hospital_medical_reimbursement_entries(
                revision=revision
            )
        ),
    }


