def parse_mercantile_new_hospital_medical_rider_plan(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_mercantile_new_hospital_medical_rider_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = MERCANTILE_NEW_HOSPITAL_MEDICAL_RIDER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    common_signals = (
        "新住院醫療保險附約",
        "每日病房費用保險金",
        "住院醫療費用保險金",
        "手術費用保險金",
        "住院日額保險金",
        "最高補償限額表",
        "附表一",
        "附表二",
    )
    if any(signal not in dense_text for signal in common_signals):
        return None

    revision = int(version["revision"])
    phase_checks = (
        ("社會保險" in dense_text, revision == 0),
        ("指定醫師" in dense_text, revision <= 8),
        (
            "附約有效期間屆滿後住院之處理" in dense_text,
            revision >= 10,
        ),
        ("日間住院" in dense_text, revision >= 11),
        ("醫療法人" in dense_text, revision >= 11),
    )
    if any(actual is not expected for actual, expected in phase_checks):
        return None

    semantic_phase = (
        "social_insurance_legacy"
        if revision == 0
        else "nhi_standard"
        if revision <= 8
        else "nhi_medical_item_revision"
        if revision == 9
        else "post_expiry_readmission_exclusion"
        if revision == 10
        else "day_hospital_exclusion"
    )
    return {
        "selection_type": "plan",
        "input_mode": "plan",
        "selection_source": "terms",
        "selection_label": "計劃別",
        "selection_guidance": (
            "請依保單面頁選擇 A 至 F 計劃；本商品沒有投保單位數。"
            "理賠估算時再輸入住院日數、實際費用、健保給付狀態與手術附表比率。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "mercantile-new-hospital-medical-rider"
            ),
            "company_group": "mercantile_life",
            "source_batch_id": "tii-life-062",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "plan_options": ["A", "B", "C", "D", "E", "F"],
            "plan_required": True,
            "unit_count_required": False,
            "disease_waiting_days": 0,
            "same_hospital_readmission_days": 14,
            "same_hospitalization_day_limit": 120,
            "medical_limit_base_days": 30,
            "non_health_insurance_payment_rate_percent": 66,
            "surgery_rate_min_percent": 8,
            "surgery_rate_max_percent": 500,
            "social_insurance_wording": revision == 0,
            "designated_physician_expense_included": revision <= 8,
            "post_expiry_readmission_excluded": revision >= 10,
            "day_hospital_excluded": revision >= 11,
            "mental_day_stay_excluded": revision >= 11,
            "medical_corporation_hospital_wording": revision >= 11,
            "daily_cash_alternative_mutually_exclusive": True,
            "required_policy_inputs": ["plan_name"],
            "claim_event_inputs": [
                "hospitalization_days",
                "hospital_room_expense",
                "inpatient_medical_expense",
                "inpatient_surgery_expense",
                "national_health_insurance_payment_status",
                "surgery_benefit_rate_percent",
                "reimbursement_or_daily_cash_choice",
            ],
            "amount_presentation": (
                "selected_plan_with_claim_event_inputs"
            ),
        },
        "plan_options": [
            {
                "value": plan_name,
                "label": f"計劃 {plan_name}",
                "coverage_entries": (
                    mercantile_new_hospital_medical_plan_entries(
                        plan_name=plan_name
                    )
                ),
            }
            for plan_name in MERCANTILE_NEW_HOSPITAL_MEDICAL_PLAN_LIMITS
        ],
    }


