def mercantile_evergreen_hospital_medical_semantic_phase(
    revision: int,
) -> str:
    if revision == 0:
        return "legacy_90_day_per_hospitalization"
    if revision == 1:
        return "legacy_90_day_same_hospitalization"
    if revision <= 7:
        return "modern_14_day_annual_caps"
    if revision == 8:
        return "post_expiry_readmission_exclusion"
    return "day_hospital_and_mental_day_stay_exclusion"


