def is_allianz_one_year_inpatient_medical_expense_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = (
        ALLIANZ_ONE_YEAR_INPATIENT_MEDICAL_EXPENSE_RIDER_VERSIONS.get(
            product_id
        )
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-092"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


