def parse_allianz_one_year_inpatient_medical_expense_rider_unit(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_allianz_one_year_inpatient_medical_expense_rider_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = (
        ALLIANZ_ONE_YEAR_INPATIENT_MEDICAL_EXPENSE_RIDER_VERSIONS[
            product_id
        ]
    )
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "安聯人壽一年定期住院醫療費用保險附約",
            "每日病房費用保險金",
            "住院醫療費用保險金",
            "手術費用保險金",
            "住院醫療日額保險金",
        )
    ):
        return None

    revision = int(version["revision"])
    annual_day_limit = revision == 5 or revision >= 8
    semantic_phase = (
        "legacy_per_hospitalization_day_limit"
        if revision <= 4
        else "policy_year_day_limit"
        if revision == 5
        else "legacy_per_hospitalization_day_limit_reissued"
        if revision <= 7
        else "policy_year_day_limit"
        if revision <= 10
        else "post_expiry_readmission_exclusion"
        if revision == 11
        else "day_hospital_exclusion"
    )
    return {
        "selection_type": "unit",
        "input_mode": "unit",
        "selection_source": "terms",
        "selection_label": "投保單位數",
        "selection_guidance": (
            "保單以每100元保險金額為一單位；請輸入保單記載的正整數單位數，"
            "再選擇本次住院申領實支實付型或日額給付型。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "allianz-one-year-inpatient-medical-expense-rider"
            ),
            "company_group": "allianz_life",
            "source_batch_id": "tii-life-092",
            "terms_revision": f"partial_change_{revision}",
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "insured_amount_per_unit": 100,
            "unit_count_required": True,
            "unit_count_positive_integer": True,
            "same_hospital_readmission_days": 14,
            "same_hospitalization_day_limit": 120,
            "annual_same_hospitalization_day_limit": annual_day_limit,
            "medical_limit_base_days": 30,
            "non_health_insurance_payment_rate_percent": 70,
            "surgery_rate_min_percent": 15,
            "surgery_rate_max_percent": 500,
            "medical_expense_receipt_required": True,
            "designated_physician_expense_included": True,
            "post_expiry_readmission_excluded": revision >= 11,
            "day_hospital_excluded": revision >= 12,
            "mental_day_stay_excluded": revision >= 12,
            "medical_corporation_hospital_wording": revision >= 12,
            "outpatient_benefit_present": False,
            "reimbursement_or_daily_cash_mutually_exclusive": True,
            "required_policy_inputs": ["unit_count"],
            "claim_event_inputs": [
                "reimbursement_or_daily_cash_choice",
                "hospitalization_days",
                "hospital_room_expense",
                "inpatient_medical_expense",
                "inpatient_surgery_expense",
                "national_health_insurance_payment_status",
                "surgery_benefit_rate_percent",
            ],
            "amount_presentation": (
                "unit_limits_with_reimbursement_or_daily_cash_choice"
            ),
        },
        "coverage_entries": (
            allianz_one_year_inpatient_medical_expense_entries()
        ),
    }


