def is_taiwan_new_hospital_medical_health_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-008"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def taiwan_new_hospital_medical_health_plan_entries(
    *,
    plan_name: str,
    revision: int,
) -> list[dict[str, Any]]:
    (
        room_limit,
        surgery_base_limit,
        inpatient_medical_limit,
        specific_surgery_recuperation,
        daily_cash_amount,
    ) = TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_PLAN_LIMITS[
        plan_name
    ]
    ineligible_values = ["disease_within_waiting_period"]
    uncertain_values = ["not_eligible_or_uncertain"]
    if revision >= 9:
        ineligible_values.append("day_hospital_or_day_care")
    else:
        uncertain_values.append("day_hospital_or_day_care")
    eligibility_fields = {
        "eligibility_state_key": (
            "taiwan_inpatient_daily_event_status"
        ),
        "ineligible_values": ineligible_values,
        "uncertain_values": uncertain_values,
    }
    receipt_reimbursement_fields = {
        "aggregation_rule": "choose_one",
        "benefit_group_id": (
            TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_CHOICE_GROUP_ID
        ),
        "event_key": "reimbursement",
        "event_label": "實支實付",
        "exclusion_state_key": "medical_claim_receipt_status",
        "exclusion_values": ["no_original_receipt_daily_cash"],
        "result_kind": "cash_payout",
        "amount_stage": "gross_contract_benefit",
        **eligibility_fields,
    }
    expense_reimbursement_fields = {
        **receipt_reimbursement_fields,
        "rate_percent": 65,
        "rate_condition_state_key": (
            "national_health_insurance_payment_status"
        ),
        "rate_condition_value": "not_covered",
    }
    reimbursement_conditions = [
        "疾病等待期三十日；意外傷害事故不適用疾病等待期。",
        "未經全民健康保險給付或非健保醫院就醫時，符合條款的實際費用先按百分之六十五計算，仍受各項限額約束。",
        "申領實支實付項目須檢具醫療費用收據正本及費用明細。",
        "同一疾病、傷害或其併發症出院後十四日內於同一醫院再次住院，視為同一次住院。",
    ]
    return [
        coverage_entry(
            "daily-room-expense-reimbursement",
            "每日病房費用保險金",
            room_limit,
            "daily_total",
            (
                f"計劃 {plan_name} 每日最高 {room_limit:,} 元，"
                "按符合條款的實際病房費用與住院日數計算。"
            ),
            "每日病房費用保險金條文及住院醫療保險金限額表",
            calculation_basis="reimbursement_with_cap",
            amount_role="limit",
            limit_scope="per_day",
            quantity_state_key="hospitalization_days",
            expense_state_key="hospital_room_expense",
            conditions=reimbursement_conditions,
            **expense_reimbursement_fields,
        ),
        coverage_entry(
            "inpatient-surgery-expense-reimbursement",
            "手術費用保險金",
            surgery_base_limit,
            "per_event_limit",
            (
                f"計劃 {plan_name} 手術基準限額 {surgery_base_limit:,} 元，"
                "乘本版本手術附表比例後，再與符合條款的實際手術費用取低。"
            ),
            "手術費用保險金條文、住院醫療保險金限額表及手術項目給付比率表",
            calculation_basis="reimbursement_with_cap",
            amount_role="limit",
            limit_scope="per_surgery",
            limit_rate_state_key="surgery_benefit_rate_percent",
            rate_min_percent=1,
            rate_max_percent=400,
            expense_state_key="inpatient_surgery_expense",
            conditions=[
                *reimbursement_conditions,
                "同一次手術涉及多項手術時，依條款手術附表及實際施作情形判定可採比例。",
            ],
            **expense_reimbursement_fields,
        ),
        coverage_entry(
            "inpatient-medical-expense-reimbursement",
            "住院醫療費用保險金",
            inpatient_medical_limit,
            "per_hospitalization_limit",
            (
                f"計劃 {plan_name} 每次住院最高 "
                f"{inpatient_medical_limit:,} 元，與符合條款的實際住院醫療費用取低。"
            ),
            "住院醫療費用保險金條文及住院醫療保險金限額表",
            calculation_basis="reimbursement_with_cap",
            amount_role="limit",
            limit_scope="per_hospitalization",
            expense_state_key="inpatient_medical_expense",
            conditions=reimbursement_conditions,
            **expense_reimbursement_fields,
        ),
        coverage_entry(
            "specific-surgery-discharge-recuperation-benefit",
            "特定手術出院後療養保險金",
            specific_surgery_recuperation,
            "per_event",
            (
                f"計劃 {plan_name} 每次符合條款附表二特定手術，"
                f"定額給付 {specific_surgery_recuperation:,} 元。"
            ),
            "特定手術出院後療養保險金條文及住院醫療保險金限額表",
            calculation_basis="fixed_amount",
            amount_role="payout",
            limit_scope="per_surgery",
            quantity_state_key="specific_surgery_count",
            conditions=[
                *reimbursement_conditions,
                "本項僅限條款附表二所列特定手術。",
            ],
            **receipt_reimbursement_fields,
        ),
        coverage_entry(
            "hospital-daily-cash-alternative",
            "住院醫療日額保險金",
            daily_cash_amount,
            "daily_total",
            (
                f"無法提供醫療費用收據正本時，計劃 {plan_name} "
                f"每日 {daily_cash_amount:,} 元乘符合條款的實際住院日數。"
            ),
            "住院醫療日額保險金條文及住院醫療保險金限額表",
            calculation_basis="per_day",
            amount_role="payout",
            limit_scope="per_day",
            aggregation_rule="choose_one",
            benefit_group_id=(
                TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_CHOICE_GROUP_ID
            ),
            event_key="daily_cash_alternative",
            event_label="無收據日額替代給付",
            quantity_state_key="hospitalization_days",
            exclusion_state_key="medical_claim_receipt_status",
            exclusion_values=["original_receipt"],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=[
                "本項僅適用無法提供醫療費用收據正本的條款情境。",
                "同一次保險事故改領本項後，不再計算病房、住院醫療、手術及特定手術療養實支／定額項目。",
            ],
            **eligibility_fields,
        ),
    ]


def parse_taiwan_new_hospital_medical_health_rider_plan(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_taiwan_new_hospital_medical_health_rider_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "新住院醫療健康保險附約",
            "每日病房費用保險金",
            "住院醫療費用保險金",
            "手術費用保險金",
            "住院日額償金",
        )
    ):
        return None

    revision = int(version["revision"])
    phase_checks = (
        ("指定醫師" in dense_text, revision <= 5),
        (
            "附約有效期間屆滿後住院之處理" in dense_text,
            revision >= 8,
        ),
        ("日間住院" in dense_text, revision >= 9),
        ("醫療法人" in dense_text, revision >= 9),
    )
    if any(actual is not expected for actual, expected in phase_checks):
        return None
    semantic_phase = (
        "designated_physician_expense"
        if revision <= 5
        else "standard_nhi_expense_scope"
        if revision <= 7
        else "post_expiry_readmission_exclusion"
        if revision == 8
        else "day_hospital_exclusion"
    )
    return {
        "selection_type": "plan",
        "input_mode": "plan",
        "selection_source": "terms",
        "selection_label": "計劃別",
        "selection_guidance": (
            "請依保單面頁選擇 HS-5 至 HS-30 計劃；本商品沒有投保單位數。"
            "理賠估算時再填事故狀態、收據、住院日數、實際費用、"
            "健保給付狀態及手術附表比例。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "taiwan-new-hospital-medical-health-rider"
            ),
            "company_group": "taiwan_life",
            "source_batch_id": "tii-life-008",
            "family_fingerprint": (
                TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_FINGERPRINT
            ),
            "terms_revision": f"partial_change_{revision}",
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "plan_options": list(
                TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_PLAN_LIMITS
            ),
            "plan_required": True,
            "unit_count_required": False,
            "disease_waiting_days": 30,
            "accident_waiting_period_exempt": True,
            "same_hospital_readmission_days": 14,
            "same_hospitalization_day_limit": None,
            "non_health_insurance_payment_rate_percent": 65,
            "surgery_rate_min_percent": 1,
            "surgery_rate_max_percent": 400,
            "designated_physician_expense_included": revision <= 5,
            "post_expiry_readmission_excluded": revision >= 8,
            "day_hospital_excluded": revision >= 9,
            "mental_day_stay_excluded": revision >= 9,
            "medical_corporation_hospital_wording": revision >= 9,
            "outpatient_surgery_benefit_present": False,
            "medical_expense_receipt_required": True,
            "daily_cash_alternative_mutually_exclusive": True,
            "required_policy_inputs": ["plan_name"],
            "claim_event_inputs": [
                "taiwan_inpatient_daily_event_status",
                "medical_claim_receipt_status",
                "hospitalization_days",
                "hospital_room_expense",
                "inpatient_medical_expense",
                "inpatient_surgery_expense",
                "national_health_insurance_payment_status",
                "surgery_benefit_rate_percent",
                "specific_surgery_count",
            ],
            "amount_presentation": (
                "selected_plan_with_reimbursement_or_daily_cash_inputs"
            ),
        },
        "plan_options": [
            {
                "value": plan_name,
                "label": f"計劃 {plan_name}",
                "coverage_entries": (
                    taiwan_new_hospital_medical_health_plan_entries(
                        plan_name=plan_name,
                        revision=revision,
                    )
                ),
            }
            for plan_name in (
                TAIWAN_NEW_HOSPITAL_MEDICAL_HEALTH_RIDER_PLAN_LIMITS
            )
        ],
    }


