def is_taiwan_wenxin_hospital_medical_health_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = TAIWAN_WENXIN_HOSPITAL_MEDICAL_HEALTH_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-008"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def taiwan_wenxin_hospital_medical_health_rider_semantic_phase(
    revision: int,
) -> str:
    if revision <= 1:
        return "designated_physician_expense"
    if revision == 2:
        return "standard_nhi_expense_scope"
    if revision == 3:
        return "newborn_screening_exception"
    if revision == 4:
        return "post_expiry_readmission_exclusion"
    if revision <= 8:
        return "day_hospital_exclusion"
    if revision <= 12:
        return "updated_newborn_screening_wording"
    return "original_receipt_duplicate_reimbursement_coordination"


