def is_prudential_new_hospital_medical_limit_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = PRUDENTIAL_NEW_HOSPITAL_MEDICAL_LIMIT_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-014"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def prudential_new_hospital_medical_limit_rider_semantic_phase(
    revision: int,
) -> str:
    if revision == 0:
        return "legacy_social_insurance_60_percent"
    if revision == 1:
        return "nhi_65_percent"
    if revision <= 4:
        return "complete_disability_attachment"
    if revision == 5:
        return "standard_nhi_expense_scope"
    if revision <= 7:
        return "post_expiry_readmission_exclusion"
    if revision == 8:
        return "day_hospital_exclusion"
    if revision == 9:
        return "other_agreed_method"
    if revision <= 12:
        return "disability_to_impairment_wording"
    return "original_receipt_duplicate_reimbursement_coordination"


