def is_cathay_group_quanyi_hospital_medical_limit_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = CATHAY_GROUP_QUANYI_HOSPITAL_MEDICAL_LIMIT_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-020"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def cathay_group_quanyi_hospital_medical_limit_semantic_phase(
    revision: int,
) -> str:
    if revision <= 2:
        return "designated_physician_expense"
    if revision == 3:
        return "designated_physician_removed"
    if revision == 4:
        return "newborn_screening_11_disease_exception"
    if revision == 5:
        return "post_expiry_readmission_exclusion"
    if revision == 6:
        return "medical_corporation_day_hospital_exclusion"
    if revision == 7:
        return "other_agreed_method"
    if revision == 8:
        return "newborn_screening_21_disease_exception"
    if revision == 9:
        return "medical_opinion_review"
    if revision == 10:
        return "main_policy_termination_continuation"
    if revision <= 12:
        return "premium_notice_multichannel"
    return "day_stay_day_care_wording"


def cathay_group_quanyi_hospital_medical_limit_entries(
    *,
    plan_name: str,
    revision: int,
) -> list[dict[str, Any]]:
    ineligible_values = ["confirmed_not_eligible"]
    uncertain_values = ["uncertain"]
    if plan_name == "A":
        ineligible_values.append("disease_waiting_not_met")
        if revision < 4:
            uncertain_values.append(
                "eligible_newborn_screening_exception"
            )
    else:
        uncertain_values.append("disease_waiting_not_met")
    eligibility_fields = {
        "eligibility_state_key": "cathay_group_quanyi_event_status",
        "ineligible_values": ineligible_values,
        "uncertain_values": uncertain_values,
    }
    reimbursement_fields = {
        "calculation_basis":
            "percentage_of_actual_expense_with_cap",
        "amount_role": "payout",
        "rate_percent": 65,
        "rate_condition_state_key":
            "cathay_group_quanyi_nhi_status",
        "rate_condition_value": "not_nhi_covered",
        "result_kind": "cash_payout",
        "amount_stage": "gross_contract_benefit",
        **eligibility_fields,
    }
    waiting_condition = (
        "計畫 A 疾病等待期為三十日；第 4 版起另依該版條款適用新生兒篩檢疾病例外。"
        if plan_name == "A"
        else "計畫 B 疾病自附約生效或加保日起納入保障，不適用計畫 A 三十日等待期。"
    )
    common_conditions = [
        waiting_condition,
        "意外傷害須發生於附約有效期間內。",
        "未以全民健康保險身分就醫、非健保醫院治療或費用未經健保給付時，按符合項目的實際費用百分之六十五給付，仍受保單記載限額約束。",
        "給付限額及最高日數以保單、被保險人名冊或其他書面約定為準。",
    ]
    return [
        coverage_entry(
            "daily-room-expense-benefit",
            "每日病房費用保險金",
            None,
            "policy_recorded_limit",
            "按符合條款的病房實際費用與保單記載每日限額乘符合日數的金額取低。",
            "每日病房費用保險金條文",
            limit_scope="per_hospitalization",
            aggregation_rule="separate",
            unit_key="cathay_group_quanyi_daily_room_limit",
            quantity_state_key="hospitalization_days",
            quantity_cap_state_key=(
                "cathay_group_quanyi_max_hospital_days"
            ),
            expense_state_key="hospital_room_expense",
            conditions=common_conditions,
            **reimbursement_fields,
        ),
        coverage_entry(
            "inpatient-medical-expense-benefit",
            "住院醫療費用保險金",
            None,
            "policy_recorded_limit",
            "按符合條款的住院醫療實際費用與保單記載每次住院限額取低。",
            "住院醫療費用保險金條文",
            limit_scope="per_hospitalization",
            aggregation_rule="separate",
            unit_key=(
                "cathay_group_quanyi_inpatient_medical_limit"
            ),
            expense_state_key="inpatient_medical_expense",
            conditions=common_conditions,
            **reimbursement_fields,
        ),
    ]


def parse_cathay_group_quanyi_hospital_medical_limit_plan(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_cathay_group_quanyi_hospital_medical_limit_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = CATHAY_GROUP_QUANYI_HOSPITAL_MEDICAL_LIMIT_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version[
        "source_text_sha256"
    ]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "團體全意住院醫療限額給付健康保險附約",
            "每日病房費用保險金",
            "住院醫療費用保險金",
        )
    ):
        return None
    revision = int(version["revision"])
    newborn_exception_count = 0 if revision < 4 else 11 if revision < 8 else 21
    return {
        "selection_type": "plan",
        "input_mode": "plan",
        "selection_source": "terms",
        "selection_label": "計畫別",
        "selection_guidance": (
            "請依保單選擇計畫 A 或 B；本商品沒有投保單位數。"
            "再填保單記載的每日病房限額、最高給付日數、每次住院醫療限額，"
            "以及本次住院日數、費用、健保與事故狀態。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family":
                "cathay-group-quanyi-hospital-medical-limit-health-rider",
            "company_group": "cathay_life",
            "source_batch_id": "tii-life-020",
            "family_fingerprint":
                CATHAY_GROUP_QUANYI_HOSPITAL_MEDICAL_LIMIT_FINGERPRINT,
            "terms_revision": f"partial_change_{revision}",
            "semantic_phase":
                cathay_group_quanyi_hospital_medical_limit_semantic_phase(
                    revision
                ),
            "source_document_sha256":
                version["source_document_sha256"],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version["source_text_extractor"],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "group_policy": True,
            "plan_options": ["A", "B"],
            "plan_required": True,
            "unit_count_required": False,
            "plan_a_disease_waiting_days": 30,
            "plan_b_disease_waiting_days": 0,
            "accident_waiting_period_exempt": True,
            "newborn_screening_exception_count":
                newborn_exception_count,
            "designated_physician_expense_included": revision <= 2,
            "post_expiry_readmission_excluded": revision >= 5,
            "day_hospital_excluded": revision >= 6,
            "mental_day_stay_excluded": revision >= 6,
            "medical_corporation_hospital_wording": revision >= 6,
            "other_agreed_method_wording": revision >= 7,
            "medical_opinion_review_wording": revision >= 9,
            "main_policy_termination_continuation": revision >= 10,
            "premium_notice_multichannel": revision >= 11,
            "day_stay_day_care_wording": revision >= 13,
            "benefit_entry_count": 2,
            "separate_surgery_benefit_present": False,
            "separate_outpatient_benefit_present": False,
            "non_nhi_actual_expense_rate_percent": 65,
            "required_policy_inputs": [
                "plan_name",
                "cathay_group_quanyi_daily_room_limit",
                "cathay_group_quanyi_max_hospital_days",
                "cathay_group_quanyi_inpatient_medical_limit",
            ],
            "claim_event_inputs": [
                "cathay_group_quanyi_event_status",
                "cathay_group_quanyi_nhi_status",
                "hospitalization_days",
                "hospital_room_expense",
                "inpatient_medical_expense",
            ],
            "amount_presentation":
                "selected_plan_with_policy_recorded_limits_and_actual_expenses",
        },
        "plan_options": [
            {
                "value": plan_name,
                "label": f"計畫 {plan_name}",
                "coverage_entries":
                    cathay_group_quanyi_hospital_medical_limit_entries(
                        plan_name=plan_name,
                        revision=revision,
                    ),
            }
            for plan_name in ("A", "B")
        ],
    }


