def is_taiwan_inpatient_daily_health_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = TAIWAN_INPATIENT_DAILY_HEALTH_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-008"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def taiwan_inpatient_daily_health_rider_semantic_phase(
    revision: int,
) -> str:
    if revision <= 3:
        return "per_hospitalization_90_day_limit"
    if revision <= 5:
        return "policy_year_per_hospitalization_90_day_limit"
    if revision == 6:
        return "post_expiry_readmission_exclusion"
    if revision <= 13:
        return "day_hospital_exclusion"
    return "updated_day_care_and_policy_period_wording"


def parse_taiwan_inpatient_daily_health_rider_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_taiwan_inpatient_daily_health_rider_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = TAIWAN_INPATIENT_DAILY_HEALTH_RIDER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "台灣人壽住院醫療日額給付健康保險附約",
            "住院醫療日額",
            "每次住院給付日數最高以九十日為限",
            "自本附約生效日起持續有效滿三十日後",
            "出院後十四日內",
        )
    ):
        return None
    if any(
        signal in dense_text
        for signal in (
            "加護病房保險金",
            "燒燙傷病房保險金",
            "手術保險金之給付",
            "療養保險金之給付",
        )
    ):
        return None

    revision = int(version["revision"])
    annual_limit_wording = revision >= 4
    post_expiry_readmission_excluded = revision >= 6
    day_hospital_excluded = revision >= 7
    updated_day_care_wording = revision >= 14
    if (
        ("同一保單年度" in dense_text) is not annual_limit_wording
        or (
            "附約有效期間屆滿後住院之處理" in dense_text
        )
        is not post_expiry_readmission_excluded
        or ("日間住院" in dense_text) is not day_hospital_excluded
        or ("日間照護" in dense_text) is not updated_day_care_wording
    ):
        return None

    benefit_article = 10 if revision >= 14 else 9
    readmission_article = 11 if revision >= 14 else 10
    required_policy_inputs = [
        "hospital_daily_amount",
        "hospitalization_days",
        "taiwan_inpatient_daily_event_status",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "住院日額與本次住院狀態",
        "selection_guidance": (
            "請輸入保單或最新批註記載的住院醫療日額、"
            "本次可計入住院日數，並選擇疾病等待期或意外事故狀態。"
            "系統依本 product_id 條款最多計算九十日。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "taiwan-inpatient-daily-health-rider"
            ),
            "company_group": "taiwan_life",
            "source_batch_id": "tii-life-008",
            "terms_revision": f"partial_change_{revision}",
            "semantic_phase": (
                taiwan_inpatient_daily_health_rider_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "group_policy": False,
            "daily_amount_source": (
                "policy_or_latest_endorsement"
            ),
            "disease_waiting_days": 30,
            "accident_waiting_period_exempt": True,
            "same_hospital_readmission_days": 14,
            "hospital_daily_days_limit": 90,
            "hospital_daily_day_limit_scope": (
                "same_policy_year_per_hospitalization"
                if annual_limit_wording
                else "per_hospitalization"
            ),
            "annual_same_hospitalization_day_limit": (
                annual_limit_wording
            ),
            "post_expiry_readmission_excluded": (
                post_expiry_readmission_excluded
            ),
            "day_hospital_excluded": day_hospital_excluded,
            "mental_day_stay_excluded": day_hospital_excluded,
            "day_hospital_wording": (
                "day_hospital_and_day_care"
                if updated_day_care_wording
                else "day_hospital_and_day_stay"
                if day_hospital_excluded
                else "not_explicit"
            ),
            "benefit_article": benefit_article,
            "readmission_article": readmission_article,
            "special_room_benefit_present": False,
            "surgery_benefit_present": False,
            "convalescence_benefit_present": False,
            "event_status_required": True,
            "required_policy_inputs": required_policy_inputs,
            "amount_presentation": (
                "policy_recorded_daily_amount_times_eligible_days"
            ),
        },
        "coverage_entries": [
            coverage_entry(
                "hospital-daily-benefit",
                "住院醫療日額保險金",
                None,
                "policy_recorded_limit",
                (
                    "按保單記載住院醫療日額乘以本次符合條款的住院日數；"
                    "每次住院最多計算九十日。"
                ),
                f"保單條款第{benefit_article}條保險範圍",
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="per_hospitalization",
                unit_key="hospital_daily_amount",
                quantity_state_key="hospitalization_days",
                quantity_cap=90,
                exclusion_state_key=(
                    "taiwan_inpatient_daily_event_status"
                ),
                exclusion_values=[
                    "disease_within_waiting_period",
                ],
                policy_state_keys=["hospital_daily_amount"],
                result_kind="cash_payout",
                amount_stage="gross_contract_benefit",
                conditions=[
                    "疾病須於本附約生效日起持續有效滿三十日後發生；意外傷害不受此疾病等待期限制。",
                    "同一疾病、傷害或其併發症出院後十四日內於同一醫院再次住院，合併為同一次住院。",
                    (
                        "本版明定不包含日間住院與精神衛生法所稱日間留院或日間照護。"
                        if day_hospital_excluded
                        else "本版未明列日間住院排除，相關資格須由保險公司依住院事實認定。"
                    ),
                    "本 family 沒有獨立加護病房、手術或出院療養保險金。",
                ],
            )
        ],
    }


