def is_hongtai_premium_waiver_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = HONGTAI_PREMIUM_WAIVER_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-086"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def hongtai_premium_waiver_discount_rate(
    revision: int,
) -> float:
    if revision <= 5:
        return 2
    if revision <= 7:
        return 1.5
    if revision <= 11:
        return 1.25
    return 1


def hongtai_premium_waiver_terms_change_number(
    revision: int,
) -> int:
    # The official sequence has no eighth partial-change document.
    return revision if revision <= 7 else revision + 1


def hongtai_premium_waiver_entries(
    *,
    plan: str,
    revision: int,
    disability_term: str,
    source_ref: str,
) -> list[dict[str, Any]]:
    if plan == "A":
        trigger_description = (
            f"甲型：身故、重大疾病或第一級至第六級{disability_term}之一"
        )
    else:
        trigger_description = (
            f"乙型：重大疾病或第二級至第六級{disability_term}之一"
        )
    discount_rate = hongtai_premium_waiver_discount_rate(
        revision
    )
    entries = [
        coverage_entry(
            "future-premium-waiver",
            "未來保險費豁免",
            None,
            "policy_premium",
            (
                f"{trigger_description}時，豁免本附約、主契約及附加於主契約"
                "之其他附約續期應繳保險費至主契約繳費期間屆滿；"
                "輸入尚未到期的保費合計可估算非現金保障效果。"
            ),
            source_ref,
            calculation_basis="waiver",
            amount_role="premium_waiver",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="remaining_premium_amount",
            policy_state_keys=["remaining_premium_amount"],
            result_kind="non_cash_effect",
            amount_stage="non_cash_estimate",
            conditions=[
                trigger_description + "。",
                "重大疾病須符合附約生效日起三十日等待期間；意外傷害所致的條款指定事故依條款例外辦理。",
                "此項為未來保費豁免效果，不是現金保險金。",
            ],
        ),
        coverage_entry(
            "current-unexpired-premium-refund",
            "事故當期未到期保險費退還",
            None,
            "policy_recorded_limit",
            (
                f"{trigger_description}時，另按事故日至當期末剩餘日數比例，"
                "退還本附約、主契約及其他附約當期已繳未到期保險費。"
            ),
            source_ref,
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_event",
            aggregation_rule="separate",
            unit_key="unexpired_premium_refund_amount",
            policy_state_keys=["unexpired_premium_refund_amount"],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=[
                trigger_description + "。",
                "金額須依事故日、繳費週期及各契約當期保費按日數比例確認。",
            ],
        ),
    ]
    if revision >= 2:
        entries.append(
            coverage_entry(
                "overlapping-waiver-cash-settlement",
                "重疊豁免貼現一次給付",
                None,
                "policy_recorded_limit",
                (
                    "本附約已發生豁免事故後，若主契約或其他附約再發生"
                    "其豁免事故，將對應尚未豁免的續期保費按條款利率"
                    f"{discount_rate:g}% 貼現至核定日一次給付。"
                ),
                source_ref,
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="per_policy",
                aggregation_rule="separate",
                unit_key="overlapping_waiver_settlement_amount",
                policy_state_keys=[
                    "overlapping_waiver_settlement_amount"
                ],
                result_kind="cash_payout",
                amount_stage="gross_contract_benefit",
                conditions=[
                    "須先符合本附約豁免事故，之後主契約或其他附約另發生其豁免事故。",
                    f"本版本條款貼現年利率為 {discount_rate:g}%。",
                    "請輸入保險公司依對應保費、剩餘繳費期間與條款利率確認的一次給付總額。",
                ],
            )
        )
    settlement_trigger = (
        f"豁免期間內主契約被保險人身故或成為第一級{disability_term}"
        if revision <= 7
        else "豁免期間內主契約或其他附約效力終止"
    )
    entries.append(
        coverage_entry(
            "waived-premium-termination-settlement",
            "豁免後契約終止貼現給付",
            None,
            "policy_recorded_limit",
            (
                f"{settlement_trigger}時，將該契約尚未豁免的續期保費"
                f"按條款年利率 {discount_rate:g}% 貼現一次給付。"
            ),
            source_ref,
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="waived_premium_termination_settlement_amount",
            policy_state_keys=[
                "waived_premium_termination_settlement_amount"
            ],
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=[
                settlement_trigger + "。",
                f"本版本條款貼現年利率為 {discount_rate:g}%。",
                "請輸入保險公司依尚未豁免保費與條款利率確認的一次給付總額。",
            ],
        )
    )
    return entries


def parse_hongtai_premium_waiver_rider_plan_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_hongtai_premium_waiver_rider_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = HONGTAI_PREMIUM_WAIVER_RIDER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    revision = int(version["revision"])
    terms_change_number = (
        hongtai_premium_waiver_terms_change_number(revision)
    )
    disability_term = "殘廢" if revision <= 9 else "失能"
    discount_rate = hongtai_premium_waiver_discount_rate(
        revision
    )
    rate_signal = {
        2: "年利率百分之二貼現",
        1.5: "年利率百分之一點五貼現",
        1.25: "年利率百分之一點二五貼現",
        1: "年利率百分之一貼現",
    }[discount_rate]
    required_signals = (
        "宏泰人壽豁免保險費附約",
        "本附約無解約金",
        "附加甲型者",
        "附加乙型者",
        f"第二級至第六級{disability_term}",
        "按日數比例計算當期已繳付未到期",
        "至主契約繳費期間屆滿",
        rate_signal,
    )
    if any(signal not in dense_text for signal in required_signals):
        return None

    overlap_signal = (
        "主契約或附加於主契約之其他附約(不含本附約)"
        "如另有豁免保險費之約定"
    )
    if (overlap_signal in dense_text) is not (revision >= 2):
        return None
    legacy_settlement_signal = (
        "主契約被保險人於豁免保險費期間內身故"
    )
    termination_settlement_signal = (
        "主契約或附加於主契約之其他附約於"
        "豁免保險費期間內效力終止時"
    )
    if (
        (legacy_settlement_signal in dense_text)
        is not (revision <= 7)
        or (termination_settlement_signal in dense_text)
        is not (revision >= 8)
    ):
        return None

    semantic_phase = (
        "legacy_basic_disability_discount_2"
        if revision <= 1
        else "legacy_overlap_disability_discount_2"
        if revision <= 5
        else "legacy_overlap_disability_discount_1_5"
        if revision <= 7
        else "legacy_overlap_termination_discount_1_25"
        if revision <= 9
        else "impairment_overlap_termination_discount_1_25"
        if revision <= 11
        else "impairment_overlap_termination_discount_1"
    )
    required_policy_inputs = [
        "plan_name",
        "remaining_premium_amount",
        "unexpired_premium_refund_amount",
        *(
            ["overlapping_waiver_settlement_amount"]
            if revision >= 2
            else []
        ),
        "waived_premium_termination_settlement_amount",
    ]
    source_ref = (
        "保單條款保險範圍、身故或第一級殘廢／失能、重大疾病、"
        "第二級至第六級殘廢／失能豁免保險費及附約終止約定"
    )
    return {
        "selection_type": "plan",
        "input_mode": "plan",
        "selection_source": "terms",
        "selection_label": "附約型別",
        "selection_guidance": (
            "請依保單面頁選擇甲型或乙型。系統會固定顯示條款保障；"
            "事故發生時，再填尚未到期保費、當期退費及保險公司確認的"
            "貼現一次給付金額。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": "hongtai-premium-waiver-rider",
            "company_group": "hongtai_life",
            "source_batch_id": "tii-life-086",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{terms_change_number}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "plan_options": ["A", "B"],
            "plan_type_required": True,
            "disease_waiting_days": 30,
            "accidental_waiting_exception": True,
            "critical_illness_definition_source": (
                "exact_terms_revision"
            ),
            "disability_term": disability_term,
            "premium_waiver_disability_levels": "1-6",
            "plan_a_waiver_event_triggers": [
                "death",
                "critical_illness",
                (
                    "disability_grade_1_to_6"
                    if disability_term == "殘廢"
                    else "impairment_grade_1_to_6"
                ),
            ],
            "plan_b_waiver_event_triggers": [
                "critical_illness",
                (
                    "disability_grade_2_to_6"
                    if disability_term == "殘廢"
                    else "impairment_grade_2_to_6"
                ),
            ],
            "premium_waiver_until": "main_contract_payment_end",
            "premium_waiver_scope": (
                "this_rider_main_contract_and_other_attached_riders"
            ),
            "premium_waiver_requires_remaining_premium_amount": True,
            "waiver_is_non_cash_effect": True,
            "current_unexpired_premium_refund_available": True,
            "current_unexpired_premium_refund_formula": (
                "current_paid_premiums_times_unexpired_day_ratio"
            ),
            "overlapping_waiver_settlement_available": (
                revision >= 2
            ),
            "overlapping_waiver_settlement_formula": (
                "remaining_covered_premiums_discounted_to_waiver_approval_date"
                if revision >= 2
                else None
            ),
            "waived_premium_termination_settlement_available": True,
            "waived_premium_termination_trigger": (
                "main_contract_insured_death_or_grade_1_disability"
                if revision <= 7
                else "covered_contract_termination_during_waiver"
            ),
            "waived_premium_settlement_discount_rate_percent": (
                discount_rate
            ),
            "no_cash_surrender_value": True,
            "required_policy_inputs": required_policy_inputs,
            "claim_event_inputs": [
                "policy_effect_status_at_event",
                "insured_event_type",
                "event_or_diagnosis_date",
                "critical_illness_exact_version_confirmation",
                "waiting_period_or_accident_exception_confirmation",
                "disability_or_impairment_grade",
                "waiver_approval_date",
                "covered_contract_premium_schedule",
                "covered_contract_termination_date",
            ],
            "amount_presentation": (
                "selected_plan_with_policy_state_amounts"
            ),
        },
        "plan_options": [
            {
                "value": "A",
                "label": (
                    f"甲型（含身故及第一級{disability_term}）"
                ),
                "coverage_entries": hongtai_premium_waiver_entries(
                    plan="A",
                    revision=revision,
                    disability_term=disability_term,
                    source_ref=source_ref,
                ),
            },
            {
                "value": "B",
                "label": (
                    f"乙型（重大疾病及第二至第六級{disability_term}）"
                ),
                "coverage_entries": hongtai_premium_waiver_entries(
                    plan="B",
                    revision=revision,
                    disability_term=disability_term,
                    source_ref=source_ref,
                ),
            },
        ],
    }


YUANTA_ANXIN100_CRITICAL_PRODUCT_ID = "261391MZ9GRJ023A11Z10000000"
YUANTA_ANXIN100_CRITICAL_FILE_NAME = "261391MZ9GRJ023A11Z10000000-A.pdf"


def is_yuanta_anxin100_critical_illness_strict_source(document: dict[str, Any]) -> bool:
    product_id = str(document.get("product_id") or "")
    file_name = str(document.get("file_name") or "")
    dense_text = re.sub(r"\s+", "", normalize_terms_text(str(document.get("text") or "")))
    return (
        product_id == YUANTA_ANXIN100_CRITICAL_PRODUCT_ID
        or file_name == YUANTA_ANXIN100_CRITICAL_FILE_NAME
        or "元大人壽安鑫100重大傷病終身健康保險" in dense_text
    )


