def is_allianz_worldview_foreign_currency_variable_universal_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = (
        ALLIANZ_WORLDVIEW_FOREIGN_CURRENCY_VARIABLE_UNIVERSAL_LIFE_VERSIONS.get(
            product_id
        )
    )
    return bool(
        version
        and document.get("batch_id") == "tii-life-095"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def allianz_worldview_semantic_phase(revision: int) -> str:
    if revision <= 10:
        return "legacy-annual-insurance-amount-abc"
    if revision == 11:
        return "preservation-multiplier-abc"
    if revision <= 24:
        return "preservation-multiplier-abcd"
    return "preservation-multiplier-abcd-minor-account-value-return"


