def is_shinkong_jinhaoyi_variable_universal_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = SHINKONG_JINHAOYI_VARIABLE_UNIVERSAL_LIFE_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and document.get("batch_id") == "tii-life-047"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def shinkong_jinhaoyi_semantic_phase(revision: int) -> str:
    if revision <= 13:
        return "age14-risk-threshold-appendix5"
    if revision <= 18:
        return "age15-minor-return-death-before-maturity-appendix5"
    if revision <= 22:
        return "age15-minor-return-all-events-before-maturity-appendix5"
    return "age15-minor-return-all-events-before-maturity-appendix4"


