def parse_shinkong_jinhaoyi_variable_universal_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_shinkong_jinhaoyi_variable_universal_life_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = SHINKONG_JINHAOYI_VARIABLE_UNIVERSAL_LIFE_VERSIONS[
        product_id
    ]
    if (
        document.get("source_document_sha256")
        != version["source_document_sha256"]
        or document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or document.get("source_text_extractor")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        hashlib.sha256(text.encode("utf-8")).hexdigest()
        != version["normalized_text_sha256"]
    ):
        return None
    dense_text = compact_table_text(text).replace("「", "").replace("」", "")
    common_signals = [
        "新光人壽金好意變額萬能壽險",
        "滿期日:被保險人保險年齡屆滿一百歲",
        "危險保額",
        "彈性保險金額",
        "第二十一條:滿期保險金的給付",
        "第二十二條:身故保險金或喪葬費用保險金",
        "第二十三條:全殘廢保險金的給付",
        "次二資產評價日之保單帳戶價值",
        "欠繳保險成本及保單維持費用或未還款項的扣除",
        "本保險為不分紅保單",
    ]
    if any(
        compact_table_text(signal) not in dense_text
        for signal in common_signals
    ):
        return None

    revision = int(version["revision"])
    semantic_phase = shinkong_jinhaoyi_semantic_phase(revision)
