def is_shinkong_jinmanyi_variable_universal_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = SHINKONG_JINMANYI_VARIABLE_UNIVERSAL_LIFE_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and document.get("batch_id") == "tii-life-047"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def shinkong_jinmanyi_semantic_phase(revision: int) -> str:
    if revision <= 12:
        return "age14-risk-threshold-appendix5"
    if revision == 13:
        return "age15-minor-return-death-before-maturity-appendix5"
    if revision <= 17:
        return (
            "age15-minor-return-death-before-maturity-"
            "minor-exclusion-clause-appendix5"
        )
    if revision <= 21:
        return (
            "age15-minor-return-all-events-before-maturity-"
            "minor-exclusion-clause-appendix5"
        )
    return (
        "age15-minor-return-all-events-before-maturity-"
        "minor-exclusion-clause-appendix4"
    )


def shinkong_jinmanyi_benefit_entries(
    revision: int,
) -> list[dict[str, Any]]:
    entries = shinkong_jinhaoyi_benefit_entries(revision + 1)
    for entry in entries:
        unit_key = str(entry.get("unit_key") or "")
        entry["unit_key"] = unit_key.replace(
            "shinkong_jinhaoyi_",
            "shinkong_jinmanyi_",
        )
    if revision >= 14:
        death_entry = next(
            entry
            for entry in entries
            if entry.get("id") == "death-benefit"
        )
        death_entry["conditions"].append(
            "未滿十五足歲因條款除外責任死亡時，依身故條款返還保單帳戶價值。"
        )
    return entries


