def parse_allianz_age111_variable_universal_life_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_allianz_age111_variable_universal_life_strict_source(document):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if len(text) < 5000:
        return None
    dense_text = compact_table_text(text)
    required_signals = [
        "變額萬能壽險",
        "投資標的",
        "保單帳戶價值",
        "淨危險保額",
        "保險型態",
        "基本保額",
        "保險金額",
        "祝壽保險金的給付",
        "身故保險金或喪葬費用保險金的給付",
    ]
    if any(compact_table_text(signal) not in dense_text for signal in required_signals):
        return None
    if not re.search(r"保險年齡.?達(?:111|一百一十一|一百十一)歲", dense_text):
        return None
    if compact_table_text("完全失能保險金的給付") in dense_text:
        disability_term = "失能"
    elif compact_table_text("完全殘廢保險金的給付") in dense_text:
        disability_term = "殘廢"
    else:
        return None
    gate_text = dense_text.replace("「", "").replace("」", "")
    if "按保險金額給付" not in gate_text and "保險金額給付" not in gate_text:
        return None

    net_risk_text = allianz_age111_net_risk_definition(text)
    policy_types = allianz_age111_policy_types(net_risk_text)
    if not policy_types:
        return None
    if "保險金扣除額" not in text and policy_types != ["丁型"]:
        return None
    net_risk_formula_by_type = allianz_age111_formula_by_type(policy_types)
    requires_insurance_deduction = any(
        policy_type in {"甲型", "丙型", "戊型"} for policy_type in policy_types
    )
    requires_threshold_factor = any(
        policy_type in {"丙型", "丁型", "戊型"} for policy_type in policy_types
    )
    if requires_threshold_factor and "門檻係數" not in text:
        return None
    if (
        any(policy_type in {"丙型", "丁型"} for policy_type in policy_types)
        and compact_table_text("不得低於保單帳戶價值乘以門檻係數")
        not in dense_text
    ):
        return None
    threshold_factor_schedule = (
        allianz_age111_threshold_factor_schedule(text)
        if requires_threshold_factor
        else []
    )
    if requires_threshold_factor and not threshold_factor_schedule:
        return None
    requires_paid_premium_basis = "戊型" in policy_types
    if requires_paid_premium_basis and (
        compact_table_text("累計已繳付之保險費扣除累計已提領金額")
        not in dense_text
    ):
        return None

    has_minor_death_account_value_rule = (
        "未滿十五足歲" in text or "滿十五足歲前死亡" in text
    )
    has_minor_disability_account_value_rule = (
        f"未滿十五足歲前，致成完全{disability_term}" in text
        or f"未滿十五足歲前,致成完全{disability_term}" in text
        or f"滿十五足歲以前致成完全{disability_term}" in text
    )
    has_maturity_interest = "給付祝壽保險金時" in text and "加計利息" in text
    required_inputs = [
        "basic_face_amount",
        "policy_type",
        "policy_account_value",
    ]
    if requires_insurance_deduction:
        required_inputs.append("insurance_deduction_amount")
    if requires_threshold_factor:
        required_inputs.append("insured_age_at_event")
    if requires_paid_premium_basis:
        required_inputs.extend(
            ["paid_premium_total", "partial_termination_amount_total"]
        )

    return {
        "selection_type": "face_amount_plan",
        "input_mode": "face_amount_plan",
        "selection_source": "terms",
        "selection_label": "基本保額與保險型態",
        "selection_guidance": "請輸入保單上的基本保額並選擇保險型態；系統會依所選型態要求保單帳戶價值、保險金扣除額、事故時年齡或累計保費與提領額，再按條款換算保障金額。",
        "plan_options": [
            {"value": policy_type, "label": policy_type}
            for policy_type in policy_types
        ],
        "version_characteristics": {
            "product_family": "allianz-age111-variable-universal-life-face-amount",
            "company_group": "allianz_life",
            "currency_basis": "twd",
            "investment_linked_policy": True,
            "variable_universal_life_policy": True,
            "age111_maturity": True,
            "maturity_trigger": "age_111_policy_anniversary",
            "maturity_age": 111,
            "maturity_benefit_formula": "net_amount_at_risk_plus_policy_account_value_at_age_111_policy_anniversary",
            "maturity_interest_crediting": has_maturity_interest,
            "death_benefit_formula": "net_amount_at_risk_plus_policy_account_value",
            "total_disability_benefit_formula": "net_amount_at_risk_plus_policy_account_value",
            "net_amount_at_risk_formula_by_type": net_risk_formula_by_type,
            "policy_type_options": policy_types,
            "threshold_factor_schedule": threshold_factor_schedule,
            "required_policy_inputs": required_inputs,
            "policy_face_amount_required": True,
            "policy_type_required": True,
            "policy_account_value_required": True,
            "insurance_deduction_amount_required": requires_insurance_deduction,
            "threshold_factor_required": requires_threshold_factor,
            "insurance_amount_basis": "net_amount_at_risk_plus_policy_account_value",
            "redemption_valuation_timing_required": True,
            "funeral_benefit_limit_rule": True,
            "funeral_benefit_excludes_account_value": True,
            "minor_death_before_age_15_account_value_rule": has_minor_death_account_value_rule,
            "minor_disability_before_age_15_account_value_rule": has_minor_disability_account_value_rule,
            "complete_disability_table_item_count": 7,
            "disability_term": disability_term,
            "non_participating_policy": True,
        },
        "coverage_entries": allianz_age111_variable_universal_life_entries(
            disability_term,
            has_minor_death_account_value_rule=has_minor_death_account_value_rule,
            has_minor_disability_account_value_rule=has_minor_disability_account_value_rule,
        ),
    }


