BNP_PARIBAS_LEGACY_RECORDED_VARIABLE_LIFE_VERSIONS = {
    f"{prefix}{revision:02d}": {
        "revision": revision,
        "terms_revision": (
            "original" if revision == 0 else f"partial_change_{revision}"
        ),
        "family_key": family["family_key"],
        "family_name": family["family_name"],
        "identity_signals": family["identity_signals"],
        "formula_variant": family["formula_variant"],
        "currency_basis": family["currency_basis"],
        "source_document_sha256": family["source_document_sha256"][revision],
        "normalized_text_sha256": family["normalized_text_sha256"][revision],
        "source_text_extractor": family["source_text_extractor"][revision],
        "page_count": family["page_count"][revision],
    }
    for prefix, family in BNP_PARIBAS_LEGACY_RECORDED_VARIABLE_LIFE_FAMILIES.items()
    for revision in range(len(family["source_document_sha256"]))
}
BNP_PARIBAS_LEGACY_RECORDED_VARIABLE_LIFE_PRODUCT_IDS = frozenset(
    BNP_PARIBAS_LEGACY_RECORDED_VARIABLE_LIFE_VERSIONS
)


def is_bnp_paribas_legacy_recorded_variable_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = BNP_PARIBAS_LEGACY_RECORDED_VARIABLE_LIFE_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-173"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == f"{product_id.lower()}-a.pdf"
        and document.get("source_document_sha256")
        == version["source_document_sha256"]
    )


def bnp_paribas_legacy_offset_state_keys(
    *,
    maturity: bool = False,
    foreign_currency: bool = False,
) -> list[str]:
    keys = [
        (
            "maturity_policy_account_value"
            if maturity
            else "benefit_valuation_policy_account_value"
        ),
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_policy_charge_amount",
    ]
    if foreign_currency:
        keys.append("remittance_fee_amount")
    return keys


def bnp_paribas_legacy_maturity_entry(
    *,
    foreign_currency: bool,
) -> dict[str, Any]:
    return coverage_entry(
        "maturity-benefit",
        "滿期保險金",
        None,
        "policy_recorded_limit",
        "契約於滿期日仍有效且被保險人生存時，依滿期日次一評價日的保單帳戶價值，扣除條款允許抵銷的款項後給付。",
        "滿期保險金的給付／未償款項的扣除",
        calculation_basis="maturity_policy_account_value",
        amount_role="payout",
        limit_scope="per_policy",
        aggregation_rule="separate",
        unit_key="maturity_policy_account_value",
        policy_state_keys=bnp_paribas_legacy_offset_state_keys(
            maturity=True,
            foreign_currency=foreign_currency,
        ),
        currency_state_key=(
            "contract_currency" if foreign_currency else None
        ),
        conditions=[
            "滿期帳戶價值須以保險公司於條款指定評價日列示的金額為準。",
            "如有未償款項或保單借款本息，保險公司得先抵銷後給付餘額。",
        ]
        + (
            ["外幣契約給付時另扣除條款約定的匯款相關費用。"]
            if foreign_currency
            else []
        ),
    )


def bnp_paribas_legacy_paid_premium_entries(
    *,
    foreign_currency: bool,
) -> list[dict[str, Any]]:
    common_event_state_keys = [
        "benefit_valuation_policy_account_value",
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_policy_charge_amount",
        "claim_time_status",
        "benefit_exclusion_status",
    ]
    death_state_keys = [
        *common_event_state_keys,
        "death_benefit_status",
        "remaining_funeral_benefit_limit",
        "funeral_excess_insurance_cost_refund_status",
        "funeral_excess_insurance_cost_refund_amount",
    ]
    disability_state_keys = [
        *common_event_state_keys,
        "total_disability_qualification_status",
    ]
    if foreign_currency:
        death_state_keys.append("remittance_fee_amount")
        disability_state_keys.append("remittance_fee_amount")
    currency_state_key = (
        "contract_currency" if foreign_currency else None
    )
    shared_conditions = [
        "保險金額基礎為累計已繳保險費扣除累計部分提領帳戶金額後，乘以保單目前指定百分比或倍數。",
        "甲型取保險金額基礎與給付評價日保單帳戶價值較大者；乙型為兩者相加。",
        "未滿十五足歲發生條款指定身故或完全殘廢情形時，改以給付評價日保單帳戶價值給付或返還。",
        "如有未償款項或保單借款本息，保險公司得先抵銷後給付餘額。",
    ]
    if foreign_currency:
        shared_conditions.append(
            "所有輸入及試算結果均以保單約定外幣為單位，給付時另扣除匯款相關費用。"
        )
    death_entry = coverage_entry(
        "death-or-funeral-benefit",
        "身故保險金或喪葬費用保險金",
        None,
        "policy_recorded_limit",
        "依保險型態計算身故保障；適用喪葬費用限制時，只限制非投資保障部分，再加回保單帳戶價值。",
        "身故保險金或喪葬費用保險金的給付／保險金額定義",
        calculation_basis="paid_premium_factor_account_value_formula",
        amount_role="payout",
        limit_scope="per_policy",
        aggregation_rule="separate",
        unit_key="paid_premium_basis_plus_policy_account_value",
        policy_state_keys=death_state_keys,
        currency_state_key=currency_state_key,
        minor_account_value_return_age=15,
        funeral_limit_plan_options=["甲型", "乙型"],
        conditions=shared_conditions
        + ["喪葬費用保險金額不包含投資部分的保單帳戶價值。"],
    )
    disability_entry = coverage_entry(
        "total-disability-benefit",
        "完全殘廢保險金",
        None,
        "policy_recorded_limit",
        "符合條款附表所列完全殘廢程度之一時，依保險型態計算給付。",
        "完全殘廢保險金的給付／保險金額定義",
        calculation_basis="paid_premium_factor_account_value_formula",
        amount_role="payout",
        limit_scope="per_policy",
        aggregation_rule="separate",
        unit_key="paid_premium_basis_plus_policy_account_value",
        policy_state_keys=disability_state_keys,
        currency_state_key=currency_state_key,
        minor_account_value_return_age=15,
        conditions=shared_conditions
        + ["給付完全殘廢保險金後，契約效力終止。"],
    )
    return [
        bnp_paribas_legacy_maturity_entry(
            foreign_currency=foreign_currency
        ),
        death_entry,
        disability_entry,
    ]


def bnp_paribas_value100_value_addition_entry() -> dict[str, Any]:
    policy_state_keys = [
        "installment_premium_frequency",
        "previous_installment_premium_cumulative_count",
        "current_installment_premium_cumulative_count",
        "previous_installment_premium_average_amount",
        "value_addition_qualification_status",
    ]
    return coverage_entry(
        "value-added-benefit",
        "加值給付金",
        None,
        "policy_recorded_limit",
        "依分期保險費繳別、前後期累積繳費次數及前期累積所繳分期保險費平均值計算，並投入新臺幣貨幣帳戶。",
        "加值給付金及其給付條件／附表五",
        calculation_basis="installment_premium_value_addition",
        amount_role="reference",
        limit_scope="per_event",
        aggregation_rule="separate",
        unit_key="installment_premium_value_addition",
        policy_state_keys=policy_state_keys,
        conditions=[
            "累積繳費次數 61 至 120 次適用 1%，121 次以上適用 2%。",
            "年繳需依跨越 61 次或 121 次的條款公式分段計算；月繳按當期累積次數所對應給付率計算。",
            "曾部分提領且提領後次日帳戶價值低於累積所繳分期保險費總和者，喪失加值給付資格。",
            "加值給付金投入帳戶後已反映在保單帳戶價值，不另加到身故、完全殘廢或滿期保障。",
            "條款未另列小數處理方式；網站以元為單位四捨五入試算，實際入帳以保險公司為準。",
        ],
    )


def bnp_paribas_legacy_three_way_entries() -> list[dict[str, Any]]:
    offset_keys = [
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_policy_charge_amount",
    ]
    candidate_keys = [
        "current_policy_amount",
        "basic_face_amount",
        "benefit_valuation_policy_account_value",
    ]
    shared_conditions = [
        "給付毛額為目前有效保險金額、目前基本保額及給付評價日保單帳戶價值三者較大值。",
        "目前基本保額可能因歷次繳費或部分提領重算，須依最新保單明細輸入，不可用目前年齡與目前帳戶價值倒推。",
        "未滿十五足歲發生條款指定身故或完全殘廢情形時，改以給付評價日保單帳戶價值給付或返還。",
        "如有未償款項或保單借款本息，保險公司得先抵銷後給付餘額。",
    ]
    return [
        bnp_paribas_legacy_maturity_entry(foreign_currency=False),
        coverage_entry(
            "death-or-funeral-benefit",
            "身故保險金或喪葬費用保險金",
            None,
            "policy_recorded_limit",
            "身故時取三項保單記載金額較大者；適用喪葬費用限制時，只限制非投資保障部分。",
            "身故保險金或喪葬費用保險金的給付",
            calculation_basis="death_or_funeral_greater_of",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="highest",
            unit_key="greater_of_current_policy_basic_face_and_account_value",
            policy_state_keys=candidate_keys + offset_keys,
            minor_account_value_return_age=15,
            conditions=shared_conditions,
        ),
        coverage_entry(
            "total-disability-benefit",
            "完全殘廢保險金",
            None,
            "policy_recorded_limit",
            "符合條款附表所列完全殘廢程度之一時，取三項保單記載金額較大者給付。",
            "完全殘廢保險金的給付",
            calculation_basis="greater_of",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="highest",
            unit_key="greater_of_current_policy_basic_face_and_account_value",
            policy_state_keys=candidate_keys + offset_keys,
            minor_account_value_return_age=15,
            conditions=shared_conditions
            + ["給付完全殘廢保險金後，契約效力終止。"],
        ),
        bnp_paribas_value100_value_addition_entry(),
    ]


def parse_bnp_paribas_legacy_recorded_variable_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_bnp_paribas_legacy_recorded_variable_life_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    version = BNP_PARIBAS_LEGACY_RECORDED_VARIABLE_LIFE_VERSIONS[product_id]
    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        len(text) < 5000
        or document.get("source_text_extractor")
        != version["source_text_extractor"]
        or document.get("page_count") != version["page_count"]
        or sha256_bytes(text.encode("utf-8"))
        != version["normalized_text_sha256"]
    ):
        return None
    dense_text = compact_table_text(text)
    front_dense = compact_table_text(text[:1800])
    if (
        any(
            compact_table_text(signal) not in front_dense
            for signal in version["identity_signals"]
        )
        or compact_table_text("給付項目") not in front_dense
        or compact_table_text("滿期保險金") not in front_dense
        or compact_table_text("完全殘廢保險金") not in front_dense
        or compact_table_text("未償款項或保單借款本息者")
        not in dense_text
    ):
        return None

    foreign_currency = version["currency_basis"] == "foreign_currency"
    common_characteristics = {
        "source_product_id": product_id,
        "source_document_sha256": version["source_document_sha256"],
        "source_text_sha256": version["normalized_text_sha256"],
        "source_text_extractor": version["source_text_extractor"],
        "source_page_count": version["page_count"],
        "product_family": (
            "bnp-paribas-legacy-recorded-variable-life"
        ),
        "product_family_key": version["family_key"],
        "company_group": "bnp_paribas_cardif_life",
        "terms_revision": version["terms_revision"],
        "currency_basis": version["currency_basis"],
        "contract_currency_required": foreign_currency,
        "remittance_fee_required": foreign_currency,
        "investment_linked_policy": True,
        "variable_life_policy": True,
        "maturity_trigger": "age_110_policy_anniversary",
        "maturity_benefit_formula": (
            "maturity_policy_account_value_at_next_valuation_date_minus_offsets"
        ),
        "benefit_valuation_policy_account_value_required": True,
        "policy_effect_status_required": True,
        "policy_offsets_required": True,
        "funeral_benefit_limit_rule": True,
        "funeral_benefit_excludes_account_value": True,
        "minor_death_before_age_15_account_value_rule": True,
        "minor_disability_before_age_15_account_value_rule": True,
        "complete_disability_table_item_count": 7,
        "disability_term": "殘廢",
        "non_participating_policy": True,
    }

    if version["formula_variant"] == "paid_premium_factor":
        required_signals = [
            "各期已繳納的保險費總額扣除所有部分提領帳戶金額",
            "乘上要保人於要保書中所指定之百分比或倍數",
            "甲型",
            "乙型",
            "保單帳戶價值",
            "滿十五足歲前無危險保額",
        ]
        if any(
            compact_table_text(signal) not in dense_text
            for signal in required_signals
        ):
            return None
        if foreign_currency and (
            compact_table_text("約定外幣") not in dense_text
            or compact_table_text("扣除匯款相關費用後給付")
            not in dense_text
        ):
            return None
        required_policy_inputs = [
            "policy_type",
            "paid_premium_total",
            "partial_termination_amount_total",
            "specified_percent_or_multiplier",
            "specified_factor_unit",
            "benefit_valuation_policy_account_value",
            "insured_age_at_event",
            "policy_effect_status_at_event",
            "claim_time_status",
            "benefit_exclusion_status",
            "policy_loan_and_interest_amount",
            "unpaid_policy_charge_amount",
            "death_benefit_status",
            "remaining_funeral_benefit_limit",
            "funeral_excess_insurance_cost_refund_status",
            "funeral_excess_insurance_cost_refund_amount",
            "total_disability_qualification_status",
            "maturity_policy_account_value",
        ]
        if foreign_currency:
            required_policy_inputs.extend(
                ["contract_currency", "remittance_fee_amount"]
            )
        return {
            "selection_type": "paid_premium_factor_plan",
            "input_mode": "paid_premium_factor_plan",
            "selection_source": "terms",
            "selection_label": "保險型態與保單目前記載金額",
            "selection_guidance": "請選擇甲型或乙型，並依最新保單明細輸入累計保費、累計部分提領、指定倍數與條款指定給付評價日帳戶價值。",
            "plan_options": [
                {"value": label, "label": label}
                for label in ["甲型", "乙型"]
            ],
            "version_characteristics": {
                **common_characteristics,
                "input_formula_variant": "paid_premium_factor",
                "specified_factor_unit_required": True,
                "death_benefit_formula": (
                    "paid_premium_basis_times_specified_factor_or_plus_benefit_valuation_account_value_by_type_minus_offsets"
                ),
                "total_disability_benefit_formula": (
                    "paid_premium_basis_times_specified_factor_or_plus_benefit_valuation_account_value_by_type_minus_offsets"
                ),
                "policy_type_options": ["甲型", "乙型"],
                "formula_by_type": {
                    "甲型": "max((paid_premium_total - partial_termination_amount_total) * specified_factor, benefit_valuation_policy_account_value)",
                    "乙型": "(paid_premium_total - partial_termination_amount_total) * specified_factor + benefit_valuation_policy_account_value",
                },
                "required_policy_inputs": required_policy_inputs,
            },
            "coverage_entries": bnp_paribas_legacy_paid_premium_entries(
                foreign_currency=foreign_currency
            ),
        }

    required_signals = [
        "超值100變額壽險",
        "保險金額、基本保額與保單帳戶價值三者之較大值給付",
        "加值給付金及其給付條件",
        "前期累積所繳分期保險費平均值",
        "61次",
        "121次",
        "直接投入新台幣貨幣帳戶",
    ]
    if any(
        compact_table_text(signal) not in dense_text
        for signal in required_signals
    ):
        return None
    required_policy_inputs = [
        "current_policy_amount",
        "basic_face_amount",
        "benefit_valuation_policy_account_value",
        "insured_age_at_event",
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_policy_charge_amount",
        "death_benefit_status",
        "remaining_funeral_benefit_limit",
        "maturity_policy_account_value",
        "installment_premium_frequency",
        "previous_installment_premium_cumulative_count",
        "current_installment_premium_cumulative_count",
        "previous_installment_premium_average_amount",
        "value_addition_qualification_status",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "保單目前記載金額與加值給付狀態",
        "selection_guidance": "請依最新保單明細輸入目前保險金額、目前基本保額、條款指定給付評價日帳戶價值，以及加值給付所需的繳別與前後期累積次數。",
        "version_characteristics": {
            **common_characteristics,
            "input_formula_variant": "three_way_recorded_amounts",
            "death_benefit_formula": (
                "max(current_policy_amount,basic_face_amount,benefit_valuation_policy_account_value)_minus_offsets"
            ),
            "total_disability_benefit_formula": (
                "max(current_policy_amount,basic_face_amount,benefit_valuation_policy_account_value)_minus_offsets"
            ),
            "policy_type_options": ["丙型"],
            "formula_by_type": {
                "丙型": "max(current_policy_amount,basic_face_amount,benefit_valuation_policy_account_value)"
            },
            "required_policy_inputs": required_policy_inputs,
            "value_addition_formula": (
                "installment_premium_frequency_and_count_band_times_previous_average"
            ),
            "value_addition_rate_bands": [
                {"count_range": "0-60", "rate_percent": 0},
                {"count_range": "61-120", "rate_percent": 1},
                {"count_range": "121+", "rate_percent": 2},
            ],
            "value_addition_credit_destination": "twd_money_account",
            "value_addition_already_reflected_in_account_value_after_credit": True,
        },
        "coverage_entries": bnp_paribas_legacy_three_way_entries(),
    }


