BNP_PARIBAS_BAOFU_VARIABLE_LIFE_PRODUCT_IDS = frozenset(
    f"267191M32A001{version:02d}" for version in range(13) if version != 10
)


def is_bnp_paribas_baofu_variable_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    file_name = str(document.get("file_name") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-173"
        and product_id in BNP_PARIBAS_BAOFU_VARIABLE_LIFE_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and file_name.lower() == f"{product_id.lower()}-a.pdf"
    )


