def parse_bnp_paribas_baofu_variable_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_bnp_paribas_baofu_variable_life_strict_source(document):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if len(text) < 10_000:
        return None
    dense_text = compact_table_text(text)
    front_matter = compact_table_text(text[:2500])
    if (
        "法商法國巴黎人壽保富變額壽險" not in front_matter
        or "批註條款" in front_matter
        or "變額萬能壽險" in front_matter
    ):
        return None

    required_signals = [
        "滿期保險金的給付",
        "一般身故保險金之給付",
        "意外傷害身故保險金之給付",
        "一般殘廢保險金之給付",
        "意外傷害殘廢保險金之給付",
        "一般身故及一般殘廢保險金額",
        "意外傷害身故及意外傷害殘廢保險金額",
        "本公司按「一般身故及一般殘廢保險金額」給付",
        "本公司按「一般身故及一般殘廢保險金額」加上「意外傷害身故及意外傷害殘廢保險金額」給付",
        "本公司將以本契約約定之幣別及方式計算保單帳戶價值作為滿期保險金",
        "意外傷害事故發生之日起一百八十日以內",
        "自得為請求之日起,經過兩年不行使而消滅",
        "新台幣與外幣之轉換",
        "參考機構掛牌匯率之大額匯率",
        "完全殘廢程度表",
    ]
    if any(compact_table_text(signal) not in dense_text for signal in required_signals):
        return None
    if "喪葬費用保險金" in text or "未滿十五足歲" in text:
        return None

    required_policy_inputs = [
        "maturity_policy_account_value",
        "policy_value_component",
        "general_death_disability_insurance_amount",
        "accidental_death_disability_insurance_amount",
        "policy_values_converted_to_twd",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "事故時保單價值與一般／意外保險金額",
        "selection_guidance": (
            "請依事故時點輸入條款所稱的保單價值或保單帳戶價值，"
            "以及保單記載的一般與意外傷害身故／完全殘廢保險金額；"
            "確認保險公司已依評價日與匯率換算為新臺幣後再勾選確認。"
        ),
        "version_characteristics": {
            "product_family": "bnp-paribas-baofu-variable-life",
            "company_group": "bnp_paribas_cardif_life",
            "currency_basis": "twd",
            "investment_linked_policy": True,
            "variable_life_policy": True,
            "separate_general_and_accident_amounts": True,
            "maturity_trigger": "policy_maturity_date",
            "maturity_benefit_formula": (
                "maturity_policy_account_value_after_asset_valuation_and_fx"
            ),
            "general_event_benefit_formula": (
                "policy_value_component_plus_general_insurance_amount"
            ),
            "accidental_event_benefit_formula": (
                "policy_value_component_plus_general_and_accidental_insurance_amount"
            ),
            "required_policy_inputs": required_policy_inputs,
            "policy_value_component_required": True,
            "general_insurance_amount_required": True,
            "accidental_insurance_amount_required": True,
            "policy_value_timing_required": True,
            "policy_values_twd_confirmation_required": True,
            "current_endorsed_insurance_amounts_required": True,
            "accidental_event_payment_days": 180,
            "accidental_event_after_180_days_requires_causation_review": True,
            "claim_limitation_years": 2,
            "claim_limit_expired_formula": (
                "policy_account_value_at_first_valuation_date_after_claim_submission_return_only"
            ),
            "calculation_scope": "coverage_amount_if_terms_conditions_met",
            "payout_currency": "twd",
            "foreign_asset_fx_conversion_required": True,
            "exchange_rate_basis": (
                "asset_valuation_date_reference_institution_large_amount_rate"
            ),
            "accidental_reserve_refund_on_general_event": True,
            "accidental_reserve_refund_separate_from_insurance_benefit": True,
            "complete_disability_table_item_count": 7,
        },
        "coverage_entries": bnp_paribas_baofu_variable_life_entries(),
    }


