def parse_bnp_paribas_hengfu_variable_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_bnp_paribas_hengfu_variable_life_strict_source(document):
        return None

    product_id = str(document.get("product_id") or "")
    version = BNP_PARIBAS_HENGFU_VARIABLE_LIFE_VERSIONS[product_id]
    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        len(text) < 5000
        or document.get("source_text_extractor") != "pypdf"
        or document.get("page_count") != version["page_count"]
        or sha256_bytes(text.encode("utf-8"))
        != version["normalized_text_sha256"]
    ):
        return None
    dense_text = compact_table_text(text)
    front_matter = compact_table_text(text[:2500])
    if (
        "法商法國巴黎人壽恆富變額壽險" not in front_matter
        or "批註條款" in front_matter
        or "變額萬能壽險" in front_matter
    ):
        return None
    if (
        product_id
        in BNP_PARIBAS_HENGFU_MISSING_REFERENCED_APPENDIX_PRODUCT_IDS
        or compact_table_text("附表三完全殘廢程度表")
        not in dense_text
    ):
        return None

    required_signals = [
        "保險金額",
        "截至評價日各期已繳納的保險費總額扣除所有部分終止金額之餘額乘上要保人於要保書中所指定之百分比",
        "滿期保險金的給付",
        "滿期日次一評價日之保單帳戶價值",
        "身故保險金或喪葬費用保險金的給付",
        "甲型以被保險人身故時之保險金額相較於",
        "乙型以被保險人身故時之保險金額加上",
        "完全殘廢保險金的給付",
        "甲型以完全殘廢確定時之保險金額相較於",
        "乙型以完全殘廢確定時之保險金額加上",
        "投保年齡的計算及錯誤的處理",
        "按原繳保障費用與應繳保障費用的比例提高保險金額",
        "按原繳保障費用與應繳保障費用的比例減少保險金額",
    ]
    if any(compact_table_text(signal) not in dense_text for signal in required_signals):
        return None
    if "新台幣" not in text:
        return None

    uses_current_insurance_amount = (
        product_id in BNP_PARIBAS_HENGFU_CURRENT_AMOUNT_PRODUCT_IDS
    )
    modern_funeral_rule = version["revision"] >= 8
    if uses_current_insurance_amount and not (
        "保險金額有所變更時以變更後之保險金額為準" in dense_text
        or "申請繳納保險費或增減保險金額" in dense_text
    ):
        return None
    if not uses_current_insurance_amount and any(
        signal in dense_text
        for signal in (
            "保險金額有所變更時以變更後之保險金額為準",
            "申請繳納保險費或增減保險金額",
        )
    ):
        return None
    if modern_funeral_rule:
        modern_funeral_signals = [
            "致不能辨識其行為或欠缺依其辨識而行為之能力",
            "遺產稅喪葬費扣除額之半數",
            "返還超過部分之已扣除保障費用",
        ]
        if (
            "以下條款適用乙型" in dense_text
            or any(
                compact_table_text(signal) not in dense_text
                for signal in modern_funeral_signals
            )
        ):
            return None
        semantic_phase = (
            "current_recorded_amount_modern_mental_capacity_funeral"
        )
        funeral_limit_basis = (
            "legal_incapacity_half_estate_tax_funeral_deduction"
        )
        funeral_limit_plan_options = ["甲型", "乙型"]
    else:
        legacy_funeral_signals = [
            "以下條款適用乙型",
            "未滿十四足歲之未成年人",
            "心神喪失或精神耗弱",
            "返還超過部分之已繳保障費用",
        ]
        if any(
            compact_table_text(signal) not in dense_text
            for signal in legacy_funeral_signals
        ):
            return None
        semantic_phase = (
            "current_recorded_amount_legacy_funeral"
            if uses_current_insurance_amount
            else "paid_premium_formula_legacy_funeral"
        )
        funeral_limit_basis = (
            "legacy_under_age_14_or_mental_incapacity"
        )
        funeral_limit_plan_options = ["乙型"]

    if (
        compact_table_text("若已超過") not in dense_text
        or compact_table_text("次一評價日") not in dense_text
        or compact_table_text("因第一項各款情形而免給付各項保險金者")
        not in dense_text
        or compact_table_text("保單帳戶價值") not in dense_text
    ):
        return None

    policy_types = ["甲型", "乙型"]
    if uses_current_insurance_amount:
        selection_type = "face_amount_plan"
        face_amount_label = "事故時有效保險金額"
        selection_label = "有效保險金額與保險型態"
        selection_guidance = (
            "請輸入保單首頁、批註或最近通知所記載的事故時有效保險金額，"
            "並選擇甲型或乙型，再補入條款指定評價日的保單帳戶價值。"
        )
        required_policy_inputs = [
            "current_effective_insurance_amount",
            "policy_type",
            "benefit_valuation_policy_account_value",
            "policy_effect_status_at_event",
            "claim_time_status",
            "benefit_exclusion_status",
            "insured_age_accuracy_status",
            "total_disability_qualification_status",
            "death_benefit_status",
            "remaining_funeral_benefit_limit",
            "funeral_excess_insurance_cost_refund_status",
            "funeral_excess_insurance_cost_refund_amount",
            "maturity_policy_account_value",
        ]
        insurance_amount_source = "latest_policy_record_or_endorsement"
    else:
        selection_type = "paid_premium_factor_plan"
        face_amount_label = None
        selection_label = "保險型態與已繳保費公式"
        selection_guidance = (
            "請選擇甲型或乙型，並輸入截至評價日已繳保險費總額、"
            "累計部分終止金額、要保書指定百分比與保單帳戶價值。"
        )
        required_policy_inputs = [
            "policy_type",
            "paid_premium_total",
            "partial_termination_amount_total",
            "specified_percent_or_multiplier",
            "benefit_valuation_policy_account_value",
            "policy_effect_status_at_event",
            "claim_time_status",
            "benefit_exclusion_status",
            "insured_age_accuracy_status",
            "total_disability_qualification_status",
            "death_benefit_status",
            "remaining_funeral_benefit_limit",
            "funeral_excess_insurance_cost_refund_status",
            "funeral_excess_insurance_cost_refund_amount",
            "maturity_policy_account_value",
        ]
        insurance_amount_source = "paid_premium_formula"

    schedule = {
        "selection_type": selection_type,
        "input_mode": selection_type,
        "selection_source": "terms",
        "selection_label": selection_label,
        "selection_guidance": selection_guidance,
        "plan_options": [{"value": label, "label": label} for label in policy_types],
        "version_characteristics": {
            "source_batch_id": "tii-life-173",
            "source_product_id": product_id,
            "source_document_sha256": version["source_document_sha256"],
            "source_text_sha256": version["normalized_text_sha256"],
            "source_text_extractor": "pypdf",
            "source_page_count": version["page_count"],
            "source_text_quality": "verified_full_text",
            "product_family": "bnp-paribas-hengfu-variable-life",
            "company_group": "bnp_paribas_cardif_life",
            "terms_revision": (
                "original"
                if version["revision"] == 0
                else f"partial_change_{version['revision']}"
            ),
            "semantic_phase": semantic_phase,
            "version_group": (
                "current_effective_insurance_amount"
                if uses_current_insurance_amount
                else "paid_premium_formula"
            ),
            "currency_basis": "twd",
            "investment_linked_policy": True,
            "variable_life_policy": True,
            "variable_universal_life_policy": False,
            "maturity_trigger": "policy_maturity_date",
            "maturity_benefit_formula": "policy_account_value_at_next_valuation_date_after_maturity",
            "death_benefit_formula": (
                "current_effective_insurance_amount_or_plus_policy_account_value_by_type"
                if uses_current_insurance_amount
                else "paid_premium_basis_times_specified_factor_or_plus_policy_account_value_by_type"
            ),
            "total_disability_benefit_formula": (
                "current_effective_insurance_amount_or_plus_policy_account_value_by_type"
                if uses_current_insurance_amount
                else "paid_premium_basis_times_specified_factor_or_plus_policy_account_value_by_type"
            ),
            "formula_by_type": {
                "甲型": (
                    "max(current_effective_insurance_amount, benefit_valuation_policy_account_value)"
                    if uses_current_insurance_amount
                    else "max((paid_premium_total - partial_termination_amount_total) * (specified_percent / 100), benefit_valuation_policy_account_value)"
                ),
                "乙型": (
                    "current_effective_insurance_amount + benefit_valuation_policy_account_value"
                    if uses_current_insurance_amount
                    else "(paid_premium_total - partial_termination_amount_total) * (specified_percent / 100) + benefit_valuation_policy_account_value"
                ),
            },
            "policy_type_options": policy_types,
            "insurance_amount_source": insurance_amount_source,
            "insurance_amount_change_rules_present": uses_current_insurance_amount,
            "required_policy_inputs": required_policy_inputs,
            "specified_factor_unit_fixed": (
                None if uses_current_insurance_amount else "percent"
            ),
            "age_based_minimum_rate_adjustment_applies": (
                uses_current_insurance_amount
            ),
            "age_based_minimum_rate_schedule": (
                [
                    {
                        "min_age": (
                            15 if modern_funeral_rule else 0
                        ),
                        "max_age": 40,
                        "factor": 1.3,
                    },
                    {"min_age": 41, "max_age": 70, "factor": 1.15},
                    {"min_age": 71, "max_age": 130, "factor": 1.01},
                ]
                if uses_current_insurance_amount
                else []
            ),
            "benefit_valuation_policy_account_value_required": True,
            "maturity_policy_account_value_required": True,
            "policy_effect_status_required": True,
            "claim_time_status_required": True,
            "benefit_exclusion_status_required": True,
            "insured_age_accuracy_status_required": True,
            "total_disability_qualification_status_required": True,
            "redemption_valuation_timing_required": True,
            "account_value_return_on_time_bar": True,
            "account_value_return_on_exclusion": True,
            "funeral_benefit_limit_rule": True,
            "funeral_benefit_excludes_account_value": True,
            "funeral_limit_basis": funeral_limit_basis,
            "funeral_limit_plan_options": funeral_limit_plan_options,
            "funeral_excess_insurance_cost_refund_applies": True,
            "minor_account_value_return": False,
            "complete_disability_table_item_count": 7,
            "disability_term": "完全殘廢",
            "non_participating_policy": True,
        },
        "coverage_entries": bnp_paribas_hengfu_variable_life_entries(
            uses_current_insurance_amount=uses_current_insurance_amount,
            funeral_limit_plan_options=funeral_limit_plan_options,
        ),
    }
    if face_amount_label:
        schedule["face_amount_label"] = face_amount_label
    return schedule


def is_bnp_paribas_variable_life_net_risk_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    file_name = str(document.get("file_name") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-173"
        and product_id.startswith(("267131MV1A", "267141M31A", "267191M31A"))
        and document.get("document_type") == "policy_terms"
        and file_name.lower() == f"{product_id.lower()}-a.pdf"
    )


def bnp_paribas_variable_life_net_risk_definition(text: str) -> str:
    match = re.search(
        r"淨危險保額\s*[:：](.{0,1200}?)(?:[三四五六]、\s*(?:「)?保險金額|[三四五六]、\s*保險費)",
        text,
        re.DOTALL,
    )
    if match:
        return match.group(1)
    start = text.find("淨危險保額")
    return text[start : start + 1200] if start >= 0 else ""


def bnp_paribas_variable_life_policy_types(net_risk_text: str) -> list[str]:
    return [label for label in ("甲型", "乙型") if label in net_risk_text]


def bnp_paribas_variable_life_entries(
    disability_term: str,
    *,
    has_minor_death_account_value_rule: bool,
    has_minor_disability_account_value_rule: bool,
    currency_state_key: str | None = None,
) -> list[dict[str, Any]]:
    source_ref_benefits = "祝壽保險金／身故保險金或喪葬費用保險金／完全失能或完全殘廢保險金的給付"
    insurance_amount_conditions = [
        "保險金額為淨危險保額與保單帳戶價值兩者之總和。",
        "甲型淨危險保額為基本保額扣除保單帳戶價值後之餘額，且不得為負值；乙型淨危險保額為基本保額。",
        "淨危險保額及保單帳戶價值須以受益人檢齊申請文件並送達公司後第一個資產評價日計算。",
    ]
    entries = [
        coverage_entry(
            "maturity-benefit",
            "祝壽保險金",
            None,
            "policy_account_value",
            "被保險人於滿期日仍生存且契約有效時，按滿期日之後第一個資產評價日之保單帳戶價值給付。",
            "祝壽保險金的給付",
            calculation_basis="account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="policy_account_value",
            currency_state_key=currency_state_key,
            conditions=[
                "給付祝壽保險金後，本契約效力即行終止。",
                "實際金額需依滿期日後第一個資產評價日之保單帳戶價值確認。",
            ],
        ),
        coverage_entry(
            "death-or-funeral-benefit",
            "身故保險金或喪葬費用保險金",
            None,
            "policy_recorded_limit",
            "被保險人於契約有效期間內身故者，按保險金額給付身故保險金；受監護宣告或條款所列情形者改給付喪葬費用保險金。",
            "身故保險金或喪葬費用保險金的給付",
            calculation_basis="net_amount_at_risk_plus_policy_account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="net_amount_at_risk_plus_policy_account_value",
            currency_state_key=currency_state_key,
            minor_account_value_return_age=(
                15 if has_minor_death_account_value_rule else None
            ),
            conditions=insurance_amount_conditions
            + [
                "喪葬費用保險金額不包含其屬投資部分之保單帳戶價值。",
                "喪葬費用保險金受遺產稅喪葬費扣除額半數上限及同業合計規則限制。",
            ],
        ),
        coverage_entry(
            "total-disability-benefit",
            f"完全{disability_term}保險金",
            None,
            "policy_recorded_limit",
            f"被保險人於契約有效期間內致成條款附表所列完全{disability_term}程度之一者，按保險金額給付完全{disability_term}保險金。",
            f"完全{disability_term}保險金的給付",
            calculation_basis="net_amount_at_risk_plus_policy_account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="net_amount_at_risk_plus_policy_account_value",
            currency_state_key=currency_state_key,
            minor_account_value_return_age=(
                15 if has_minor_disability_account_value_rule else None
            ),
            conditions=insurance_amount_conditions
            + [
                f"同時有兩項以上完全{disability_term}時，公司僅給付一項完全{disability_term}保險金。",
                f"給付完全{disability_term}保險金後，本契約效力即行終止。",
            ],
        ),
    ]
    if has_minor_death_account_value_rule:
        entries[1]["conditions"].append(
            "訂立契約時以未滿十五足歲之未成年人為被保險人者，滿十五足歲前死亡改返還保單帳戶價值。"
        )
    if has_minor_disability_account_value_rule:
        entries[2]["conditions"].append(
            f"被保險人於十五足歲前致成完全{disability_term}者，改以保單帳戶價值給付完全{disability_term}保險金。"
        )
    return entries


def parse_bnp_paribas_variable_life_net_risk_account_value(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_bnp_paribas_variable_life_net_risk_strict_source(document):
        return None

    product_id = str(document.get("product_id") or "")
    text = normalize_terms_text(str(document.get("text") or ""))
    if len(text) < 5000:
        return None
    dense_text = compact_table_text(text)
    required_signals = [
        "變額壽險",
        "投資標的",
        "保單帳戶價值",
        "淨危險保額",
        "保險型態",
        "基本保額",
        "保險金額",
        "祝壽保險金的給付",
        "身故保險金或喪葬費用保險金的給付",
    ]
    if any(compact_table_text(signal) not in dense_text for signal in required_signals):
        return None
    if "保單帳戶價值給付祝壽保險金" not in dense_text:
        return None
    if compact_table_text("完全失能保險金的給付") in dense_text:
        disability_term = "失能"
    elif compact_table_text("完全殘廢保險金的給付") in dense_text:
        disability_term = "殘廢"
    else:
        return None
    gate_text = dense_text.replace("「", "").replace("」", "")
    if "按保險金額給付" not in gate_text and "保險金額給付" not in gate_text:
        return None

    net_risk_text = bnp_paribas_variable_life_net_risk_definition(text)
    net_risk_dense = compact_table_text(net_risk_text)
    policy_types = bnp_paribas_variable_life_policy_types(net_risk_text)
    if policy_types != ["甲型", "乙型"]:
        return None
    if any(label in net_risk_text for label in ("丙型", "丁型")):
        return None
    if (
        "基本保額扣除保單帳戶價值" not in net_risk_dense
        or "不得為負值" not in net_risk_dense
    ):
        return None
    if "保險金扣除額" in text or "門檻係數" in text:
        return None

    has_minor_death_account_value_rule = (
        "滿十五足歲前死亡" in text or "未滿十五足歲" in text
    )
    has_minor_disability_account_value_rule = (
        "十五足歲前致成附表" in dense_text
        or f"十五足歲前，致成附表" in text
        or f"滿十五足歲以前致成完全{disability_term}" in dense_text
        or f"未滿十五足歲前致成完全{disability_term}" in dense_text
    )
    front_matter = text[:3000]
    currency_basis = (
        "foreign_currency"
        if "外幣變額壽險" in front_matter or re.search(r"23Z", product_id)
        else "twd"
    )
    currency_state_key = (
        "contract_currency" if currency_basis == "foreign_currency" else None
    )
    required_inputs = [
        "basic_face_amount",
        "policy_type",
        "policy_account_value",
    ]
    if currency_state_key:
        required_inputs.append(currency_state_key)
    if (
        has_minor_death_account_value_rule
        or has_minor_disability_account_value_rule
    ):
        required_inputs.append("insured_age_at_event")

    return {
        "selection_type": "face_amount_plan",
        "input_mode": "face_amount_plan",
        "selection_source": "terms",
        "selection_label": "基本保額與保險型態",
        "selection_guidance": "請輸入保單上的基本保額，並依保單現況補入保險型態與保單帳戶價值；本商品身故、完全失能或完全殘廢給付需依淨危險保額加保單帳戶價值計算，祝壽金依滿期後第一個資產評價日保單帳戶價值給付。",
        "plan_options": [
            {"value": label, "label": label} for label in policy_types
        ],
        "version_characteristics": {
            "product_family": "bnp-paribas-variable-life-net-risk-account-value",
            "company_group": "bnp_paribas_cardif_life",
            "currency_basis": currency_basis,
            "contract_currency_required": bool(currency_state_key),
            "investment_linked_policy": True,
            "variable_life_policy": True,
            "maturity_trigger": "policy_maturity_date",
            "maturity_benefit_formula": "policy_account_value_at_first_asset_valuation_date_after_maturity",
            "death_benefit_formula": "net_amount_at_risk_plus_policy_account_value",
            "total_disability_benefit_formula": "net_amount_at_risk_plus_policy_account_value",
            "net_amount_at_risk_formula_by_type": {
                "甲型": "max(basic_face_amount - policy_account_value, 0)",
                "乙型": "basic_face_amount",
            },
            "policy_type_options": policy_types,
            "required_policy_inputs": required_inputs,
            "policy_face_amount_required": True,
            "policy_type_required": True,
            "policy_account_value_required": True,
            "insurance_amount_basis": "net_amount_at_risk_plus_policy_account_value",
            "redemption_valuation_timing_required": True,
            "funeral_benefit_limit_rule": True,
            "funeral_benefit_excludes_account_value": True,
            "minor_death_before_age_15_account_value_rule": has_minor_death_account_value_rule,
            "minor_disability_before_age_15_account_value_rule": has_minor_disability_account_value_rule,
            "complete_disability_table_item_count": 7,
            "disability_term": disability_term,
            "non_participating_policy": True,
        },
        "coverage_entries": bnp_paribas_variable_life_entries(
            disability_term,
            has_minor_death_account_value_rule=has_minor_death_account_value_rule,
            has_minor_disability_account_value_rule=has_minor_disability_account_value_rule,
            currency_state_key=currency_state_key,
        ),
    }


BNP_PARIBAS_ZERO_LIMIT_VARIABLE_UNIVERSAL_LIFE_REVISIONS = {
    "267141M31A03800": 0,
    "267141M31A03801": 1,
    **{
        f"267131MV1A03823A11C9{revision:07d}": revision
        for revision in range(2, 14)
    },
}
BNP_PARIBAS_ZERO_LIMIT_VARIABLE_UNIVERSAL_LIFE_PRODUCT_IDS = frozenset(
    BNP_PARIBAS_ZERO_LIMIT_VARIABLE_UNIVERSAL_LIFE_REVISIONS
)


def is_bnp_paribas_zero_limit_variable_universal_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    file_name = str(document.get("file_name") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-173"
        and product_id
        in BNP_PARIBAS_ZERO_LIMIT_VARIABLE_UNIVERSAL_LIFE_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and file_name.lower() == f"{product_id.lower()}-a.pdf"
    )


def bnp_paribas_zero_limit_variable_universal_life_revision(
    product_id: str,
) -> int:
    return BNP_PARIBAS_ZERO_LIMIT_VARIABLE_UNIVERSAL_LIFE_REVISIONS[
        product_id
    ]


def bnp_paribas_zero_limit_variable_universal_life_entries(
    *,
    revision: int,
    disability_term: str,
    has_minor_account_value_rule: bool,
    maturity_interest_crediting: bool,
) -> list[dict[str, Any]]:
    original_formula = revision == 0
    death_policy_state_keys = (
        [
            "current_policy_amount",
            "basic_face_amount",
            "benefit_valuation_policy_account_value",
        ]
        if original_formula
        else [
            "basic_face_amount",
            "current_threshold_face_amount",
            "benefit_valuation_policy_account_value",
        ]
    )
    maturity_policy_state_keys = (
        ["maturity_policy_account_value", "maturity_interest_amount"]
        if maturity_interest_crediting
        else ["maturity_policy_account_value"]
    )
    maturity_name = "滿期保險金" if original_formula else "祝壽保險金"
    formula_conditions = (
        [
            "給付為當年度保險金額、基本保額與條款指定給付評價日之保單帳戶價值三者取最大值。",
            "當年度保險金額與基本保額須使用事故時有效的保單、批註或契約變更通知所列金額。",
        ]
        if original_formula
        else [
            "給付為基本保額、目前門檻保額與受益人備齊文件送達保險公司後第一個資產評價日之保單帳戶價值三者取最大值。",
            "門檻保額只在投保、每次繳納保險費或部分提領時依當時帳戶價值與保價乘數重算；請輸入保單或保險公司目前列示的門檻保額。",
            "不可使用目前年齡與目前保單帳戶價值回推歷次事件後的門檻保額。",
        ]
    )
    minor_conditions = (
        [
            "事故時未滿十五足歲，依條款改以保單帳戶價值給付或返還，不適用一般取最大值公式。"
        ]
        if has_minor_account_value_rule
        else []
    )
    maturity_conditions = [
        "滿期金額須使用滿期日後條款指定資產評價日的保單帳戶價值；不可用目前帳戶價值推定未來金額。",
    ]
    if maturity_interest_crediting:
        maturity_conditions = [
            "本版本祝壽保險金除滿期日後第一個資產評價日的保單帳戶價值外，另依條款逐日以日單利加計利息。",
            "請分別輸入滿期保單帳戶價值及保險公司按指定利率與日期列示的利息；系統加總兩者，不以目前帳戶價值或目前利率自行推估。",
        ]

    return [
        coverage_entry(
            "maturity-benefit",
            maturity_name,
            None,
            "policy_recorded_limit",
            (
                "被保險人於滿期日仍生存且契約有效時，依條款指定的滿期保單帳戶價值"
                + ("及應加計利息" if maturity_interest_crediting else "")
                + f"給付{maturity_name}。"
            ),
            f"{maturity_name}的給付",
            calculation_basis=(
                "sum_policy_state_amounts"
                if maturity_interest_crediting
                else "policy_state_amount"
            ),
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key=(
                "maturity_policy_account_value_plus_interest"
                if maturity_interest_crediting
                else "maturity_policy_account_value"
            ),
            policy_state_keys=maturity_policy_state_keys,
            conditions=maturity_conditions,
        ),
        coverage_entry(
            "death-or-funeral-benefit",
            "身故保險金或喪葬費用保險金",
            None,
            "policy_recorded_limit",
            "被保險人於契約有效期間內身故時，依本版本條款公式計算；喪葬費用上限與受益資格仍須另依條款及法令確認。",
            "身故保險金或喪葬費用保險金的給付與保單帳戶價值之返還",
            calculation_basis="death_or_funeral_greater_of",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="highest",
            unit_key=(
                "greater_of_current_policy_basic_face_and_account_value"
                if original_formula
                else "greater_of_basic_threshold_and_account_value"
            ),
            policy_state_keys=death_policy_state_keys,
            minor_account_value_return_age=(
                15 if has_minor_account_value_rule else None
            ),
            conditions=formula_conditions
            + minor_conditions
            + [
                "喪葬費用保險金上限不包含投資部分的保單帳戶價值。",
                "適用喪葬費用限制時，系統以取高值扣除給付評價日保單帳戶價值後的保障部分，與本保單可用喪葬費用剩餘額度取小值，再加回保單帳戶價值。",
                "若已超過條款約定的請求權時效，條款改依指定評價日返還保單帳戶價值；此時不適用一般保障金額。",
            ],
        ),
        coverage_entry(
            "total-disability-benefit",
            f"完全{disability_term}保險金",
            None,
            "policy_recorded_limit",
            f"被保險人符合附表所列完全{disability_term}程度之一時，依本版本條款公式計算。",
            f"完全{disability_term}保險金的給付",
            calculation_basis="greater_of",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="highest",
            unit_key=(
                "greater_of_current_policy_basic_face_and_account_value"
                if original_formula
                else "greater_of_basic_threshold_and_account_value"
            ),
            policy_state_keys=death_policy_state_keys,
            minor_account_value_return_age=(
                15 if has_minor_account_value_rule else None
            ),
            conditions=formula_conditions
            + minor_conditions
            + [
                f"完全{disability_term}程度須符合本 product_id 對應條款附表所列七項之一。",
                f"完全{disability_term}保險金給付後，契約效力終止。",
                "若已超過條款約定的請求權時效，條款改依指定評價日返還保單帳戶價值；此時不適用一般保障金額。",
            ],
        ),
    ]


def parse_bnp_paribas_zero_limit_variable_universal_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_bnp_paribas_zero_limit_variable_universal_life_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    revision = bnp_paribas_zero_limit_variable_universal_life_revision(
        product_id
    )
    text = normalize_terms_text(str(document.get("text") or ""))
    if len(text) < 5000:
        return None
    dense_text = compact_table_text(text)
    front_matter = text[:2500]
    front_dense = compact_table_text(front_matter)
    if (
        any(
            signal not in front_dense
            for signal in [
                "法商法國巴黎人壽",
                "零極限",
                "變額萬能壽險",
            ]
        )
        or "批註條款" in front_dense
    ):
        return None

    required_signals = [
        "丙型",
        "保單帳戶價值",
        "基本保額",
        "保險金額",
        "滿期日",
        "身故保險金",
        "贖回費用",
        "不分紅保單",
        "喪葬費用保險金額",
        "不包含其屬投資部分之保單帳戶價值",
    ]
    if any(
        compact_table_text(signal) not in dense_text
        for signal in required_signals
    ):
        return None

    if compact_table_text("完全失能保險金的給付") in dense_text:
        disability_term = "失能"
    elif compact_table_text("完全殘廢保險金的給付") in dense_text:
        disability_term = "殘廢"
    else:
        return None
    expected_disability_term = "殘廢" if revision <= 5 else "失能"
    if disability_term != expected_disability_term:
        return None

    has_minor_death_account_value_rule = (
        (
            "滿十五足歲前死亡" in dense_text
            or "未滿十五足歲前身故" in dense_text
        )
        and "保單帳戶價值" in dense_text
    )
    has_minor_disability_account_value_rule = (
        re.search(
            rf"十五足歲前.{{0,160}}保單帳戶價值.{{0,80}}給付完全{disability_term}保險金",
            dense_text,
        )
        is not None
    )
    expected_minor_rule = revision <= 8
    if (
        has_minor_death_account_value_rule is not expected_minor_rule
        or has_minor_disability_account_value_rule is not expected_minor_rule
    ):
        return None

    maturity_interest_crediting = (
        "給付祝壽保險金時應加計利息" in dense_text
    )
    if maturity_interest_crediting is not (revision >= 10):
        return None
    has_time_bar_account_value_return = (
        "時效" in dense_text
        and "保單帳戶價值" in dense_text
        and "返還予應得之人" in dense_text
    )
    if not has_time_bar_account_value_return:
        return None

    if revision == 0:
        original_signals = [
            "保險金額、基本保額與保單帳戶價值三者之較大值給付",
            "申請身故保險金所須文件送達本公司之次一評價日的保單帳戶價值計算",
            "滿期日之次一個評價日之保單帳戶價值給付滿期保險金",
            "危險保額",
        ]
        if (
            "門檻保額" in dense_text
            or any(
                compact_table_text(signal) not in dense_text
                for signal in original_signals
            )
        ):
            return None
        input_formula_variant = "three_way_recorded_amounts"
        death_benefit_formula = (
            "max(current_policy_amount,basic_face_amount,"
            "benefit_valuation_policy_account_value)"
        )
