def bnp_paribas_qimandeli_threshold_multiplier_age_bands(
    revision: int,
) -> list[dict[str, Any]]:
    if revision <= 2:
        return [
            {"age_range": "18-40", "multiplier_percent": 130},
            {"age_range": "41-70", "multiplier_percent": 115},
            {"age_range": "71歲以上", "multiplier_percent": 101},
        ]
    first_age_range = "18-30" if revision == 3 else "30歲以下"
    return [
        {"age_range": first_age_range, "multiplier_percent": 190},
        {"age_range": "31-40", "multiplier_percent": 160},
        {"age_range": "41-50", "multiplier_percent": 140},
        {"age_range": "51-60", "multiplier_percent": 120},
        {"age_range": "61-70", "multiplier_percent": 110},
        {"age_range": "71-90", "multiplier_percent": 102},
        {"age_range": "91歲以上", "multiplier_percent": 100},
    ]


