def is_fubon_new_lucky_variable_universal_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FUBON_NEW_LUCKY_VARIABLE_UNIVERSAL_LIFE_VERSIONS.get(product_id)
    return (
        version is not None
        and str(document.get("batch_id") or "") == "tii-life-053"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "") == version["file_name"]
        and str(document.get("source_document_sha256") or "")
        == version["source_document_sha256"]
    )


def parse_fubon_new_lucky_variable_universal_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_fubon_new_lucky_variable_universal_life_strict_source(document):
        return None

    product_id = str(document.get("product_id") or "")
    version = FUBON_NEW_LUCKY_VARIABLE_UNIVERSAL_LIFE_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
        or hashlib.sha256(text.encode("utf-8")).hexdigest()
        != version["normalized_text_sha256"]
    ):
        return None
    dense_text = compact_table_text(text).replace("「", "").replace("」", "")
    revision = int(version["revision"])
    source_text_extractor = str(version["source_text_extractor"])
    has_minor_account_value_return = revision >= 29
    has_funeral_endorsement = revision != 11
    maturity_age = 105 if revision == 10 else 110
    maturity_age_text = "一百零五歲" if maturity_age == 105 else "一百一十歲"
    if revision <= 55:
        disability_term = "全殘廢"
        face_amount_label = "保單所載保險金額"
        terms_formula_representation = "direct_greater_or_sum"
        if revision <= 28:
            if has_funeral_endorsement:
                semantic_phase = (
                    "legacy_under14_b_funeral_maturity105"
                    if revision == 10
                    else "legacy_under14_b_funeral"
                )
                minor_death_benefit_rule = (
                    "under_14_b_type_converts_to_funeral"
                )
                funeral_limit_plan_options = ["B型"]
                funeral_eligibility_rule = (
                    "under_14_or_mental_incapacity"
                )
                funeral_limit_basis = (
                    "regulator_funeral_expense_limit"
                )
            else:
                semantic_phase = (
                    "base_terms_without_funeral_endorsement"
                )
                minor_death_benefit_rule = (
                    "not_stated_in_exact_source_document"
                )
                funeral_limit_plan_options = []
                funeral_eligibility_rule = (
                    "not_stated_in_exact_source_document"
                )
                funeral_limit_basis = ""
        else:
            semantic_phase = "under15_account_value_return"
            minor_death_benefit_rule = (
                "under_15_account_value_return"
            )
            funeral_limit_plan_options = ["B型"]
            funeral_eligibility_rule = "mental_capacity_definition"
            funeral_limit_basis = (
                "estate_tax_funeral_deduction_half"
            )
        formula_signals = [
            "A型",
            "保險金額與保單帳戶價值較大者",
            "B型",
            "保險金額加計保單帳戶價值",
            "全殘廢保險金",
        ]
        insurance_amount_formula_by_type = {
            "A型": "max(policy_recorded_insurance_amount, benefit_valuation_policy_account_value)",
            "B型": "policy_recorded_insurance_amount + benefit_valuation_policy_account_value",
        }
    else:
        semantic_phase = (
            "net_risk_legacy_funeral"
            if revision <= 71
            else "net_risk_guardianship"
        )
        minor_death_benefit_rule = "under_15_account_value_return"
        disability_term = "完全殘廢" if revision <= 71 else "完全失能"
        face_amount_label = "基本保額"
        terms_formula_representation = "net_amount_at_risk_plus_account_value"
        funeral_limit_plan_options = ["A型", "B型"]
        funeral_limit_basis = "estate_tax_funeral_deduction_half"
        funeral_eligibility_rule = (
            "mental_capacity_definition"
            if revision <= 71
            else "guardianship_declaration"
        )
        formula_signals = [
            "基本保額",
            "淨危險保額",
            "A型",
            "基本保額扣除保單帳戶價值",
            "B型",
            disability_term,
        ]
        if not (
            "等於基本保額" in dense_text
            or "為基本保額" in dense_text
        ):
            return None
        insurance_amount_formula_by_type = {
            "A型": "max(basic_face_amount - benefit_valuation_policy_account_value, 0) + benefit_valuation_policy_account_value",
            "B型": "basic_face_amount + benefit_valuation_policy_account_value",
        }

    required_signals = (
        [
            "富邦",
            "新吉祥",
            "保單帳戶",
            "祝壽",
            "身故",
            "全殘",
        ]
        if source_text_extractor == "windows_ocr"
        else [
            "富邦人壽新吉祥變額萬能終身壽險",
            "保單帳戶價值",
            "祝壽保險金",
            maturity_age_text,
            "身故保險金",
            *formula_signals,
        ]
    )
    if any(
        compact_table_text(signal) not in dense_text
        for signal in required_signals
    ):
        return None
    if source_text_extractor != "windows_ocr" and has_funeral_endorsement:
        if "喪葬費用保險金" not in dense_text:
            return None
        if revision <= 28:
            if (
                "未滿十四足歲" not in dense_text
                or (
                    "心神喪失" not in dense_text
                    and "精神耗弱" not in dense_text
                )
                or "主管機關所訂定之喪葬費用保險金額上限"
                not in dense_text
            ):
                return None
        elif funeral_eligibility_rule == "mental_capacity_definition":
            if (
                "精神障礙" not in dense_text
                and "心智缺陷" not in dense_text
            ):
                return None
        elif "受監護宣告尚未撤銷" not in dense_text:
            return None
        if funeral_limit_plan_options == ["B型"]:
            if revision <= 28:
                if (
                    "投保富邦人壽新吉祥變額萬能終身壽險B型"
                    not in dense_text
                ):
                    return None
            elif not (
                "B型之身故保險金" in dense_text
                or "B型身故保險金" in dense_text
            ):
                return None
    if (
        source_text_extractor != "windows_ocr"
        and has_minor_account_value_return
    ):
        if not re.search(
            r"(?:滿|未滿)?十五足歲前.{0,120}(?:死亡|身故).{0,180}保單帳戶價值",
            dense_text,
        ):
            return None
        if not (
            re.search(
                rf"十五足歲前.{{0,180}}{disability_term}.{{0,220}}保單帳戶價值",
                dense_text,
            )
            or re.search(
                rf"十五足歲前.{{0,300}}保單帳戶價值.{{0,180}}{disability_term}",
                dense_text,
            )
        ):
            return None

    death_benefit_formula = (
        "insurance_amount_or_account_value_before_age_15"
        if has_minor_account_value_return
        else "insurance_amount_with_under_14_b_funeral_limit"
        if has_funeral_endorsement
        else "insurance_amount"
    )
    total_disability_benefit_formula = (
        "insurance_amount_or_account_value_before_age_15"
        if has_minor_account_value_return
        else "insurance_amount"
    )
    death_entry_id = (
        "death-or-funeral-benefit"
        if has_funeral_endorsement
        else "death-benefit"
    )
    death_entry_label = (
        "身故保險金或喪葬費用保險金"
        if has_funeral_endorsement
        else "身故保險金"
    )
    if has_minor_account_value_return:
        death_summary = (
            "滿十五足歲後身故按 A 型或 B 型保險金額公式給付；"
            "十五足歲前身故改返還保單帳戶價值。符合本版條款的"
            "喪葬費用限制時，只限制保障部分，保單帳戶價值另依條款處理。"
        )
        death_conditions = [
            "滿十五足歲前死亡者，改返還保單帳戶價值。",
            "喪葬費用保險金受遺產稅喪葬費扣除額半數及同業合計規則限制。",
            (
                "本版條款僅 B 型身故保障部分適用喪葬費用保險金限制；A 型不套用此項限制。"
                if revision <= 55
                else "本版條款 A 型及 B 型的身故保障部分均適用喪葬費用保險金限制。"
            ),
        ]
        disability_conditions = [
            f"十五足歲前致成條款所列{disability_term}程度者，改以保單帳戶價值給付。",
        ]
    elif has_funeral_endorsement:
        death_summary = (
            "身故按 A 型或 B 型保險金額公式給付；以未滿十四足歲"
            "未成年人或條款所列心神狀態為被保險人時，B 型保障部分"
            "改為喪葬費用保險金，投資部分的保單帳戶價值不納入上限。"
        )
        death_conditions = [
            "本版僅 B 型符合批註條款資格時，保障部分改為喪葬費用保險金。",
            "喪葬費用保險金受主管機關所定額度及同業合計規則限制。",
        ]
        disability_conditions = []
    else:
        death_summary = (
            "本精確來源文件按 A 型或 B 型保險金額公式給付身故保險金；"
            "該文件未附喪葬費用批註條款，因此不從相鄰版本推定限制。"
        )
        death_conditions = [
            "本版本僅依來源文件呈現主約身故公式；若保單另附批註，須回原保單確認。",
        ]
        disability_conditions = []

    account_value_key = "benefit_valuation_policy_account_value"
    common_formula_conditions = [
        "保險金額依保單約定的 A 型或 B 型公式及受益人檢齊文件送達公司後的條款指定資產評價時點計算。",
        "保單帳戶價值會隨投資標的價格變動，網站試算須使用對應給付評價時點的實際金額。",
    ]
    entries = [
        coverage_entry(
            "maturity-benefit",
            "祝壽保險金",
            None,
            "policy_recorded_limit",
            f"被保險人保險年齡到達{maturity_age_text}之保單週年日仍生存且契約有效時，依條款指定贖回評價時點的保單帳戶價值給付。",
            "保單條款，祝壽保險金的給付",
            calculation_basis="maturity_policy_account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="maturity_policy_account_value",
            conditions=[
                "給付祝壽保險金後，本契約效力即行終止。",
                "實際金額須由滿期給付所適用的贖回評價時點保單帳戶價值確認。",
            ],
        ),
        coverage_entry(
            death_entry_id,
            death_entry_label,
            None,
            "policy_recorded_limit",
            death_summary,
            f"保單條款，{death_entry_label}的給付",
            calculation_basis="net_amount_at_risk_plus_policy_account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="net_amount_at_risk_plus_benefit_valuation_policy_account_value",
            policy_state_keys=[account_value_key],
            minor_account_value_return_age=(
                15 if has_minor_account_value_return else None
            ),
            funeral_limit_plan_options=funeral_limit_plan_options,
            conditions=common_formula_conditions + death_conditions,
        ),
        coverage_entry(
            "total-disability-benefit",
            f"{disability_term}保險金",
            None,
            "policy_recorded_limit",
            f"被保險人於契約有效期間內符合條款附表所列{disability_term}程度之一時，按 A 型或 B 型保險金額公式給付。",
            f"保單條款，{disability_term}保險金的給付",
            calculation_basis="net_amount_at_risk_plus_policy_account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="net_amount_at_risk_plus_benefit_valuation_policy_account_value",
            policy_state_keys=[account_value_key],
            minor_account_value_return_age=(
                15 if has_minor_account_value_return else None
            ),
            conditions=common_formula_conditions
            + disability_conditions
            + [
                f"同時符合兩項以上{disability_term}程度時，公司僅給付一項。",
                f"給付{disability_term}保險金後，本契約效力即行終止。",
            ],
        ),
    ]
    required_policy_inputs = [
        "face_amount",
        "policy_type",
        account_value_key,
        *(
            ["insured_age_at_event"]
            if has_minor_account_value_return
            else []
        ),
        *(
            [
                "death_benefit_status",
                "remaining_funeral_benefit_limit",
            ]
            if has_funeral_endorsement
            else []
        ),
        "maturity_policy_account_value",
    ]
    return {
        "selection_type": "face_amount_plan",
        "input_mode": "face_amount_plan",
        "selection_source": "terms",
        "selection_label": f"{face_amount_label}與保險型態",
        "selection_guidance": f"請輸入保單上的{face_amount_label}並選擇 A 型或 B 型；身故與{disability_term}金另需填入給付評價時點的保單帳戶價值，祝壽金則使用滿期贖回評價時點的保單帳戶價值。",
        "face_amount_label": face_amount_label,
        "plan_options": [
            {"value": "A型", "label": "A型"},
            {"value": "B型", "label": "B型"},
        ],
        "version_characteristics": {
            "product_family": "fubon-new-lucky-variable-universal-life",
            "company_group": "fubon_life",
            "source_product_id": product_id,
            "terms_revision": f"partial-change-{revision}",
            "source_document_sha256": version["source_document_sha256"],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if source_text_extractor == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_text_extractor": version["source_text_extractor"],
            "semantic_phase": semantic_phase,
            "investment_linked_policy": True,
            "variable_universal_life_policy": True,
            "policy_type_options": ["A型", "B型"],
            "face_amount_label": face_amount_label,
            "terms_formula_representation": terms_formula_representation,
            "insurance_amount_formula_by_type": insurance_amount_formula_by_type,
            "death_benefit_formula": death_benefit_formula,
            "total_disability_benefit_formula": (
                total_disability_benefit_formula
            ),
            "maturity_age": maturity_age,
            "maturity_benefit_formula": "maturity_redemption_valuation_policy_account_value",
            "benefit_valuation_policy_account_value_required": True,
            "maturity_policy_account_value_required": True,
            "minor_death_benefit_rule": minor_death_benefit_rule,
            "minor_death_before_age_15_account_value_rule": (
                has_minor_account_value_return
            ),
            "minor_disability_before_age_15_account_value_rule": (
                has_minor_account_value_return
            ),
            "funeral_limit_policy_type_options": funeral_limit_plan_options,
            "funeral_eligibility_rule": funeral_eligibility_rule,
            "funeral_limit_basis": funeral_limit_basis,
            "funeral_benefit_excludes_account_value": (
                has_funeral_endorsement
            ),
            "required_policy_inputs": required_policy_inputs,
            "disability_term": disability_term,
            "complete_disability_table_required": True,
            "non_participating_policy": True,
        },
        "coverage_entries": entries,
    }


