GLOBAL_EXCELLENCE_VARIABLE_UNIVERSAL_LIFE_VERSIONS = {
    product_id: {
        "revision": revision,
        "file_name": file_name,
        "page_count": page_count,
        "source_text_extractor": source_text_extractor,
        "source_document_sha256": source_document_sha256,
        "normalized_text_sha256": normalized_text_sha256,
    }
    for (
        product_id,
        revision,
        file_name,
        page_count,
        source_text_extractor,
        source_document_sha256,
        normalized_text_sha256,
    ) in GLOBAL_EXCELLENCE_VARIABLE_UNIVERSAL_LIFE_VERSION_ROWS
}


def is_global_excellence_variable_universal_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = GLOBAL_EXCELLENCE_VARIABLE_UNIVERSAL_LIFE_VERSIONS.get(product_id)
    return (
        version is not None
        and str(document.get("batch_id") or "") == "tii-life-167"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "") == version["file_name"]
        and str(document.get("source_document_sha256") or "")
        == version["source_document_sha256"]
    )


def parse_global_excellence_variable_universal_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_global_excellence_variable_universal_life_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    version = GLOBAL_EXCELLENCE_VARIABLE_UNIVERSAL_LIFE_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
        or hashlib.sha256(text.encode("utf-8")).hexdigest()
        != version["normalized_text_sha256"]
    ):
        return None
    dense_text = compact_table_text(text).replace("「", "").replace("」", "")
    common_signals = [
        "卓越變額萬能壽險",
        "身故保險金",
        "全殘廢保險金",
        "九五祝壽金",
        "不分紅保險單",
        "保單帳戶價值",
        "基本保額",
        "保險型別",
        "完全殘廢",
    ]
    if any(
        compact_table_text(signal) not in dense_text
        for signal in common_signals
    ):
        return None

    revision = int(version["revision"])
    if revision <= 6:
        semantic_phase = "fixed_110_percent"
        minimum_rate_formula_variant = "fixed_110_percent"
        minimum_benefit_formula_age = 0
        threshold_factor_schedule: list[dict[str, Any]] = []
        insurance_amount_formula_by_type = {
            "A型": "max(basic_face_amount, benefit_valuation_policy_account_value * 1.1)",
            "B型": "basic_face_amount + benefit_valuation_policy_account_value",
        }
        phase_signals = [
            "一.一倍",
            "A型",
            "但不得低於基本保額",
            "B型",
            "基本保額與保單帳戶價值的總和",
        ]
    elif revision <= 19:
        semantic_phase = "age_bands_130_115_101"
        minimum_rate_formula_variant = "age_bands_130_115_101"
        minimum_benefit_formula_age = 0
        threshold_factor_schedule = [
            {"min_age": 0, "max_age": 40, "factor": 1.3},
            {"min_age": 41, "max_age": 70, "factor": 1.15},
            {"min_age": 71, "max_age": 130, "factor": 1.01},
        ]
        insurance_amount_formula_by_type = {
            "A型": "max(basic_face_amount, benefit_valuation_policy_account_value * minimum_rate)",
            "B型": "max(basic_face_amount + benefit_valuation_policy_account_value, benefit_valuation_policy_account_value * minimum_rate)",
        }
        phase_signals = [
            "保險金最低比率",
            "40歲(含)以下",
            "41歲至70歲",
            "71歲(含)以上",
            "130%",
            "115%",
            "101%",
        ]
    else:
        semantic_phase = "age_bands_15_floor_130_115_101"
        minimum_rate_formula_variant = (
            "age_bands_15_floor_130_115_101"
        )
        minimum_benefit_formula_age = 15
        threshold_factor_schedule = [
            {"min_age": 15, "max_age": 40, "factor": 1.3},
            {"min_age": 41, "max_age": 70, "factor": 1.15},
            {"min_age": 71, "max_age": 130, "factor": 1.01},
        ]
        insurance_amount_formula_by_type = {
            "A型": "max(basic_face_amount, benefit_valuation_policy_account_value * minimum_rate)",
            "B型": "max(basic_face_amount + benefit_valuation_policy_account_value, benefit_valuation_policy_account_value * minimum_rate)",
        }
        phase_signals = [
            "保險金最低比率",
            "滿十五足歲",
            "四十歲以下",
            "百分之一百三十",
            "百分之一百十五",
            "百分之一百零一",
        ]
    if any(
        compact_table_text(signal) not in dense_text
        for signal in phase_signals
    ):
        return None
    if revision >= 7:
        formula_signals = [
            "A型：保險金額為保單帳戶價值乘以保險金最低比率之金額，但不低於基本保額",
            "B型：保險金額為保單帳戶價值與基本保額的總和，但不低於保單帳戶價值乘以保險金最低比率",
        ]
        if any(
            compact_table_text(signal) not in dense_text
            for signal in formula_signals
        ):
            return None

    account_value_key = "benefit_valuation_policy_account_value"
    common_formula_conditions = [
        "保險金額依保單約定的 A 型或 B 型公式，以及事故給付評價時點的實際保單帳戶價值計算。",
        "保單帳戶價值會隨投資標的價格變動，網站試算須使用保險公司列示的對應給付評價金額。",
        "實際給付仍可能依條款扣除未清償的保單借款、利息或其他應扣款項。",
    ]
    entries = [
        coverage_entry(
            "maturity-benefit",
            "九五祝壽金",
            None,
            "policy_recorded_limit",
            "被保險人保險年齡到達九十五歲且契約仍有效時，按當時保單帳戶價值給付。",
            "保單條款，九五祝壽金的給付",
            calculation_basis="maturity_policy_account_value",
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key="maturity_policy_account_value",
            conditions=[
                "給付九五祝壽金後，本契約效力即行終止。",
                "實際金額須使用滿期時由保險公司列示的保單帳戶價值。",
            ],
        ),
        coverage_entry(
            "death-benefit",
            "身故保險金",
            None,
            "policy_recorded_limit",
            "被保險人於契約有效期間內身故時，按 A 型或 B 型保險金額公式給付。",
            "保單條款，身故保險金的給付",
            calculation_basis=(
                "net_amount_at_risk_plus_policy_account_value"
            ),
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key=(
                "net_amount_at_risk_plus_"
                "benefit_valuation_policy_account_value"
            ),
            policy_state_keys=[account_value_key],
            conditions=common_formula_conditions
            + ["給付身故保險金後，本契約效力即行終止。"],
        ),
        coverage_entry(
            "total-disability-benefit",
            "全殘廢保險金",
            None,
            "policy_recorded_limit",
            "被保險人於契約有效期間內符合條款附表所列完全殘廢情事之一時，按 A 型或 B 型保險金額公式給付。",
            "保單條款，全殘廢保險金的給付",
            calculation_basis=(
                "net_amount_at_risk_plus_policy_account_value"
            ),
            amount_role="payout",
            limit_scope="per_policy",
            aggregation_rule="separate",
            unit_key=(
                "net_amount_at_risk_plus_"
                "benefit_valuation_policy_account_value"
            ),
            policy_state_keys=[account_value_key],
            conditions=common_formula_conditions
            + [
                "同時符合兩項以上完全殘廢情事時，公司僅給付一項。",
                "給付全殘廢保險金後，本契約效力即行終止。",
            ],
        ),
    ]
    required_policy_inputs = [
        "face_amount",
        "policy_type",
        account_value_key,
        *(
            ["insured_age_at_event"]
            if revision >= 7
            else []
        ),
        "maturity_policy_account_value",
    ]
    return {
        "selection_type": "face_amount_plan",
        "input_mode": "face_amount_plan",
        "selection_source": "terms",
        "selection_label": "基本保額與保險型別",
        "selection_guidance": (
            "請輸入保單目前基本保額並選擇 A 型或 B 型；"
            "身故與全殘廢金另需填入給付評價時點的保單帳戶價值，"
            "九五祝壽金則使用滿期時保單帳戶價值。"
        ),
        "face_amount_label": "基本保額",
        "plan_options": [
            {"value": "A型", "label": "A型"},
            {"value": "B型", "label": "B型"},
        ],
        "version_characteristics": {
            "product_family": (
                "global-excellence-variable-universal-life"
            ),
            "company_group": "global_life",
            "source_product_id": product_id,
            "terms_revision": f"partial-change-{revision}",
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_text_extractor": version["source_text_extractor"],
            "semantic_phase": semantic_phase,
            "investment_linked_policy": True,
            "variable_universal_life_policy": True,
            "policy_type_options": ["A型", "B型"],
            "face_amount_label": "基本保額",
            "minimum_rate_formula_variant": (
                minimum_rate_formula_variant
            ),
            "minimum_benefit_formula_age": (
                minimum_benefit_formula_age
            ),
            "threshold_factor_schedule": threshold_factor_schedule,
            "insurance_amount_formula_by_type": (
                insurance_amount_formula_by_type
            ),
            "terms_formula_representation": semantic_phase,
            "death_benefit_formula": "insurance_amount_by_policy_type",
            "total_disability_benefit_formula": (
                "insurance_amount_by_policy_type"
            ),
            "maturity_age": 95,
            "maturity_benefit_formula": (
                "policy_account_value_at_age_95"
            ),
            "benefit_valuation_policy_account_value_required": True,
            "maturity_policy_account_value_required": True,
            "required_policy_inputs": required_policy_inputs,
            "disability_term": "全殘廢",
            "complete_disability_table_required": True,
            "policy_loan_offset_rule": (
                "deduct_outstanding_policy_loan_and_interest_"
                "after_gross_benefit"
            ),
            "non_participating_policy": True,
        },
        "coverage_entries": entries,
    }


