NANSHAN_LIFETIME_SINGLE_PREMIUM_VARIABLE_LIFE_VERSIONS = {
    product_id: {
        "revision": revision,
        "file_name": file_name,
        "page_count": page_count,
        "source_text_extractor": source_text_extractor,
        "source_document_sha256": source_document_sha256,
        "normalized_text_sha256": normalized_text_sha256,
    }
    for (
        product_id,
        revision,
        file_name,
        page_count,
        source_text_extractor,
        source_document_sha256,
        normalized_text_sha256,
    ) in NANSHAN_LIFETIME_SINGLE_PREMIUM_VARIABLE_LIFE_VERSION_ROWS
}


def is_nanshan_lifetime_single_premium_variable_life_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = NANSHAN_LIFETIME_SINGLE_PREMIUM_VARIABLE_LIFE_VERSIONS.get(
        product_id
    )
    return (
        version is not None
        and str(document.get("batch_id") or "") == "tii-life-035"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "") == version["file_name"]
        and str(document.get("source_document_sha256") or "")
        == version["source_document_sha256"]
    )


def nanshan_lifetime_single_premium_semantic_phase(revision: int) -> str:
    if revision == 0:
        return "legacy_fifth_valuation"
    if revision == 1:
        return "legacy_second_trading_day"
    if revision <= 9:
        return "legacy_funeral_200m"
    if revision <= 11:
        return "legacy_funeral_200m_loan"
    if revision == 12:
        return "legacy_funeral_threshold_excludes_pending"
    if revision == 13:
        return "legacy_funeral_threshold_includes_pending"
    if revision <= 18:
        return "legacy_no_funeral_loan"
    if revision <= 26:
        return "legacy_minor15_funeral_loan"
    if revision <= 29:
        return "account_value_minor15_disability"
    if revision <= 32:
        return "account_value_minor15_impairment_guardianship"
    if revision == 33:
        return "account_value_guardianship"
    return "account_value_guardianship_maturity_interest"


def nanshan_lifetime_single_premium_disability_term(revision: int) -> str:
    if revision == 0 or 13 <= revision <= 26:
        return "殘廢"
    if 1 <= revision <= 12:
        return "全殘"
    if revision <= 29:
        return "完全殘廢"
    return "完全失能"


def parse_nanshan_lifetime_single_premium_variable_life(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_nanshan_lifetime_single_premium_variable_life_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    version = NANSHAN_LIFETIME_SINGLE_PREMIUM_VARIABLE_LIFE_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        hashlib.sha256(text.encode("utf-8")).hexdigest()
        != version["normalized_text_sha256"]
    ):
        return None
    dense_text = compact_table_text(text).replace("「", "").replace("」", "")
    if any(
        compact_table_text(signal) not in dense_text
        for signal in (
            "伴我一生躉繳變額壽險",
            "躉繳",
        )
    ):
        return None
    if "一百歲" not in dense_text and "100歲" not in dense_text:
        return None

    revision = int(version["revision"])
    semantic_phase = nanshan_lifetime_single_premium_semantic_phase(revision)
    disability_term = nanshan_lifetime_single_premium_disability_term(
        revision
    )
    includes_pending_premium = revision <= 26
    includes_policy_loan_offset = revision >= 10
    includes_unpaid_charge_offset = revision >= 27
    includes_funeral_limit = (
        2 <= revision <= 13 or revision >= 19
    )
    includes_minor_age_rule = 19 <= revision <= 32
    includes_maturity_interest = revision == 34
    face_amount_label = (
        "基本保險金額" if revision <= 26 else "基本保額"
    )
    maturity_name = "滿期保險金" if revision <= 26 else "祝壽保險金"

    common_policy_state_keys = [
        "policy_effect_status_at_event",
        "benefit_valuation_policy_account_value",
        "policy_values_converted_to_twd",
        *(
            ["investment_allocation_status"]
            if includes_pending_premium
            else []
        ),
        *(
            ["policy_loan_and_interest_amount"]
            if includes_policy_loan_offset
            else []
        ),
        *(
            ["unpaid_policy_charge_amount"]
            if includes_unpaid_charge_offset
            else []
        ),
        *(
            ["insured_age_at_event"]
            if includes_minor_age_rule
            else []
        ),
    ]
    death_policy_state_keys = [
        *common_policy_state_keys,
        *(["death_benefit_status"] if includes_funeral_limit else []),
    ]
    maturity_policy_state_keys = [
        "policy_effect_status_at_event",
        *(
            ["policy_loan_and_interest_amount"]
            if includes_policy_loan_offset
            else []
        ),
        *(
            ["unpaid_policy_charge_amount"]
            if includes_unpaid_charge_offset
            else []
        ),
        *(
            ["maturity_interest_amount"]
            if includes_maturity_interest
            else []
        ),
    ]
    benefit_note = (
        f"依本版條款，以{face_amount_label}加給付評價日保單帳戶價值"
        + (
            "及已收取尚未投入之淨保險費"
            if includes_pending_premium
            else ""
        )
        + (
            "，再扣除保單借款及利息"
            if includes_policy_loan_offset
            else ""
        )
        + (
            "及尚未收取的保險成本、行政費用"
            if includes_unpaid_charge_offset
            else ""
        )
        + "；帳戶價值須依條款指定評價日由保險公司列示。"
    )

    death_name = (
        "身故保險金或喪葬費用保險金"
        if includes_funeral_limit
        else "身故保險金"
    )
    entries = [
        coverage_entry(
            "nanshan-lifetime-maturity",
            maturity_name,
            None,
            "policy_recorded_limit",
            (
                "被保險人於年齡達一百歲的保單週年日仍生存且契約有效時，"
                "依滿期評價日保單帳戶價值給付"
                + (
                    "，並加計保險公司依條款列示的利息"
                    if includes_maturity_interest
                    else ""
                )
                + "。"
            ),
            f"{maturity_name}條款",
            calculation_basis="maturity_policy_account_value",
            amount_role="payout",
            limit_scope="per_event",
            policy_state_keys=maturity_policy_state_keys,
            unit_key="maturity_policy_account_value",
        ),
        coverage_entry(
            "nanshan-lifetime-death",
            death_name,
            None,
            "policy_recorded_limit",
            benefit_note,
            f"{death_name}條款",
            calculation_basis=(
                "protected_amount_plus_policy_account_value"
            ),
            amount_role="payout",
            limit_scope="per_event",
            policy_state_keys=death_policy_state_keys,
            unit_key=(
                "protected_amount_plus_"
                "benefit_valuation_policy_account_value"
            ),
            minor_account_value_return_age=(
                15 if includes_minor_age_rule else None
            ),
        ),
        coverage_entry(
            "nanshan-lifetime-disability",
            f"{disability_term}保險金",
            None,
            "policy_recorded_limit",
            benefit_note,
            f"{disability_term}保險金條款",
            calculation_basis=(
                "protected_amount_plus_policy_account_value"
            ),
            amount_role="payout",
            limit_scope="per_event",
            policy_state_keys=common_policy_state_keys,
            unit_key=(
                "protected_amount_plus_"
                "benefit_valuation_policy_account_value"
            ),
            minor_account_value_return_age=(
                15 if includes_minor_age_rule else None
            ),
        ),
    ]

    required_policy_inputs = [
        face_amount_label,
        "給付時點契約狀態",
        "給付評價日保單帳戶價值",
        "保單價值金額已換算為新臺幣",
        *(
            ["保險費投入狀態"]
            if includes_pending_premium
            else []
        ),
        *(
            ["保單借款及應付利息"]
            if includes_policy_loan_offset
            else []
        ),
        *(
            ["尚未扣除的保險成本及行政費用"]
            if includes_unpaid_charge_offset
            else []
        ),
        *(
            ["事故時被保險人年齡"]
            if includes_minor_age_rule
            else []
        ),
        "滿期時保單帳戶價值",
        *(
            ["保險公司列示之祝壽金利息"]
            if includes_maturity_interest
            else []
        ),
    ]
    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": face_amount_label,
        "selection_guidance": (
            f"請輸入保單目前{face_amount_label}，再依事故或滿期時點補上"
            "保險公司列示的帳戶價值與本版本要求的保單現況；"
            "系統只使用本版條款固定的保障公式。"
        ),
        "face_amount_label": face_amount_label,
        "version_characteristics": {
            "product_family": (
                "nanshan-lifetime-single-premium-variable-life"
            ),
            "company_group": "nanshan_life",
            "source_product_id": product_id,
            "terms_revision": f"partial-change-{revision}",
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_quality": "machine_readable_exact_hash",
            "source_text_extractor": version["source_text_extractor"],
            "semantic_phase": semantic_phase,
            "investment_linked_policy": True,
            "variable_life_policy": True,
            "single_premium_policy": True,
            "face_amount_label": face_amount_label,
            "death_benefit_formula": (
                "protected_amount_plus_benefit_valuation_"
                "policy_account_value"
            ),
            "disability_benefit_formula": (
                "protected_amount_plus_benefit_valuation_"
                "policy_account_value"
            ),
            "maturity_age": 100,
            "maturity_benefit_name": maturity_name,
            "maturity_benefit_formula": (
                "maturity_policy_account_value"
                + (
                    "_plus_insurer_quoted_interest"
                    if includes_maturity_interest
                    else ""
                )
            ),
            "benefit_valuation_policy_account_value_required": True,
            "maturity_policy_account_value_required": True,
            "unallocated_net_premium_included": (
                includes_pending_premium
            ),
            "unallocated_net_premium_conditional_input": (
                "unallocated_net_premium_amount"
                if includes_pending_premium
                else "not_applicable"
            ),
            "minimum_face_amount_threshold_pending_premium_rule": (
                "exclude_unallocated_net_premium"
                if revision == 12
                else "include_unallocated_net_premium"
                if revision == 13
                else "not_applicable"
            ),
            "policy_loan_offset_rule": (
                "deduct_outstanding_policy_loan_and_interest"
                if includes_policy_loan_offset
                else "not_stated_in_this_version"
            ),
            "unpaid_policy_charge_offset_rule": (
                "deduct_unpaid_insurance_cost_and_admin_fee"
                if includes_unpaid_charge_offset
                else "not_stated_in_this_version"
            ),
            "funeral_limit_applies": includes_funeral_limit,
            "funeral_benefit_excludes_account_value": (
                includes_funeral_limit
            ),
            "minor_death_before_age_15_account_value_rule": (
                includes_minor_age_rule
            ),
            "minor_disability_before_age_15_account_value_rule": (
                includes_minor_age_rule
            ),
            "maturity_interest_applies": includes_maturity_interest,
            "required_policy_inputs": required_policy_inputs,
            "conditional_policy_inputs": {
                "investment_allocation_status=awaiting_allocation": (
                    ["unallocated_net_premium_amount"]
                    if includes_pending_premium
                    else []
                ),
                "death_benefit_status=funeral_limited": (
                    ["remaining_funeral_benefit_limit"]
                    if includes_funeral_limit
                    else []
                ),
            },
            "disability_term": disability_term,
            "complete_disability_or_impairment_table_required": True,
            "non_participating_policy": True,
        },
        "coverage_entries": entries,
    }


