def is_kgi_china_legacy_declared_rate_annuity_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    characteristics = (
        KGI_CHINA_LEGACY_DECLARED_RATE_ANNUITY_CHARACTERISTICS.get(
            product_id
        )
    )
    return bool(
        characteristics
        and str(document.get("batch_id") or "") == "tii-life-028"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "")
        == characteristics["file_name"]
    )


def parse_kgi_china_legacy_declared_rate_annuity(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_kgi_china_legacy_declared_rate_annuity_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    characteristics = (
        KGI_CHINA_LEGACY_DECLARED_RATE_ANNUITY_CHARACTERISTICS[
            product_id
        ]
    )
    text = normalize_terms_text(str(document.get("text") or ""))
    required_signals = (
        characteristics["family_title"],
        "年金保單價值準備金",
        "未支領之年金餘額",
        "年金金額的計算",
        "調整係數",
        "年金生命表",
        "保證期間十年",
        "保證期間十五年",
        "保險單借款應扣除保險單借款及其應付利息後",
    )
    if any(signal not in text for signal in required_signals):
        return None
    if not re.search(
        r"調整係數.{0,80}1\s*\+\s*前一年金給付週年日當月宣告利率"
        r".{0,30}除以.{0,20}1\s*\+\s*預定利率",
        text,
    ):
        return None
    if not (
        ("保證期間十年" in text and "保證期間十五年" in text)
        and (
            "年金給付開始日後" in text
            or "年金給付開始日起" in text
        )
    ):
        return None

    max_payment_age = characteristics["maximum_payment_age"]
    if max_payment_age == 110 and not re.search(
        r"保險年齡到達\s*110\s*歲",
        text,
    ):
        return None
    if (
        max_payment_age is None
        and re.search(r"保險年齡到達\s*110\s*歲", text)
    ):
        return None
    if characteristics["start_after_tenth_anniversary"] and not re.search(
        r"第十保單週年日屆滿後",
        text,
    ):
        return None
    if (
        characteristics["accumulation_interest_method"]
        == "daily_simple_declared_plus_bonus"
        and "以單利法計算" not in text
    ):
        return None

    plan_options = []
    for guarantee_years in (10, 15):
        benefit_group_id = (
            f"annuity-settlement-guarantee-{guarantee_years}"
        )
        common_conditions = [
            f"保證期間為 {guarantee_years} 年，領取頻率為年領。",
            "實際適用版本以保單首頁的商品名稱、銷售日期與保證期間為準。",
        ]
        entries = [
            coverage_entry(
                "pre-annuity-death-reserve-return",
                "年金給付開始前身故返還金額",
                None,
                "policy_recorded_limit",
                (
                    "被保險人在年金給付開始前身故時，以事故時"
                    "年金保單價值準備金扣除保單借款及應付利息。"
                ),
                "第8條、第9條及身故返還條款",
                calculation_basis=(
                    "reserve_minus_policy_loan_and_interest"
                ),
                amount_role="payout",
                limit_scope="per_policy",
                aggregation_rule="choose_one",
                benefit_group_id=benefit_group_id,
                event_key="pre-annuity-death",
                event_label="年金給付開始前身故",
                unit_key="policy_reserve_value",
                policy_state_keys=[
                    "policy_reserve_value",
                    "policy_loan_and_interest_amount",
                ],
                result_kind="cash_payout",
                conditions=[
                    *common_conditions,
                    "返還後契約效力終止。",
                ],
            ),
            coverage_entry(
                "annual-annuity-payment",
                "目前年度年金給付",
                None,
                "policy_recorded_limit",
                (
                    "第一年度年金須由保險公司依準備金、預定利率、"
                    "年金生命表、開始年齡及保證期間換算；第二年度起"
                    "依前一年度年金與宣告利率調整。請填最近通知列示金額。"
                ),
                "第8條、第9條",
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="annual",
                aggregation_rule="choose_one",
                benefit_group_id=benefit_group_id,
                event_key="annual-annuity",
                event_label="被保險人生存時年金",
                unit_key="annuity_payment_amount",
                policy_state_keys=["annuity_payment_amount"],
                result_kind="cash_payout",
                amount_stage="insurer_quoted_amount",
                conditions=[
                    *common_conditions,
                    (
                        "第二年度起年金 = 前一年度年金 × "
                        "(1 + 前一年金週年日當月宣告利率) ÷ "
                        "(1 + 年金開始時預定利率)。"
                    ),
                    "條款未提供生命表數值與完整年金因子，第一年度不可由一般使用者自行重建。",
                    *(
                        [
                            "被保險人生存給付最晚至保險年齡到達 110 歲。"
                        ]
                        if max_payment_age == 110
                        else []
                    ),
                ],
            ),
            coverage_entry(
                "low-annuity-lump-sum-reserve-payment",
                "低額年金改一次給付準備金",
                None,
                "policy_recorded_limit",
                (
                    "年金給付開始時計算的年領金額低於 10,000 元時，"
                    "改將扣除借款及利息後的年金保單價值準備金一次給付。"
                ),
                "第9條",
                calculation_basis=(
                    "reserve_minus_policy_loan_and_interest"
                ),
                amount_role="payout",
                limit_scope="per_policy",
                aggregation_rule="choose_one",
                benefit_group_id=benefit_group_id,
                event_key="low-annuity-lump-sum",
                event_label="年領金額低於 10,000 元",
                unit_key="policy_reserve_value",
                policy_state_keys=[
                    "policy_reserve_value",
                    "policy_loan_and_interest_amount",
                ],
                result_kind="cash_payout",
                conditions=[
                    *common_conditions,
                    "僅在保險公司於年金開始時計算的年領金額低於 10,000 元時適用。",
                    "一次給付後契約效力終止。",
                ],
            ),
            coverage_entry(
                "unpaid-guaranteed-annuity-balance",
                "保證期間未支領年金餘額",
                None,
                "policy_recorded_limit",
                (
                    "保證期間內身故時，原則上按年繼續給付至保證"
                    "期間屆滿；申請提前給付時依預定利率貼現。"
                ),
                "第2條、第8條、第10條",
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="per_policy",
                aggregation_rule="choose_one",
                benefit_group_id=benefit_group_id,
                event_key="death-during-guarantee-period",
                event_label="保證期間內身故",
                unit_key="unpaid_annuity_balance",
                policy_state_keys=["unpaid_annuity_balance"],
                result_kind="cash_payout",
                amount_stage="insurer_quoted_amount",
                conditions=[
                    *common_conditions,
                    "預設依原約定按年給付至保證期間屆滿。",
                    "提前一次領取須由保險公司依剩餘期數、預定利率及給付時點正式試算。",
                ],
            ),
            coverage_entry(
                "excess-annuity-reserve-return",
                "超額年金準備金返還",
                None,
                "policy_recorded_limit",
                (
                    "年金給付開始日的準備金若超過年領年金"
                    " 1,200,000 元所需金額，超出部分返還要保人。"
                ),
                "第9條",
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="per_policy",
                aggregation_rule="separate",
                unit_key="excess_annuity_reserve_return_amount",
                policy_state_keys=[
                    "excess_annuity_reserve_return_amount"
                ],
                result_kind="cash_payout",
                amount_stage="insurer_quoted_amount",
                conditions=[
                    "是否超額及返還金額取決於年金生命表與保險公司使用的年金因子。",
                    "若保險公司確認沒有超額返還，請輸入 0。",
                ],
            ),
        ]
        plan_options.append(
            {
                "value": f"guarantee-{guarantee_years}",
                "label": f"保證期間 {guarantee_years} 年｜年領",
                "coverage_entries": entries,
            }
        )

    version_characteristics: dict[str, Any] = {
        "product_family": (
            "kgi-china-legacy-declared-rate-traditional-annuity"
        ),
        "subfamily": characteristics["family"],
        "company_group": "kgi_china_life",
        "currency_basis": "twd",
        "traditional_annuity_policy": True,
        "declared_rate_annuity": True,
        "payment_frequency_options": ["annual"],
        "guarantee_period_options_years": [10, 15],
        "minimum_accumulation_years": 10,
        "maximum_annuity_start_age": 80,
        "maximum_annuity_payment_age": max_payment_age,
        "premium_mode": characteristics["premium_mode"],
        "annuity_amount_formula": (
            "first_year_insurer_annuity_factor_then_prior_amount_times_"
            "declared_rate_ratio"
        ),
        "pre_annuity_death_formula": (
            "policy_reserve_value_minus_policy_loan_and_interest"
        ),
        "annual_annuity_minimum_amount": 10_000,
        "annual_annuity_maximum_amount": 1_200_000,
        "accumulation_interest_method": characteristics[
            "accumulation_interest_method"
        ],
        "start_after_tenth_anniversary": characteristics[
            "start_after_tenth_anniversary"
        ],
        "required_policy_inputs": [
            "plan",
            "policy_reserve_value",
            "policy_loan_and_interest_amount",
            "annuity_payment_amount",
            "unpaid_annuity_balance",
            "excess_annuity_reserve_return_amount",
        ],
        "insurer_quoted_policy_inputs": [
            "annuity_payment_amount",
            "unpaid_annuity_balance",
            "excess_annuity_reserve_return_amount",
        ],
    }
    if characteristics["family"] == "yu-ling-long":
        version_characteristics.update(
            {
                "single_premium_policy": True,
                "initial_expense_rate_percent": 1.25,
                "bonus_interest_rate_schedule_percent": {
                    "year_3": 0.1,
                    "year_4": 0.1,
                    "year_5": 0.2,
                    "year_6": 0.2,
                    "year_7": 0.4,
                    "year_8": 0.4,
                    "year_9_and_after": 0.8,
                },
            }
        )

    return {
        "selection_type": "plan",
        "input_mode": "plan",
        "selection_source": "terms",
        "selection_label": "保證期間",
        "selection_guidance": (
            "請依保單首頁選擇 10 年或 15 年保證期間；再填最近"
            "保單通知或保險公司試算列示的準備金、借款、目前年度"
            "年金與未支領餘額。"
        ),
        "version_characteristics": version_characteristics,
        "plan_options": plan_options,
    }


