def is_kgi_china_songying_immediate_annuity_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-028"
        and product_id in KGI_CHINA_SONGYING_IMMEDIATE_ANNUITY_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "")
        == KGI_CHINA_SONGYING_IMMEDIATE_ANNUITY_FILES.get(product_id)
    )


def parse_kgi_china_songying_immediate_annuity_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_kgi_china_songying_immediate_annuity_strict_source(document):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    required_signals = (
        "松盈即期年金保險",
        "年金保險投保金額",
        "換算係數表",
        "平準型",
        "增額型",
        "未支領之年金餘額",
        "給付至 100 歲",
    )
    if any(signal not in text for signal in required_signals):
        return None
    if not re.search(
        r"年金保險投保金額.{0,40}乘以附表一中所列之換算係數",
        text,
    ):
        return None
    coefficient_match = re.search(
        r"換算係數表\s*年領\s*半年領\s*季領\s*月領\s*換算係數\s*"
        r"([0-9.]+)%\s*([0-9.]+)%\s*([0-9.]+)%\s*([0-9.]+)%",
        text,
    )
    if not coefficient_match:
        return None
    coefficients = [float(value) for value in coefficient_match.groups()]
    if coefficients != [100.0, 49.5562, 24.6686, 8.1987]:
        return None
    if not re.search(
        r"保證期間分為下列三類型.{0,120}甲型\s*[：:]\s*十年"
        r".{0,40}乙型\s*[：:]\s*十五年.{0,40}丙型\s*[：:]\s*二十年",
        text,
    ):
        return None
    if not re.search(
        r"保證期間內.{0,80}第一年依.{0,20}年金金額.{0,40}"
        r"以後每年.{0,50}(?:０．０３|0\.03|百分之三|3%)\s*單利增值",
        text,
    ):
        return None
    if not re.search(
        r"保證期間滿後.{0,80}年金金額.{0,30}(?:０．０３|0\.03|百分之三|3%)"
        r".{0,30}保證期間",
        text,
    ):
        return None

    frequencies = (
        ("annual", "年領", coefficients[0]),
        ("semiannual", "半年領", coefficients[1]),
        ("quarterly", "季領", coefficients[2]),
        ("monthly", "月領", coefficients[3]),
    )
    guarantee_options = (
        ("A", "甲型", 10),
        ("B", "乙型", 15),
        ("C", "丙型", 20),
    )
    patterns = (
        ("level", "平準型"),
        ("increasing", "增額型"),
    )
    plan_options = []
    for pattern, pattern_label in patterns:
        for frequency, frequency_label, frequency_rate in frequencies:
            for guarantee_code, guarantee_label, guarantee_years in guarantee_options:
                entry = coverage_entry(
                    "annuity-payment",
                    f"{frequency_label}年金給付",
                    None,
                    "face_amount",
                    (
                        "被保險人於契約有效期間內，在約定年金給付日仍生存時，"
                        "依年金保險投保金額、領取頻率與給付型態計算每期年金。"
                    ),
                    "第二條名詞定義、第五條、第八條及附表一",
                    calculation_basis="annuity_face_amount_schedule",
                    amount_role="payout",
                    limit_scope="per_policy",
                    aggregation_rule="separate",
                    rate_percent=frequency_rate,
                    unit_key="annuity_payment",
                    policy_state_keys=(
                        ["annuity_payment_year"] if pattern == "increasing" else None
                    ),
                    annuity_payment_pattern=pattern,
                    annuity_growth_rate_percent=(
                        3 if pattern == "increasing" else None
                    ),
                    annuity_guarantee_years=guarantee_years,
                    conditions=[
                        f"保證期間為{guarantee_label} {guarantee_years} 年。",
                        (
                            "平準型每期依年金投保金額乘以領取頻率換算係數給付。"
                            if pattern == "level"
                            else (
                                "增額型第一年依基本年金金額給付，保證期間內以後每年按基本年金金額"
                                "加計 3% 單利；保證期間屆滿後固定為基本年金金額加計"
                                f" 3% × {guarantee_years}。"
                            )
                        ),
                        "被保險人須於約定年金給付日仍生存且契約有效。",
                    ],
                )
                unpaid_balance = coverage_entry(
                    "unpaid-annuity-balance",
                    "保證期間未支領年金餘額",
                    None,
                    "policy_recorded_limit",
                    (
                        "被保險人於保證期間內身故且仍有未支領年金餘額時，"
                        "依保險公司或保單明細列示的餘額給付。"
                    ),
                    "第五條至第九條",
                    calculation_basis="policy_state_amount",
                    amount_role="payout",
                    limit_scope="per_policy",
                    aggregation_rule="separate",
                    unit_key="unpaid_annuity_balance",
                    policy_state_keys=["unpaid_annuity_balance"],
                    conditions=[
                        f"適用{guarantee_label} {guarantee_years} 年保證期間。",
                        "受益人申請提前領取全部未支領年金餘額時，條款年貼現率為 2%。",
                    ],
                )
                value = (
                    f"{pattern}-{frequency}-guarantee-{guarantee_years}"
                )
                plan_options.append(
                    {
                        "value": value,
                        "label": (
                            f"{pattern_label}｜{frequency_label}｜"
                            f"{guarantee_label}保證 {guarantee_years} 年"
                        ),
                        "coverage_entries": [entry, unpaid_balance],
                    }
                )

    return {
        "selection_type": "face_amount_plan",
        "input_mode": "face_amount_plan",
        "selection_source": "terms",
        "selection_label": "年金投保金額與給付方式",
        "face_amount_label": "年金保險投保金額",
        "selection_guidance": (
            "請輸入保單首頁的年金保險投保金額，並選擇平準／增額型、"
            "領取頻率及甲／乙／丙型保證期間；增額型另填目前年金給付年度。"
        ),
        "version_characteristics": {
            "product_family": "kgi-china-songying-immediate-annuity-face-amount",
            "company_group": "kgi_china_life",
            "currency_basis": "twd",
            "traditional_annuity_policy": True,
            "immediate_annuity_policy": True,
            "participating_policy": True,
            "policy_dividend_guaranteed": False,
            "annuity_face_amount_formula": (
                "annuity_face_amount_times_payment_frequency_coefficient"
            ),
            "payment_frequency_rates_percent": {
                frequency: rate
                for frequency, _label, rate in frequencies
            },
            "payment_frequency_options": [
                frequency for frequency, _label, _rate in frequencies
            ],
            "payment_pattern_options": [
                pattern for pattern, _label in patterns
            ],
            "guarantee_period_options_years": [
                years for _code, _label, years in guarantee_options
            ],
            "increasing_annuity_simple_growth_rate_percent": 3,
            "unpaid_annuity_balance_discount_rate_percent": 2,
            "max_annuity_payment_age": 100,
            "required_policy_inputs": [
                "basic_face_amount",
                "plan",
                "annuity_payment_year",
                "unpaid_annuity_balance",
            ],
        },
        "plan_options": plan_options,
    }


