def is_kgi_china_songying_principal_protected_annuity_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    return (
        str(document.get("batch_id") or "") == "tii-life-028"
        and product_id
        in KGI_CHINA_SONGYING_PRINCIPAL_PROTECTED_ANNUITY_PRODUCT_IDS
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "")
        == KGI_CHINA_SONGYING_PRINCIPAL_PROTECTED_ANNUITY_FILES.get(
            product_id
        )
    )


def parse_kgi_china_songying_principal_protected_annuity(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_kgi_china_songying_principal_protected_annuity_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    characteristics = (
        KGI_CHINA_SONGYING_PRINCIPAL_PROTECTED_ANNUITY_CHARACTERISTICS[
            product_id
        ]
    )
    text = normalize_terms_text(str(document.get("text") or ""))
    required_signals = (
        "松盈保本即期年金保險",
        "年金金額",
        "未支領之年金餘額",
        "換算係數表",
        "保險年齡屆滿一百歲",
        "保險單紅利",
    )
    if any(signal not in text for signal in required_signals):
        return None

    coefficient_match = re.search(
        r"換算係數表.{0,220}?100\s*%\s*([0-9.]+)\s*%"
        r"\s*([0-9.]+)\s*%\s*([0-9.]+)\s*%",
        text,
    )
    if not coefficient_match:
        return None
    rates = [100.0, *[float(value) for value in coefficient_match.groups()]]
    if rates != characteristics["rates"]:
        return None

    death_settlement_mode = characteristics["death_settlement_mode"]
    if death_settlement_mode == "lump_sum_unpaid_balance":
        if (
            "躉繳總保費扣除「已給付之年金總金額」之差額"
            not in text
            or "一次給付與被保險人身故受益人" not in text
        ):
            return None
        death_conditions = [
            "被保險人於年金給付開始後身故時，未支領年金餘額一次給付身故受益人。",
            "未支領年金餘額不得為負值。",
        ]
        unpaid_balance_definition = (
            "max(single_premium_amount - "
            "annuity_paid_total_amount, 0)"
        )
    else:
        if (
            "年金保證金額" not in text
            or "其金額為躉繳保險費" not in text
            or "依約定繼續給付年金予身故受益人" not in text
            or not re.search(
                r"未支領之各年度年金按預定利率"
                r".{0,30}?1\.75\s*%.{0,20}?折現",
                text,
            )
        ):
            return None
        death_conditions = [
            "被保險人身故後，按原約定頻率繼續給付年金予身故受益人，直到未支領餘額領完。",
            "身故受益人於領完前身故時，未支領之各年度年金按預定利率 1.75% 折現後一次給付其法定繼承人。",
        ]
        unpaid_balance_definition = (
            "max(annuity_guarantee_amount_equal_to_single_premium "
            "- annuity_paid_total_amount, 0)"
        )

    frequencies = (
        ("annual", "年領", rates[0]),
        ("semiannual", "半年領", rates[1]),
        ("quarterly", "季領", rates[2]),
        ("monthly", "月領", rates[3]),
    )
    plan_options = []
    for frequency, frequency_label, frequency_rate in frequencies:
        annuity_entry = coverage_entry(
            "annuity-payment",
            f"{frequency_label}年金給付",
            None,
            "face_amount",
            (
                "以保單記載的年領年金金額乘以本版本附表一的"
                "領取頻率換算係數，計算每期年金。"
            ),
            "第2條、第8條、附表一",
            calculation_basis="annuity_face_amount_schedule",
            amount_role="payout",
            limit_scope="per_policy",
            rate_percent=frequency_rate,
            unit_key="annuity_payment",
            annuity_payment_pattern="level",
            conditions=[
                "被保險人於每個約定年金給付日仍生存。",
                "年金給付至被保險人身故或保險年齡屆滿一百歲。",
                "條款未載明元以下處理；每期實際金額以保單或保險公司列示為準。",
            ],
        )
        is_lump_sum = (
            death_settlement_mode == "lump_sum_unpaid_balance"
        )
        unpaid_balance_entry = coverage_entry(
            (
                "unpaid-annuity-balance"
                if is_lump_sum
                else "continuing-annuity-balance"
            ),
            (
                "身故一次給付未支領年金餘額"
                if is_lump_sum
                else "身故後續領年金餘額（總額）"
            ),
            None,
            "policy_recorded_limit",
            (
                "以躉繳保險費扣除截至計算日實際已領取的"
                "年金總額。"
            ),
            "第2條、第6條、第8條",
            calculation_basis="single_premium_minus_paid_annuity_total",
            amount_role=("payout" if is_lump_sum else "reference"),
            limit_scope="per_policy",
            unit_key="unpaid_annuity_balance",
            policy_state_keys=[
                "single_premium_amount",
                "annuity_paid_total_amount",
            ],
            result_kind=(
                "cash_payout" if is_lump_sum else "payment_method"
            ),
            amount_stage="gross_contract_benefit",
            conditions=death_conditions,
        )
        dividend_entry = coverage_entry(
            "policy-dividend",
            "保險單紅利（非保證）",
            None,
            "policy_recorded_limit",
            (
                "紅利不是保證給付；請以保險公司年度通知或"
                "正式試算所列金額為準。"
            ),
            "第10條、附件",
            calculation_basis="policy_state_amount",
            amount_role="payout",
            limit_scope="per_policy",
            unit_key="policy_dividend_amount",
            policy_state_keys=["policy_dividend_amount"],
            result_kind="cash_payout",
            amount_stage="insurer_quoted_amount",
            conditions=[
                "紅利依條款公式及當年度利率條件計算，可能為零。",
                "本公司不保證保險單紅利金額。",
            ],
        )
        option_entries = [
            annuity_entry,
            unpaid_balance_entry,
            dividend_entry,
        ]
        if not is_lump_sum:
            option_entries.append(
                coverage_entry(
                    "successor-discounted-annuity-lump-sum",
                    "身故受益人後續身故之折現一次給付",
                    None,
                    "policy_recorded_limit",
                    (
                        "條款未提供足以由一般使用者自行重建的完整"
                        "折現期數與尾期處理；請填保險公司正式列示金額。"
                    ),
                    "第8條",
                    calculation_basis="policy_state_amount",
                    amount_role="payout",
                    limit_scope="per_policy",
                    unit_key="successor_discounted_annuity_amount",
                    policy_state_keys=[
                        "successor_discounted_annuity_amount",
                    ],
                    result_kind="cash_payout",
                    amount_stage="insurer_quoted_amount",
                    conditions=[
                        "僅於身故受益人在未支領年金餘額領完前身故時適用。",
                        "未支領各年度年金依本版本預定利率 1.75% 折現後一次給付其法定繼承人。",
                    ],
                )
            )
        plan_options.append(
            {
                "value": frequency,
                "label": (
                    f"{frequency_label}（換算係數 "
                    f"{frequency_rate:g}%）"
                ),
                "coverage_entries": option_entries,
            }
        )

    return {
        "selection_type": "face_amount_plan",
        "input_mode": "face_amount_plan",
        "selection_source": "terms",
        "selection_label": "年領年金金額與領取頻率",
        "face_amount_label": "年領年金金額",
        "selection_guidance": (
            "請填保單記載的年領年金金額，並選擇年領、半年領、"
            "季領或月領；系統會依這一版本的附表係數換算每期金額。"
        ),
        "version_characteristics": {
            "product_family": (
                "kgi-china-songying-principal-protected-immediate-annuity"
            ),
            "company_group": "kgi_china_life",
            "currency_basis": "twd",
            "traditional_annuity_policy": True,
            "immediate_annuity_policy": True,
            "principal_protected_annuity": True,
            "single_premium_policy": True,
            "participating_policy": True,
            "policy_dividend_guaranteed": False,
            "annuity_payment_end_age": 100,
            "annuity_face_amount_formula": (
                "annual_annuity_amount_times_payment_frequency_coefficient"
            ),
            "annuity_guarantee_amount_formula": (
                "single_premium_amount"
            ),
            "unpaid_annuity_balance_formula": (
                unpaid_balance_definition
            ),
            "death_settlement_mode": death_settlement_mode,
            "scheduled_interest_rate_percent": characteristics[
                "scheduled_interest_rate_percent"
            ],
            "dividend_reference_bank_count": characteristics[
                "dividend_reference_bank_count"
            ],
            "secondary_beneficiary_discount_rate_percent": (
                1.75
                if death_settlement_mode
                == "continue_annuity_until_balance_exhausted"
                else None
            ),
            "payment_frequency_rates_percent": {
                frequency: rate
                for frequency, _label, rate in frequencies
            },
            "payment_frequency_options": [
                frequency
                for frequency, _label, _rate in frequencies
            ],
            "required_policy_inputs": [
                "face_amount",
                "plan",
                "single_premium_amount",
                "annuity_paid_total_amount",
            ],
            "optional_policy_inputs": [
                "policy_dividend_amount",
                *(
                    ["successor_discounted_annuity_amount"]
                    if not is_lump_sum
                    else []
                ),
            ],
        },
        "plan_options": plan_options,
    }


