def taiwan_participating_return_terms_revision(text: str) -> str:
    if "114 年 12 月 17 日金管保壽字第 11404321761 號令修正" in text:
        return "roc-115-01-01-regulatory-revision"
    filing_date, _ = taiwan_participating_filing_info(text)
    return filing_date


