def is_nanshan_specific_illness_whole_life_health_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = (
        NANSHAN_SPECIFIC_ILLNESS_WHOLE_LIFE_HEALTH_RIDER_VERSIONS.get(
            product_id
        )
    )
    return (
        version is not None
        and document.get("batch_id") == "tii-life-032"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "") == version["file_name"]
        and str(document.get("source_document_sha256") or "")
        == version["source_document_sha256"]
    )


def nanshan_specific_illness_event_exclusions(
    *eligible_values: str,
) -> list[str]:
    return [
        value
        for value in NANSHAN_SPECIFIC_ILLNESS_EVENT_VALUES
        if value not in eligible_values
    ]


