def parse_nanshan_new_whole_life_medical_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_nanshan_new_whole_life_medical_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = NANSHAN_NEW_WHOLE_LIFE_MEDICAL_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if (
        sha256_bytes(text.encode("utf-8"))
        != version["source_text_sha256"]
    ):
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "南山人壽新終身醫療保險",
            "單位日額",
            "健康增值保險金",
            "三千倍",
        )
    ):
        return None
    revision = int(version["revision"])
    phase_checks = (
        ("緊急醫療運送保險金" in dense_text, revision <= 6),
        ("急診保險金" in dense_text, revision <= 6),
        ("癌症疾病保險金" in dense_text, revision <= 8),
        ("特定重大疾病保險金" in dense_text, revision <= 8),
        ("輕度癌症保險金" in dense_text, revision >= 9),
        ("重度重大疾病保險金" in dense_text, revision >= 9),
        (
            "一至六級失能豁免保險費" in dense_text,
            revision >= 11,
        ),
        (
            "一至六級殘廢豁免保險費" in dense_text,
            revision <= 10,
        ),
    )
    if any(actual is not expected for actual, expected in phase_checks):
        return None
    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": "單位日額",
        "face_amount_label": "單位日額",
        "selection_guidance": (
            "請輸入保單首頁或最近批註所載的單位日額。"
            "查看特定事故時，再填住院日數、特殊病房日數、門診或手術次數及相應保單狀態。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "nanshan-new-whole-life-medical"
            ),
            "family_fingerprint": (
                "c75b9f9e987af609dd5943ce"
            ),
            "company_group": "nanshan_life",
            "source_batch_id": "tii-life-032",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                nanshan_new_whole_life_medical_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "unit_daily_amount_required": True,
            "disease_waiting_days": 30,
            "cancer_waiting_days": 90,
            "same_hospitalization_max_days": 365,
            "same_hospital_readmission_days": 14,
            "hospital_daily_tiers": [
                {"min_day": 1, "max_day": 30, "multiplier": 1},
                {"min_day": 31, "max_day": 90, "multiplier": 2},
                {"min_day": 91, "max_day": 365, "multiplier": 3},
            ],
            "intensive_care_or_burn_multiplier": 2,
            "outpatient_rate_percent": 25,
            "outpatient_window_days_before_after": 14,
            "discharge_recuperation_rate_percent": 50,
            "inpatient_surgery_multiplier": 3,
            "same_site_surgery_annual_once": True,
            "emergency_transport_benefit_present": (
                revision <= 6
            ),
            "emergency_room_benefit_present": revision <= 6,
            "legacy_cancer_and_critical_definitions": (
                revision <= 8
            ),
            "severe_critical_definition": revision >= 9,
            "disability_term": (
                "失能" if revision >= 11 else "殘廢"
            ),
            "health_increment_rate_percents": [20, 40, 60, 80],
            "premium_waiver_available": True,
            "waiver_is_non_cash_effect": True,
            "maturity_age": 111,
            "terminal_benefit_paid_premium_rate_percent": 105,
            "lifetime_benefit_cap_multiplier": 3000,
            "no_cash_surrender_value": True,
            "post_expiry_continuing_hospitalization": True,
            "required_policy_inputs": ["face_amount"],
            "claim_event_inputs": [
                "hospitalization_days",
                "intensive_care_or_burn_unit_days",
                "outpatient_visit_count",
                "inpatient_surgery_count",
                "current_eligible_hospital_benefit_total_amount",
                "health_increment_rate_percent",
                "cumulative_medical_benefit_paid_amount",
                "remaining_premium_amount",
                "premium_payment_period_status",
                "unexpired_premium_refund_amount",
                "paid_premium_total",
                "death_benefit_status",
                "death_age_band_status",
                "remaining_funeral_benefit_limit",
            ],
            "amount_presentation": (
                "unit_daily_amount_with_claim_and_policy_state"
            ),
        },
        "coverage_entries": (
            nanshan_new_whole_life_medical_entries(
                revision=revision
            )
        ),
    }


