def is_farglory_yongkang_specific_illness_whole_life_health_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = (
        FARGLORY_YONGKANG_SPECIFIC_ILLNESS_WHOLE_LIFE_HEALTH_RIDER_VERSIONS.get(
            product_id
        )
    )
    return bool(
        version
        and document.get("batch_id") == "tii-life-080"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
        and str(document.get("source_document_sha256") or "")
        == version["source_document_sha256"]
    )


def farglory_yongkang_specific_illness_items(
    revision: int,
) -> list[str]:
    if revision <= 4:
        return FARGLORY_YONGKANG_SPECIFIC_ILLNESS_ITEMS_LEGACY
    if revision <= 6:
        return (
            FARGLORY_YONGKANG_SPECIFIC_ILLNESS_ITEMS_STANDARDIZED_DISABILITY
        )
    if revision == 7:
        return (
            FARGLORY_YONGKANG_SPECIFIC_ILLNESS_ITEMS_STANDARDIZED_IMPAIRMENT
        )
    return FARGLORY_YONGKANG_SPECIFIC_ILLNESS_ITEMS_CURRENT


def farglory_yongkang_specific_illness_semantic_phase(
    revision: int,
) -> str:
    if revision <= 4:
        return "legacy_eighteen_illness_definitions"
    if revision <= 6:
        return "standardized_core_residual_disability_language"
    if revision == 7:
        return "standardized_core_impairment_language"
    if revision == 8:
        return "fully_standardized_eighteen_illness_definitions"
    if revision <= 11:
        return "medical_review_and_multichannel_notice"
    if revision == 12:
        return "agreed_method_contract_changes"
    return "policy_period_start_and_agreed_method"


def farglory_yongkang_event_exclusions(
    *eligible_values: str,
) -> list[str]:
    return [
        value
        for value in FARGLORY_YONGKANG_EVENT_VALUES
        if value not in eligible_values
    ]


