def parse_farglory_yongkang_specific_illness_whole_life_health_rider_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_farglory_yongkang_specific_illness_whole_life_health_rider_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    version = (
        FARGLORY_YONGKANG_SPECIFIC_ILLNESS_WHOLE_LIFE_HEALTH_RIDER_VERSIONS[
            product_id
        ]
    )
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    dense_text = compact_table_text(text)
    source_text_sha256 = sha256_bytes(text.encode("utf-8"))
    if source_text_sha256 != version["source_text_sha256"]:
        return None

    revision = int(version["revision"])
    illness_items = farglory_yongkang_specific_illness_items(revision)
    required_signals = [
        "遠雄人壽永康特定傷病終身健康保險附約",
        "特定傷病保險金的給付",
        "第一次罹患「特定傷病」時",
        "按保險金額給付",
        "按日數比例計算當期已繳付之未滿期保險費",
        "返還予要保人",
        "本附約效力即行終止",
        *illness_items,
    ]
    if any(
        compact_table_text(signal) not in dense_text
        for signal in required_signals
    ):
        return None

    expected_phase_signals = (
        ("徵詢其他醫師", revision >= 9),
        ("電子郵件", revision >= 9),
        ("簡訊", revision >= 9),
        ("完全失能", revision >= 7),
        ("全殘廢", revision <= 6),
        ("等待期間為三十日", revision >= 8),
        ("但本附約另有約定保險期間始日者", revision >= 13),
    )
    if any(
        (compact_table_text(signal) in dense_text) is not expected
        for signal, expected in expected_phase_signals
    ):
        return None

    accident_exception_items = [
        illness_items[5],
        illness_items[6],
        illness_items[9],
    ]
    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": "保險金額",
        "face_amount_label": "保險金額",
        "selection_guidance": (
            "請輸入保單首頁、批註或最近契約變更通知所載的本附約保險金額，"
            "再依診斷日、事故原因與繳費期間選擇本次情境；繳費期間內另請填"
            "保險公司按日數比例列示的未到期保費。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "farglory-yongkang-specific-illness-"
                "whole-life-health-rider"
            ),
            "family_fingerprint": "b417f93847a588ff36487ef4",
            "company_group": "farglory_life",
            "source_batch_id": "tii-life-080",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                farglory_yongkang_specific_illness_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": source_text_sha256,
            "source_text_extractor": version["source_text_extractor"],
            "source_text_quality": (
                "machine_readable_exact_hash_pymupdf_recovery"
                if version["source_text_extractor"] == "pymupdf"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "insurance_amount_basis": "policy_face_amount",
            "benefit_formula": (
                "face_amount_plus_prorated_current_unexpired_premium"
            ),
            "specific_illness_definition_revision": (
                "legacy_eighteen"
                if revision <= 4
                else "standardized_core_residual_disability"
                if revision <= 6
                else "standardized_core_impairment"
                if revision == 7
                else "fully_standardized_eighteen"
            ),
            "specific_illness_item_count": 18,
            "specific_illness_items": illness_items,
            "specific_illness_waiting_days": 30,
            "waiting_period_start_rule": (
                "coverage_from_day_31_after_effective_or_from_reinstatement"
            ),
            "accident_waiting_exception_items": (
                accident_exception_items
            ),
            "maximum_claim_count": 1,
            "contract_terminates_after_benefit": True,
            "installment_benefit_available": False,
            "premium_waiver_available": False,
            "no_cash_surrender_value": True,
            "death_benefit_available": False,
            "maturity_benefit_available": False,
            "unexpired_premium_refund_requires_policy_state": True,
            "unexpired_premium_proration_rounding_rule_available": False,
            "required_policy_inputs": [
                "farglory_yongkang_event_status",
            ],
            "claim_event_inputs": [
                "unexpired_premium_refund_amount",
            ],
            "amount_presentation": (
                "face_amount_plus_insurer_quoted_unexpired_premium"
            ),
        },
        "coverage_entries": (
            farglory_yongkang_specific_illness_entries()
        ),
    }


