def is_farglory_specific_illness_whole_life_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = FARGLORY_SPECIFIC_ILLNESS_WHOLE_LIFE_RIDER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and document.get("batch_id") == "tii-life-080"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
        and str(document.get("source_document_sha256") or "")
        == version["source_document_sha256"]
    )


def farglory_specific_illness_whole_life_items(
    revision: int,
) -> list[str]:
    if revision <= 12:
        return FARGLORY_SPECIFIC_ILLNESS_WHOLE_LIFE_RIDER_ITEMS_LEGACY
    return FARGLORY_SPECIFIC_ILLNESS_WHOLE_LIFE_RIDER_ITEMS_STANDARDIZED


def farglory_specific_illness_whole_life_semantic_phase(
    revision: int,
) -> str:
    if revision <= 6:
        return "legacy_nine_illness_old_funeral_limit"
    if revision <= 11:
        return "legacy_nine_illness_current_funeral_limit"
    if revision == 12:
        return "legacy_nine_illness_reinstatement_disclosure"
    return "standardized_nine_illness_reinstatement_disclosure"


def farglory_specific_illness_whole_life_event_exclusions(
    *eligible_values: str,
) -> list[str]:
    return [
        value
        for value in FARGLORY_SPECIFIC_ILLNESS_WHOLE_LIFE_EVENT_VALUES
        if value not in eligible_values
    ]


