def parse_farglory_specific_illness_whole_life_rider_face_amount(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_farglory_specific_illness_whole_life_rider_strict_source(
        document
    ):
        return None

    product_id = str(document.get("product_id") or "")
    version = FARGLORY_SPECIFIC_ILLNESS_WHOLE_LIFE_RIDER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    dense_text = compact_table_text(text)
    source_text_sha256 = sha256_bytes(text.encode("utf-8"))
    if source_text_sha256 != version["source_text_sha256"]:
        return None

    revision = int(version["revision"])
    illness_items = farglory_specific_illness_whole_life_items(revision)
    required_signals = [
        "特定傷病保險金的給付",
        "身故保險金或喪葬費用保險金的給付",
        "完全殘廢保險金的給付",
        "按保險金額給付",
        "另按日數比例退還當期已繳付未到期之保險費",
        "本附約效力終止",
        *illness_items,
    ]
    if revision > 0:
        required_signals.append("遠雄人壽特定傷病終身壽險附約")
    else:
        required_signals.append("216311R12G025-A.doc")
    if any(
        compact_table_text(signal) not in dense_text
        for signal in required_signals
    ):
        return None

    expected_phase_signals = (
        ("以未滿十四足歲", revision <= 6),
        ("精神障礙或其他心智缺陷", revision >= 7),
        ("遺產及贈與稅法第十七條", revision >= 7),
        ("書面或其他約定方式", revision >= 12),
        ("急性心肌梗塞（重度）", revision >= 13),
        ("腦中風後殘障（重度）", revision >= 13),
        ("末期腎病變", revision >= 13),
    )
    if any(
        (compact_table_text(signal) in dense_text) is not expected
        for signal, expected in expected_phase_signals
    ):
        return None

    accident_exception_items = [
        illness_items[5],
        illness_items[6],
        illness_items[8],
    ]
    return {
        "selection_type": "face_amount",
        "input_mode": "face_amount",
        "selection_source": "terms",
        "selection_label": "保險金額",
        "face_amount_label": "保險金額",
        "selection_guidance": (
            "請輸入本附約保單首頁、批註或最近契約變更通知所載保險金額，"
            "再選擇本次特定傷病、身故／喪葬或完全殘廢情境；繳費期間內"
            "另填保險公司列示的未到期保費退還額。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "farglory-specific-illness-whole-life-rider"
            ),
            "family_fingerprint": "f7ff8f40e73a41cd3d8b6685",
            "company_group": "farglory_life",
            "source_batch_id": "tii-life-080",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": (
                farglory_specific_illness_whole_life_semantic_phase(
                    revision
                )
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": source_text_sha256,
            "source_text_extractor": version["source_text_extractor"],
            "source_text_quality": (
                "machine_readable_exact_hash_pymupdf_recovery"
                if version["source_text_extractor"] == "pymupdf"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "insurance_amount_basis": "policy_face_amount",
            "benefit_formula": (
                "one_terminal_face_amount_benefit_plus_applicable_refunds"
            ),
            "specific_illness_definition_revision": (
                "legacy_nine"
                if revision <= 12
                else "standardized_nine"
            ),
            "specific_illness_item_count": 9,
            "specific_illness_items": illness_items,
            "specific_illness_waiting_days": 30,
            "waiting_period_start_rule": (
                "effective_day_31_with_reinstatement_disclosure"
                if revision >= 12
                else "effective_day_31"
            ),
            "accident_waiting_exception_items": (
                accident_exception_items
            ),
            "maximum_primary_benefit_count": 1,
            "primary_benefits_mutually_exclusive": True,
            "contract_terminates_after_primary_benefit": True,
            "death_benefit_available": True,
            "funeral_limit_available": True,
            "funeral_limit_rule_revision": (
                "under_age_14_or_legacy_mental_status"
                if revision <= 6
                else "current_mental_capacity_and_statutory_limit"
            ),
            "total_disability_benefit_available": True,
            "total_disability_term": "完全殘廢",
            "premium_waiver_available": False,
            "maturity_benefit_available": False,
            "cash_surrender_value_available": True,
            "funeral_excess_premium_refund_requires_policy_state": True,
            "unexpired_premium_refund_requires_policy_state": True,
            "unexpired_premium_proration_rounding_rule_available": False,
            "required_policy_inputs": [
                "farglory_specific_illness_life_event_status",
            ],
            "claim_event_inputs": [
                "death_benefit_status",
                "remaining_funeral_benefit_limit",
                "funeral_excess_premium_refund_amount",
                "unexpired_premium_refund_amount",
            ],
            "amount_presentation": (
                "mutually_exclusive_face_amount_benefit_plus_applicable_refunds"
            ),
        },
        "coverage_entries": (
            farglory_specific_illness_whole_life_entries()
        ),
    }


