def is_allianz_new_peace_of_mind_premium_waiver_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = ALLIANZ_NEW_PEACE_OF_MIND_PREMIUM_WAIVER_VERSIONS.get(
        product_id
    )
    return bool(
        version
        and document.get("batch_id") == "tii-life-092"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def allianz_new_peace_of_mind_premium_waiver_entries(
    *, disability_term: str
) -> list[dict[str, Any]]:
    trigger_description = (
        f"身故、第一級至第六級{disability_term}、重大疾病或生命末期之一"
    )
    return [
        coverage_entry(
            "future-premium-waiver",
            "未來保險費豁免",
            None,
            "policy_premium",
            (
                f"被保險人符合{trigger_description}時，自該情形確定日起，"
                "豁免主契約與附約分期繳付的保險費豁免金額至保單面頁"
                "記載的約定豁免期滿日；輸入剩餘應繳保費可估算非現金保障效果。"
            ),
            "保單條款重大疾病、生命末期、保險費豁免金額定義及第十條豁免保險費",
            calculation_basis="waiver",
            amount_role="premium_waiver",
            limit_scope="per_policy",
            aggregation_rule="choose_one",
            unit_key="remaining_premium_amount",
            policy_state_keys=["remaining_premium_amount"],
            result_kind="non_cash_effect",
            amount_stage="non_cash_estimate",
            conditions=[
                trigger_description + "。",
                "疾病所致事故須符合三十日疾病等待期間；傷害所致事故不受疾病等待期間限制。",
                "豁免金額先繳付附約保險費，餘額再繳付主契約保險費。",
                "此項是未來保費豁免效果，不是現金保險金。",
            ],
        )
    ]


def parse_allianz_new_peace_of_mind_premium_waiver_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_allianz_new_peace_of_mind_premium_waiver_strict_source(
        document
    ):
        return None
    product_id = str(document.get("product_id") or "")
    version = ALLIANZ_NEW_PEACE_OF_MIND_PREMIUM_WAIVER_VERSIONS[
        product_id
    ]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    source_text_sha256 = sha256_bytes(text.encode("utf-8"))
    if source_text_sha256 != version["source_text_sha256"]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    revision = int(version["revision"])
    disability_term = "殘廢" if revision <= 9 else "失能"
    required_signals = (
        "安聯人壽新安心豁免保險費健康保險附約",
        f"第一級至第六級{disability_term}",
        "重大疾病",
        "生命末期",
        "保險費豁免金額",
        "約定豁免期滿日",
        "主契約及其附約分期繳付",
    )
    if any(signal not in dense_text for signal in required_signals):
        return None

    consent_signal = "非經被保險人同意,不得解約"
    severe_disease_signal = "急性心肌梗塞(重度)"
    if (
        (consent_signal in dense_text) is not (revision >= 4)
        or (severe_disease_signal in dense_text) is not (revision >= 9)
    ):
        return None
    semantic_phase = (
        "legacy_disability_definition"
        if revision <= 3
        else "legacy_disability_with_insured_consent"
        if revision <= 8
        else "severe_major_disease_with_legacy_disability"
        if revision == 9
        else "severe_major_disease_with_impairment_term"
    )
    waiver_event_triggers = [
        "death",
        (
            "disability_grade_1_to_6"
            if disability_term == "殘廢"
            else "impairment_grade_1_to_6"
        ),
        "critical_illness",
        "terminal_illness",
    ]
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "剩餘應繳保費",
        "selection_guidance": (
            "請依保單或保險公司資料輸入自事故確定日起至約定豁免期滿日"
            "尚應繳付的主契約與附約保費合計；結果代表非現金豁免效果。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": (
                "allianz-new-peace-of-mind-premium-waiver-health-rider"
            ),
            "family_fingerprint": "0b78b44efcf2e434e23825ed",
            "company_group": "allianz_life",
            "source_batch_id": "tii-life-092",
            "terms_revision": (
                "original"
                if revision == 0
                else f"partial_change_{revision}"
            ),
            "semantic_phase": semantic_phase,
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": source_text_sha256,
            "source_text_extractor": version[
                "source_text_extractor"
            ],
            "source_text_quality": (
                "verified_windows_ocr_exact_hash"
                if version["source_text_extractor"] == "windows_ocr"
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "ocr_evidence_path": (
                "work/tii-benefit-source-matrices/"
                "tii-life-092-allianz-new-peace-of-mind-premium-waiver-health-rider.json"
                if version["source_text_extractor"] == "windows_ocr"
                else None
            ),
            "currency_basis": "twd",
            "disease_waiting_days": 30,
            "disease_waiting_applies_to_disease_caused_events": True,
            "injury_events_not_subject_to_disease_waiting": True,
            "critical_illness_definition_source": (
                "exact_terms_revision"
            ),
            "critical_illness_definition_phase": (
                "legacy_seven_major_diseases"
                if revision <= 8
                else "standardized_severe_major_diseases"
            ),
            "waiver_event_triggers": waiver_event_triggers,
            "premium_waiver_disability_levels": "1-6",
            "disability_term": disability_term,
            "insured_consent_required_for_termination": (
                revision >= 4
            ),
            "premium_waiver_until": "agreed_waiver_expiry_date",
            "premium_waiver_scope": (
                "main_contract_and_attached_riders"
            ),
            "premium_waiver_allocation_order": (
                "attached_rider_premiums_then_main_contract_premium"
            ),
            "premium_waiver_amount_excludes": [
                "this_rider_premium",
                "account_type_rider_coverage_premium",
            ],
            "premium_waiver_requires_remaining_premium_amount": True,
            "waiver_is_non_cash_effect": True,
            "cash_payout_available": False,
            "current_unexpired_premium_refund_available": False,
            "rider_terminates_after_waiver": True,
            "waiver_continues_after_rider_termination": True,
            "required_policy_inputs": [
                "remaining_premium_amount"
            ],
            "claim_event_inputs": [
                "policy_effect_status_at_event",
                "insured_event_type",
                "event_or_diagnosis_date",
                "waiting_period_or_injury_confirmation",
                "disability_or_impairment_grade",
                "critical_illness_exact_version_confirmation",
                "waiver_approval_date",
                "agreed_waiver_expiry_date",
            ],
            "amount_presentation": (
                "remaining_premium_policy_state_non_cash_effect"
            ),
        },
        "coverage_entries": (
            allianz_new_peace_of_mind_premium_waiver_entries(
                disability_term=disability_term
            )
        ),
    }


