def parse_fubon_premium_waiver_rider_policy_state(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_fubon_premium_waiver_rider_strict_source(document):
        return None
    product_id = str(document.get("product_id") or "")
    version = FUBON_PREMIUM_WAIVER_RIDER_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None

    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version["source_text_sha256"]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    universal_signals = (
        "富邦人壽保險費豁免附約條款",
        "本保險費豁免附約須附加在主契約上",
        "豁免下列二款之保險費",
        "一百八十日內者",
        "一百八十日之後者",
        "退還已收保險費",
    )
    if any(signal not in dense_text for signal in universal_signals):
        return None

    revision = int(version["revision"])
    latest_refund_signal = "逐期退還要保人"
    if revision <= 8:
        if (
            "【給付項目:失能豁免保費】" not in dense_text
            or "原子或核子能設備" not in dense_text
            or latest_refund_signal in dense_text
        ):
            return None
        incapacity_term = "失能"
        exclusion_revision = "legacy_war_nuclear_and_two_year_conduct"
    elif revision <= 11:
        if (
            "【給付項目:喪失工作能力豁免保費】" not in dense_text
            or "原子或核子能設備" not in dense_text
            or latest_refund_signal in dense_text
        ):
            return None
        incapacity_term = "喪失工作能力"
        exclusion_revision = "legacy_war_nuclear_and_two_year_conduct"
    else:
        if (
            "【給付項目:喪失工作能力豁免保費】" not in dense_text
            or "非法施用防制毒品相關法令所稱之毒品" not in dense_text
        ):
            return None
        incapacity_term = "喪失工作能力"
        exclusion_revision = "intentional_criminal_and_illegal_drug_use"
    if revision >= 13:
        latest_signals = (
            "未到期保險費無息退還要保人",
            latest_refund_signal,
            "豁免前後之應繳保險費比例",
        )
        if any(signal not in dense_text for signal in latest_signals):
            return None
    elif latest_refund_signal in dense_text:
        return None

    latest_refund_version = revision >= 13
    required_policy_inputs = [
        "fubon_premium_waiver_eligibility_status",
        "fubon_premium_waiver_collected_refund_amount",
        "remaining_premium_amount",
        *(
            [
                "fubon_premium_waiver_current_refund_status",
                "unexpired_premium_refund_amount",
                "fubon_premium_waiver_overlap_status",
                "fubon_premium_waiver_overlap_refund_amount",
            ]
            if latest_refund_version
            else []
        ),
    ]
    source_ref = "第二章第二條喪失工作能力豁免保費"
    return {
        "selection_type": "policy_state",
        "input_mode": "policy_state",
        "selection_source": "terms",
        "selection_label": "工作能力狀態與保費金額",
        "selection_guidance": (
            "先確認疾病或意外造成不能從事一切工作且不能取得工作報酬，"
            "並已持續超過一百八十日未治癒；再依保單或保險公司核定金額填入返還及豁免保費。"
        ),
        "plan_options": [],
        "version_characteristics": {
            "source_product_id": product_id,
            "family_fingerprint": "80ee9daa763499a2d5c34fb7",
            "product_family": "fubon-premium-waiver-rider",
            "company_group": "fubon_life",
            "source_batch_id": "tii-life-050",
            "terms_revision": f"partial_change_{revision}",
            "semantic_phase": (
                fubon_premium_waiver_rider_semantic_phase(revision)
            ),
            "source_document_sha256": version[
                "source_document_sha256"
            ],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version["source_text_extractor"],
            "source_text_quality": (
                "machine_readable_exact_hash_with_duplicate_source_versions"
                if revision in {15, 16}
                else "machine_readable_exact_hash"
            ),
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "rider": True,
            "main_insured_must_be_policyholder": True,
            "incapacity_term": incapacity_term,
            "incapacity_definition": (
                "unable_to_perform_all_work_and_earn_remuneration"
            ),
            "continuous_incapacity_days_required": 180,
            "waiver_start_basis": (
                "retroactive_from_diagnosis_after_more_than_180_days_uncured"
            ),
            "collected_premium_refund_within_180_days_available": True,
            "collected_premium_refund_beneficiary": (
                "policyholder" if latest_refund_version else "insured"
            ),
            "future_premium_waiver_available": True,
            "premium_waiver_scope": (
                "main_contract_this_rider_and_other_attached_riders"
            ),
            "premium_waiver_until": (
                "age_60_first_rider_anniversary_or_main_payment_end_unless_qualified"
            ),
            "current_unexpired_premium_refund_available": (
                latest_refund_version
            ),
            "current_unexpired_premium_refund_formula": (
                "current_paid_premiums_minus_elapsed_day_proration"
                if latest_refund_version
                else None
            ),
            "overlapping_waiver_periodic_refund_available": (
                latest_refund_version
            ),
            "overlapping_waiver_refund_basis": (
                "other_contract_waived_renewal_premiums_refunded_each_period"
                if latest_refund_version
                else None
            ),
            "other_waiver_first_reduces_future_scope_and_rider_premium": (
                latest_refund_version
            ),
            "exclusion_revision": exclusion_revision,
            "death_benefit_available": False,
            "waiver_is_non_cash_effect": True,
            "required_policy_inputs": required_policy_inputs,
            "amount_presentation": (
                "policy_or_insurer_confirmed_premiums_and_non_cash_waiver_effect"
            ),
        },
        "coverage_entries": fubon_premium_waiver_rider_entries(
            revision=revision,
            source_ref=source_ref,
        ),
    }


