def is_global_inpatient_medical_fixed_rider_strict_source(
    document: dict[str, Any],
) -> bool:
    product_id = str(document.get("product_id") or "")
    version = GLOBAL_INPATIENT_MEDICAL_FIXED_RIDER_VERSIONS.get(product_id)
    return bool(
        version
        and str(document.get("batch_id") or "") == "tii-life-164"
        and document.get("document_type") == "policy_terms"
        and str(document.get("file_name") or "").lower()
        == str(version["file_name"]).lower()
    )


def global_inpatient_medical_fixed_rider_semantic_phase(
    revision: int,
) -> str:
    if revision == 0:
        return "legacy_policy_recorded_amounts"
    if revision == 1:
        return "legacy_policy_recorded_amounts_with_refund"
    if revision == 2:
        return "twelve_plan_terms_table"
    if revision <= 5:
        return "ten_plan_same_hospital_policy_year"
    if revision == 6:
        return "newborn_screening_waiting_exception"
    if revision == 7:
        return "post_expiry_readmission_exclusion"
    if revision <= 9:
        return "day_hospital_exclusion_disability_wording"
    if revision <= 12:
        return "day_hospital_exclusion_impairment_wording"
    return "updated_day_stay_day_care_wording"


def global_inpatient_medical_fixed_rider_eligibility(
    revision: int,
) -> dict[str, Any]:
    ineligible = ["disease_waiting_not_met", "confirmed_not_eligible"]
    if revision < 6:
        ineligible.append("eligible_newborn_screening_exception")
    uncertain = ["uncertain"]
    if revision < 8:
        uncertain.append("day_hospital_or_day_stay")
    else:
        ineligible.append("day_hospital_or_day_stay")
    return {
        "eligibility_state_key": "global_fixed_hospital_event_status",
        "ineligible_values": ineligible,
        "uncertain_values": uncertain,
    }


def global_inpatient_medical_fixed_rider_entries(
    *,
    revision: int,
    hospital_daily_amount: int | None,
    intensive_care_daily_amount: int | None,
    burn_daily_amount: int | None,
    surgery_base_amount: int | None,
    policy_recorded: bool,
) -> list[dict[str, Any]]:
    eligibility = global_inpatient_medical_fixed_rider_eligibility(revision)

    def daily_entry(
        entry_id: str,
        name: str,
        amount: int | None,
        policy_key: str,
        quantity_key: str,
        quantity_cap: int,
    ) -> dict[str, Any]:
        common = dict(
            calculation_basis=(
                "policy_state_amount" if policy_recorded else "per_day"
            ),
            amount_role="payout",
            limit_scope="per_day",
            aggregation_rule="separate",
            quantity_state_key=quantity_key,
            quantity_cap=quantity_cap,
            result_kind="cash_payout",
            amount_stage="gross_contract_benefit",
            conditions=[
                f"每次給付最多計 {quantity_cap} 日。",
                "同一疾病或傷害出院後十四日內再次住院，視為同一次住院。",
            ],
            **eligibility,
        )
        if policy_recorded:
            common.update(
                unit_key=policy_key,
                policy_state_keys=[policy_key],
            )
        return coverage_entry(
            entry_id,
            name,
            amount,
            "policy_recorded_limit" if policy_recorded else "daily_total",
            (
                "早期條款未列計畫金額，依保單記載日額乘符合條款的日數。"
                if policy_recorded
                else f"依所選計畫每日 {amount:,} 元乘符合條款的日數。"
            ),
            "保單條款給付條文及計畫表",
            **common,
        )

    entries = [
        daily_entry(
            "hospital-daily-benefit",
            "住院日額保險金",
            hospital_daily_amount,
            "hospital_daily_amount",
            "hospitalization_days",
            365,
        ),
        daily_entry(
            "intensive-care-daily-benefit",
            "加護病房日額補助保險金",
            intensive_care_daily_amount,
            "global_fixed_icu_daily_amount",
            "intensive_care_days",
            30,
        ),
        daily_entry(
            "burn-unit-daily-benefit",
            "燒燙傷病房日額補助保險金",
            burn_daily_amount,
            "global_fixed_burn_daily_amount",
            "burn_unit_days",
            60,
        ),
    ]
    surgery_args: dict[str, Any] = {
        "calculation_basis": "percentage_of_base",
        "amount_role": "payout",
        "limit_scope": "per_surgery",
        "aggregation_rule": "separate",
        "rate_state_key": "surgery_benefit_rate_percent",
        "rate_min_percent": 5,
        "rate_max_percent": 300,
        "result_kind": "cash_payout",
        "amount_stage": "gross_contract_benefit",
        "conditions": [
            "同一手術位置接受兩項以上手術時，只給付附表比例最高一項。",
            "不同手術分別計算；同一次住院或同一保單年度合計最高為手術基準額三倍。",
        ],
        **eligibility,
    }
    if policy_recorded:
        surgery_args.update(
            unit_key="global_fixed_surgery_base_amount",
            policy_state_keys=["global_fixed_surgery_base_amount"],
        )
    entries.append(
        coverage_entry(
            "surgery-fixed-benefit",
            "外科手術定額保險金",
            surgery_base_amount,
            "policy_recorded_limit" if policy_recorded else "benefit_base",
            "以手術基準額乘本 product ID 條款附表比例計算。",
            "保單條款外科手術給付條文及手術項目給付比例表",
            **surgery_args,
        )
    )
    cap_args: dict[str, Any] = dict(
        calculation_basis=(
            "policy_state_amount" if policy_recorded else "aggregate_cap"
        ),
        amount_role="limit",
        limit_scope="per_hospitalization",
        aggregation_rule="cumulative_cap",
        result_kind="reference",
        amount_stage="not_applicable",
    )
    if policy_recorded:
        cap_args.update(
            rate_percent=300,
            unit_key="global_fixed_surgery_base_amount",
            policy_state_keys=["global_fixed_surgery_base_amount"],
        )
    entries.append(
        coverage_entry(
            "surgery-aggregate-cap",
            "同一次住院／同一保單年度手術給付上限",
            None if policy_recorded else int(surgery_base_amount or 0) * 3,
            (
                "policy_recorded_limit"
                if policy_recorded
                else "per_hospitalization_limit"
            ),
            "條款明定手術保險金合計最高為手術基準額三倍。",
            "保單條款外科手術給付上限",
            **cap_args,
        )
    )
    if revision >= 1:
        entries.append(
            coverage_entry(
                "unexpired-premium-refund",
                "契約終止未滿期保險費返還",
                None,
                "policy_recorded_limit",
                "依條款按未到期日數比例返還，金額以保險公司列示為準。",
                "保單條款契約終止及未滿期保險費返還",
                calculation_basis="policy_state_amount",
                amount_role="payout",
                limit_scope="per_policy",
                unit_key="unexpired_premium_refund_amount",
                policy_state_keys=["unexpired_premium_refund_amount"],
                result_kind="cash_payout",
                amount_stage="insurer_quoted_amount",
            )
        )
    return entries


