def parse_global_inpatient_medical_fixed_rider_plan(
    document: dict[str, Any],
) -> dict[str, Any] | None:
    if not is_global_inpatient_medical_fixed_rider_strict_source(document):
        return None
    product_id = str(document.get("product_id") or "")
    version = GLOBAL_INPATIENT_MEDICAL_FIXED_RIDER_VERSIONS[product_id]
    if (
        document.get("page_count") != version["page_count"]
        or document.get("pages_parsed") != version["page_count"]
        or str(document.get("source_document_sha256") or "")
        != version["source_document_sha256"]
        or str(document.get("source_text_extractor") or "")
        != version["source_text_extractor"]
    ):
        return None
    text = normalize_terms_text(str(document.get("text") or ""))
    if sha256_bytes(text.encode("utf-8")) != version["source_text_sha256"]:
        return None
    dense_text = re.sub(r"\s+", "", text)
    if any(
        signal not in dense_text
        for signal in (
            "定額型",
            "住院日額保險",
            "外科手術定額保險",
            "加護病房日額補助保險",
            "燒燙傷病房日額補助保險",
        )
    ):
        return None

    revision = int(version["revision"])
    policy_recorded = revision <= 1
    plan_count = 0 if policy_recorded else 12 if revision == 2 else 10
    required_policy_inputs = (
        [
            "hospital_daily_amount",
            "global_fixed_icu_daily_amount",
            "global_fixed_burn_daily_amount",
            "global_fixed_surgery_base_amount",
        ]
        if policy_recorded
        else ["plan_name"]
    )
    claim_inputs = [
        "global_fixed_hospital_event_status",
        "hospitalization_days",
        "intensive_care_days",
        "burn_unit_days",
        "surgery_benefit_rate_percent",
    ]
    if revision >= 1:
        claim_inputs.append("unexpired_premium_refund_amount")
    result: dict[str, Any] = {
        "selection_type": "policy_state" if policy_recorded else "plan",
        "input_mode": "policy_state" if policy_recorded else "plan",
        "selection_source": "terms",
        "selection_label": "保單記載金額" if policy_recorded else "計畫別",
        "selection_guidance": (
            "早期版本條款未列計畫金額，請依保單首頁、保險證或批註填入四項記載金額。"
            if policy_recorded
            else "請依保單選擇 HI 計畫；金額由這個 product ID 的條款計畫表帶入，不需輸入單位數。"
        ),
        "version_characteristics": {
            "source_product_id": product_id,
            "product_family": "global-inpatient-medical-fixed-rider",
            "family_fingerprint": GLOBAL_INPATIENT_MEDICAL_FIXED_RIDER_FINGERPRINT,
            "company_group": "global_life",
            "source_batch_id": "tii-life-164",
            "terms_revision": "original" if revision == 0 else f"partial_change_{revision}",
            "semantic_phase": global_inpatient_medical_fixed_rider_semantic_phase(revision),
            "source_document_sha256": version["source_document_sha256"],
            "source_text_sha256": version["source_text_sha256"],
            "source_text_extractor": version["source_text_extractor"],
            "source_text_quality": "machine_readable_exact_hash",
            "source_page_count": version["page_count"],
            "currency_basis": "twd",
            "group_policy": False,
            "plan_table_in_terms": not policy_recorded,
            "plan_option_count": plan_count,
            "legacy_policy_recorded_amounts_required": policy_recorded,
            "unit_count_required": False,
            "disease_waiting_days": 30,
            "accident_waiting_period_exempt": True,
            "newborn_screening_waiting_exception": revision >= 6,
            "same_hospitalization_policy_year_wording": revision >= 3,
            "post_expiry_readmission_excluded": revision >= 7,
            "day_hospital_excluded": revision >= 8,
            "disability_terminology": "失能" if revision >= 10 else "殘廢",
            "hospital_daily_day_limit": 365,
            "intensive_care_day_limit": 30,
            "burn_unit_day_limit": 60,
            "surgery_rate_min_percent": 5,
            "surgery_rate_max_percent": 300,
            "surgery_aggregate_limit_multiplier": 3,
            "same_location_surgery_rule": "highest_rate_only",
            "distinct_surgeries_rule": "calculate_separately",
            "death_cash_benefit_available": False,
            "disability_cash_benefit_available": False,
            "outpatient_medical_benefit_available": False,
            "discharge_recovery_benefit_available": False,
            "maturity_benefit_available": False,
            "premium_waiver_available": False,
            "contract_termination_unexpired_premium_refund": revision >= 1,
            "required_policy_inputs": required_policy_inputs,
            "claim_event_inputs": claim_inputs,
            "amount_presentation": (
                "policy_recorded_amounts_with_claim_inputs"
                if policy_recorded
                else "selected_plan_amounts_with_claim_inputs"
            ),
        },
    }
    if policy_recorded:
        result["coverage_entries"] = global_inpatient_medical_fixed_rider_entries(
            revision=revision,
            hospital_daily_amount=None,
            intensive_care_daily_amount=None,
            burn_daily_amount=None,
            surgery_base_amount=None,
            policy_recorded=True,
        )
    else:
        result["plan_options"] = []
        for index in range(plan_count):
            daily = (index + 1) * 500
            plan_code = f"HI-{(index + 1) * 5:02d}"
            result["plan_options"].append(
                {
                    "value": plan_code,
                    "label": f"{plan_code} {GLOBAL_INPATIENT_MEDICAL_FIXED_PLAN_LABELS[index]}",
                    "coverage_entries": global_inpatient_medical_fixed_rider_entries(
                        revision=revision,
                        hospital_daily_amount=daily,
                        intensive_care_daily_amount=daily * 2,
                        burn_daily_amount=daily * 2,
                        surgery_base_amount=daily * 15,
                        policy_recorded=False,
                    ),
                }
            )
    return result


